registerClass12ExerciseBanks("quran", {"1":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l1-exercise-17",2]],"o":[["mq12-l1-exercise-17",3],["mq12-l1-exercise-17",4],["mq12-l1-exercise-17",5],["mq12-l1-exercise-17",6]],"s":["«يٰٓاَيُّهَا النَّاسُ اتَّقُوْا رَبَّكُمُ» — اے لوگو! اپنے رب سے ڈرو؛ یعنی تقویٰ (اللہ سے ڈرنے) کا حکم دیا گیا ہے۔"],"c":2},{"q":[["mq12-l1-exercise-17",7]],"o":[["mq12-l1-exercise-17",8],["mq12-l1-exercise-17",9],["mq12-l1-exercise-17",10],["mq12-l1-exercise-17",11]],"s":["«وَاٰتُوا النِّسَآءَ صَدُقٰتِهِنَّ نِحْلَةً» — عورتوں کو ان کے مہر خوش دلی سے ادا کرو؛ \"صدقات\" سے مراد مہر ہے۔"],"c":3},{"q":[["mq12-l1-exercise-17",12]],"o":[["mq12-l1-exercise-17",13],["mq12-l1-exercise-17",14],["mq12-l1-exercise-17",15],["mq12-l1-exercise-17",16]],"s":["جو لوگ ظلم سے یتیموں کا مال کھاتے ہیں وہ اپنے پیٹوں میں آگ بھرتے ہیں اور عنقریب بھڑکتی آگ میں داخل ہوں گے (آیت 10)۔"],"c":2},{"q":[["mq12-l1-exercise-17",17]],"o":[["mq12-l1-exercise-17",18],["mq12-l1-exercise-17",19],["mq12-l1-exercise-17",20],["mq12-l1-exercise-17",21]],"s":["«لِلذَّكَرِ مِثْلُ حَظِّ الْاُنْثَيَيْنِ» — بیٹے کا حصہ دو بیٹیوں کے برابر ہے (آیت 11)۔"],"c":1},{"q":[["mq12-l1-exercise-17",22]],"o":[["mq12-l1-exercise-17",23],["mq12-l1-exercise-17",24],["mq12-l1-exercise-17",25],["mq12-l1-exercise-17",26]],"s":["«وَلَهُنَّ الرُّبُعُ…» — اولاد نہ ہو تو بیوی (بیویوں) کا حصہ ترکے کا چوتھائی ہے؛ اولاد ہو تو آٹھواں (آیت 12)۔"],"c":1},{"q":[["mq12-l1-exercise-17",27]],"o":[["mq12-l1-exercise-17",28],["mq12-l1-exercise-17",29],["mq12-l1-exercise-17",30],["mq12-l1-exercise-17",31]],"s":["«وَالْمُحْصَنٰتُ» سے مراد شوہر والی (شادی شدہ) عورتیں ہیں جن سے نکاح حرام ہے (آیت 24)۔"],"c":2},{"q":[["mq12-l1-exercise-17",32]],"o":[["mq12-l1-exercise-17",33],["mq12-l1-exercise-17",34],["mq12-l1-exercise-17",35],["mq12-l1-exercise-17",36]],"s":["«مُتَّخِذٰتِ اَخْدَانٍ» — چوری چھپے آشنائی (خفیہ دوستی) رکھنے والی عورتیں (آیت 25)۔"],"c":0}],"objective":[{"q":[["mq12-l1-exercise-18",12]],"s":["جن عورتوں سے نکاح حرام ہے (آیات 22–24): باپ کی منکوحہ (سوتیلی ماں)، مائیں، بیٹیاں، بہنیں، پھوپھیاں، خالائیں، بھتیجیاں، بھانجیاں، رضاعی مائیں، رضاعی بہنیں، ساس، وہ سوتیلی بیٹیاں جن کی ماں سے صحبت ہو چکی ہو، سگے بیٹوں کی بیویاں (بہوئیں)، دو بہنوں کو ایک ساتھ نکاح میں جمع کرنا، اور شوہر والی عورتیں۔","جن عورتوں سے نکاح جائز ہے: ان کے علاوہ باقی تمام عورتیں، بشرطیکہ مہر ادا کر کے نکاح کیا جائے، مقصد پاک دامنی ہو نہ کہ بدکاری؛ آزاد مومن عورت سے نکاح کی استطاعت نہ ہو تو مومن کنیز سے اس کے مالکوں کی اجازت اور مہر کے ساتھ (آیات 24–25)۔"]}],"shortQuestions":[{"q":[["mq12-l1-exercise-17",38]],"s":["آیت بتاتی ہے کہ اللہ نے تمام انسانوں کو ایک جان (حضرت آدمؑ) سے پیدا کیا، اسی سے اس کا جوڑا (حضرت حواؑ) بنایا اور ان دونوں سے بہت سے مرد اور عورتیں پھیلا دیں — یعنی پوری انسانیت ایک ہی ماں باپ کی اولاد ہے اور سب برابر ہیں۔"]},{"q":[["mq12-l1-exercise-17",39]],"s":["یتیموں کا مال اپنے مال کے ساتھ ملا کر کھا جانا (یا اچھی چیز کو بری سے بدل لینا) بہت بڑا گناہ قرار دیا گیا ہے۔"]},{"q":[["mq12-l1-exercise-17",40]],"s":["اگر اندیشہ ہو کہ ایک سے زیادہ بیویوں کے درمیان انصاف (برابری کا سلوک) نہیں کر سکو گے تو ایک ہی نکاح پر اکتفا کرو۔"]},{"q":[["mq12-l1-exercise-17",41]],"s":["جب یتیم نکاح کی عمر (بلوغت) کو پہنچ جائیں اور ان میں سمجھ داری (مال سنبھالنے کی صلاحیت، رُشد) پاؤ تو ان کا مال ان کے حوالے کر دو؛ ان کے بڑے ہونے کے ڈر سے جلدی جلدی ان کا مال نہ کھاؤ۔"]},{"q":[["mq12-l1-exercise-17",42]],"s":["تقسیمِ وراثت کے وقت اگر وہ رشتہ دار جو وارث نہیں، یتیم اور مسکین موجود ہوں تو انہیں بھی اس میں سے کچھ دے دو اور ان سے نرمی اور بھلائی کی بات کہو۔"]},{"q":[["mq12-l1-exercise-18",0]],"s":["بیوی کی اولاد نہ ہو تو شوہر کو اس کے ترکے کا آدھا حصہ ملتا ہے؛ اگر اولاد ہو تو چوتھائی (وصیت اور قرض کی ادائیگی کے بعد)۔"]},{"q":[["mq12-l1-exercise-18",1]],"s":["جو شخص اللہ اور اس کے رسول کی نافرمانی کرے اور اللہ کی مقرر کردہ حدوں (مثلاً وراثت کے حصوں) سے تجاوز کرے، اسے اللہ آگ میں داخل کرے گا جہاں وہ ہمیشہ رہے گا اور اس کے لیے ذلت والا عذاب ہے۔"]}],"longQuestions":[{"q":[["mq12-l1-exercise-18",3]],"s":["ترجمہ: اور اپنے وہ مال جنہیں اللہ نے تمہارے لیے گزران کا ذریعہ بنایا ہے، نادانوں (کم عقلوں) کے حوالے نہ کرو، البتہ اس میں سے انہیں کھلاؤ اور پہناؤ اور ان سے بھلائی کی بات کہو۔ (النساء 5)","تشریح: مال زندگی کے قیام کا ذریعہ ہے، اسے ایسے لوگوں کے سپرد نہ کیا جائے جو اسے ضائع کر دیں (نابالغ یتیم یا کم عقل)؛ سرپرست ان کی ضروریات پوری کرے اور ان سے نرمی سے بات کرے۔"]},{"q":[["mq12-l1-exercise-18",4]],"s":["سورۃ النساء مدنی سورت ہے؛ اس میں 176 آیات اور 24 رکوع ہیں؛ ترتیب میں چوتھی سورت ہے؛ اس کا بڑا حصہ 3ھ سے 5ھ کے درمیان (غزوۂ احد کے بعد) نازل ہوا۔","نام: اس میں عورتوں کے حقوق اور مسائل کثرت سے بیان ہوئے ہیں، اس لیے \"النساء\" (عورتیں) کہلائی۔","پس منظر: غزوۂ احد کے بعد بہت سے مسلمان شہید ہوئے جس سے یتیموں اور بیواؤں کے مسائل اور ترکے کی تقسیم کی ضرورت پیدا ہوئی؛ اسلامی معاشرے کی تنظیم، خاندان کے استحکام اور منافقین و اہلِ کتاب کے رویے کی اصلاح اس سورت کا موضوع ہے۔"]},{"q":[["mq12-l1-exercise-18",5]],"s":["ترجمہ: اور ان لوگوں کو ڈرنا چاہیے جو اگر اپنے پیچھے کمزور (بے سہارا) اولاد چھوڑ جائیں تو انہیں ان کے بارے میں اندیشہ ہو؛ پس انہیں چاہیے کہ اللہ سے ڈریں اور سیدھی (درست) بات کہیں۔ (النساء 9)","تشریح: یتیموں کے سرپرست اور وصیت کرنے والے یہ سوچیں کہ اگر ان کی اپنی اولاد یتیم رہ جائے تو وہ ان کے ساتھ کیسا سلوک چاہیں گے؛ وہی سلوک دوسروں کے یتیموں سے کریں اور انصاف کی بات کہیں۔"]},{"q":[["mq12-l1-exercise-18",6]],"s":["سورۃ النساء کے بنیادی مضامین: (1) یتیموں کے حقوق اور ان کے مال کی حفاظت؛ (2) عورتوں کے حقوق — مہر، نکاح، تعددِ ازدواج کی شرط (عدل)، محرمات؛ (3) وراثت کے تفصیلی احکام اور حصے۔","(4) خاندانی نظام — میاں بیوی کے حقوق، اختلاف کی صورت میں ثالثی؛ (5) عدل و انصاف، امانتیں اہل کے سپرد کرنا، اللہ، رسول اور اولی الامر کی اطاعت۔","(6) جہاد، ہجرت اور صلوٰۃ الخوف کے احکام؛ (7) منافقین کی علامات اور ان کا انجام؛ (8) اہلِ کتاب (یہود و نصاریٰ) کے غلط عقائد کا رد — تثلیث کی تردید اور حضرت عیسیٰؑ کی حیثیت؛ (9) کلالہ کی میراث (آخری آیت)۔"]},{"q":[["mq12-l1-exercise-18",7]],"s":["ترجمہ: یہ اللہ کی (مقرر کردہ) حدیں ہیں؛ اور جو اللہ اور اس کے رسول کی اطاعت کرے گا، اللہ اسے ایسے باغوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہیں، وہ ان میں ہمیشہ رہیں گے؛ اور یہی بڑی کامیابی ہے۔ (النساء 13)","تشریح: وراثت کے حصے اللہ کی مقرر کردہ حدیں ہیں؛ ان کی پابندی اللہ اور رسول کی اطاعت ہے جس کا انعام جنت ہے، جبکہ ان سے تجاوز کا انجام ذلت والا عذاب (آیت 14)۔"]},{"q":[["mq12-l1-exercise-18",8]],"s":["آیت نے اُن عورتوں سے نکاح کرنے سے منع کیا ہے جن سے تمہارے باپ نکاح کر چکے ہوں (سوتیلی ماں)، سوائے اس کے جو پہلے (جاہلیت میں) ہو چکا۔","اس کی مذمت تین الفاظ میں کی گئی: «فَاحِشَةً» — بے حیائی کا کام، «مَقْتًا» — اللہ کے نزدیک نہایت قابلِ نفرت (غضب کا باعث)، اور «سَآءَ سَبِيْلًا» — بہت برا راستہ؛ جاہلیت میں باپ کی بیوہ سے نکاح کا رواج تھا جسے ختم کر دیا گیا۔"]}],"activities":[{"q":[["mq12-l1-exercise-18",10],["mq12-l1-exercise-18",11]],"s":["یتیموں سے متعلق احکام کی فہرست: (1) یتیموں کا مال انہیں دو؛ (2) اچھی چیز کو بری سے نہ بدلو؛ (3) ان کا مال اپنے مال میں ملا کر نہ کھاؤ؛ (4) یتیم لڑکیوں سے انصاف نہ کر سکو تو ان سے نکاح نہ کرو؛ (5) نادان یتیم کو مال نہ دو مگر اس میں سے کھلاؤ پہناؤ؛ (6) بلوغت اور سمجھ داری کے بعد مال حوالے کرو، گواہ بناؤ؛ (7) فضول خرچی اور جلدی سے مال نہ کھاؤ؛ (8) مال دار سرپرست اجرت نہ لے، محتاج دستور کے مطابق لے؛ (9) تقسیمِ ترکہ پر یتیموں کو بھی کچھ دو؛ (10) ظلم سے یتیم کا مال کھانا پیٹ میں آگ بھرنا ہے۔","وراثت کا چارٹ (آیات 11–12): بیٹا = دو بیٹیوں کے برابر؛ صرف بیٹیاں (دو یا زیادہ) = 2/3؛ ایک بیٹی = 1/2؛ والدین (اولاد ہو تو) = ہر ایک 1/6؛ اولاد نہ ہو، صرف والدین وارث = ماں 1/3 (بہن بھائی ہوں تو 1/6)، باقی باپ؛ شوہر = 1/2 (اولاد نہ ہو)، 1/4 (اولاد ہو)؛ بیوی = 1/4 (اولاد نہ ہو)، 1/8 (اولاد ہو)؛ کلالہ کے اخیافی بھائی یا بہن = ایک ہو تو 1/6، زیادہ ہوں تو 1/3 میں شریک — سب حصے وصیت اور قرض کے بعد۔"]}]}},"2":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l2-exercise-26",3]],"o":[["mq12-l2-exercise-26",4],["mq12-l2-exercise-26",5],["mq12-l2-exercise-26",6],["mq12-l2-exercise-26",7]],"s":["«وَخُلِقَ الْاِنْسَانُ ضَعِيْفًا» — انسان کمزور پیدا کیا گیا ہے، اسی لیے اللہ احکام میں آسانی چاہتا ہے (آیت 28)۔"],"c":1},{"q":[["mq12-l2-exercise-26",8]],"o":[["mq12-l2-exercise-26",9],["mq12-l2-exercise-26",10],["mq12-l2-exercise-26",11],["mq12-l2-exercise-26",12]],"s":["«قَوّٰمُوْنَ» — نگہبان، محافظ اور منتظم؛ مرد عورتوں کے نگران (قوام) ہیں (آیت 34)۔"],"c":2},{"q":[["mq12-l2-exercise-26",13]],"o":[["mq12-l2-exercise-26",14],["mq12-l2-exercise-26",15],["mq12-l2-exercise-26",16],["mq12-l2-exercise-26",17]],"s":["«سُكٰرٰى» — نشے کی حالت میں؛ نشے کی حالت میں نماز کے قریب نہ جاؤ (آیت 43)۔"],"c":2},{"q":[["mq12-l2-exercise-26",18]],"o":[["mq12-l2-exercise-26",19],["mq12-l2-exercise-26",20],["mq12-l2-exercise-26",21],["mq12-l2-exercise-26",22]],"s":["«يُزَكِّيْ» — پاکیزگی عطا کرتا ہے؛ اللہ جسے چاہتا ہے پاک کرتا ہے، اپنی پاکیزگی کا دعویٰ کرنے والوں کی بات معتبر نہیں (آیت 49)۔"],"c":2},{"q":[["mq12-l2-exercise-27",0]],"o":[["mq12-l2-exercise-27",1],["mq12-l2-exercise-27",2],["mq12-l2-exercise-27",3],["mq12-l2-exercise-27",4]],"s":["«نَصِيْرًا» — مددگار؛ جس پر اللہ لعنت کرے اس کا کوئی مددگار نہیں پاؤ گے (آیت 52)۔"],"c":3},{"q":[["mq12-l2-exercise-27",5]],"o":[["mq12-l2-exercise-27",6],["mq12-l2-exercise-27",7],["mq12-l2-exercise-27",8],["mq12-l2-exercise-27",9]],"s":["«يَعِظُكُمْ» — وہ تمہیں نصیحت کرتا ہے (آیت 58)۔"],"c":1},{"q":[["mq12-l2-exercise-27",10]],"o":[["mq12-l2-exercise-27",11],["mq12-l2-exercise-27",12],["mq12-l2-exercise-27",13],["mq12-l2-exercise-27",14]],"s":["منافقین مصیبت آنے پر آپ ﷺ کے پاس آ کر اللہ کی قسمیں کھاتے کہ ہمارا ارادہ صرف بھلائی اور میل ملاپ کا تھا (آیت 62)۔"],"c":3}],"shortQuestions":[{"q":[["mq12-l2-exercise-27",16]],"s":["نیک بیویاں فرمانبردار (اللہ اور شوہر کی جائز اطاعت کرنے والی) ہوتی ہیں اور شوہر کی غیر موجودگی میں اللہ کی حفاظت سے اپنی عزت، گھر اور شوہر کے مال کی حفاظت کرتی ہیں۔"]},{"q":[["mq12-l2-exercise-27",17]],"s":["آیت میں حکم ہے: اللہ کی عبادت کرو اور اس کے ساتھ کسی کو شریک نہ کرو؛ والدین، رشتہ داروں، یتیموں، مسکینوں، قریبی اور اجنبی پڑوسی، ساتھ بیٹھنے والے ساتھی، مسافر اور غلاموں (ماتحتوں) کے ساتھ حسنِ سلوک کرو؛ اللہ اترانے اور شیخی بگھارنے والے کو پسند نہیں کرتا (آیت 36)۔"]},{"q":[["mq12-l2-exercise-27",18]],"s":["اللہ ذرہ برابر بھی ظلم نہیں کرتا؛ اگر نیکی ہو تو اسے کئی گنا بڑھا دیتا ہے اور اپنی طرف سے بڑا اجر عطا فرماتا ہے۔"]},{"q":[["mq12-l2-exercise-27",19]],"s":["قیامت کے دن کافر اور رسول کے نافرمان تمنا کریں گے کہ کاش زمین ان پر برابر کر دی جائے (وہ مٹی میں مل جائیں)، اور وہ اللہ سے کوئی بات چھپا نہ سکیں گے۔"]},{"q":[["mq12-l2-exercise-27",20]],"s":["ہماری آیات کا انکار کرنے والوں کو آگ میں جھونکا جائے گا؛ جب ان کی کھالیں جل کر پک جائیں گی تو ان کی جگہ دوسری کھالیں بدل دی جائیں گی تاکہ وہ عذاب کا مزہ چکھتے رہیں؛ اللہ غالب اور حکمت والا ہے۔"]},{"q":[["mq12-l2-exercise-27",21]],"s":["جب منافقوں سے کہا جاتا ہے کہ اللہ کے نازل کردہ حکم اور رسول کی طرف آؤ تو وہ آپ ﷺ سے رک جاتے اور منہ پھیر لیتے ہیں (اپنا فیصلہ طاغوت سے کرانا چاہتے ہیں)۔"]},{"q":[["mq12-l2-exercise-27",22]],"s":["کوئی شخص اس وقت تک مومن نہیں ہو سکتا جب تک اپنے تنازعات میں رسول اللہ ﷺ کو فیصل (حاکم) نہ مانے، پھر آپ کے فیصلے پر دل میں کوئی تنگی محسوس نہ کرے اور پوری طرح سرِ تسلیم خم کر دے۔"]}],"longQuestions":[{"q":[["mq12-l2-exercise-27",24]],"s":["ترجمہ: اللہ چاہتا ہے کہ تمہارے لیے (احکام) کھول کر بیان کرے اور تمہیں ان لوگوں کے طریقوں کی رہنمائی کرے جو تم سے پہلے گزرے، اور تم پر رحمت کے ساتھ توجہ فرمائے؛ اور اللہ جاننے والا، حکمت والا ہے۔ (النساء 26)","تشریح: نکاح و خاندان کے احکام بیان کرنے کا مقصد یہ ہے کہ تم انبیا اور نیک لوگوں کے صحیح راستے پر چلو اور اللہ تمہاری توبہ قبول کرے۔"]},{"q":[["mq12-l2-exercise-27",25]],"s":["اگر تم ان بڑے گناہوں سے بچتے رہو جن سے تمہیں منع کیا جاتا ہے تو اللہ تمہاری چھوٹی برائیاں (صغیرہ گناہ) معاف کر دے گا اور تمہیں عزت کی جگہ (جنت) میں داخل کرے گا۔ (النساء 31)","کبیرہ گناہ: شرک، والدین کی نافرمانی، ناحق قتل، زنا، سود، یتیم کا مال کھانا، جھوٹی گواہی وغیرہ؛ ان سے بچنا صغیرہ گناہوں کی معافی کا ذریعہ ہے۔"]},{"q":[["mq12-l2-exercise-27",26]],"s":["ترجمہ: اور ہر ایک کے لیے ہم نے اس ترکے کے وارث مقرر کر دیے ہیں جو والدین اور قریبی رشتہ دار چھوڑ جائیں؛ اور جن سے تمہارا عہد و پیمان ہو انہیں ان کا حصہ دو؛ بے شک اللہ ہر چیز پر گواہ ہے۔ (النساء 33)","تشریح: وراثت کے حصے اللہ نے مقرر کیے ہیں؛ ابتدا میں عقدِ مواخات کے حلیف بھی حصہ پاتے تھے جو بعد میں وراثت کی آیات سے منسوخ ہو کر وصیت یا حسنِ سلوک تک محدود ہو گیا۔"]},{"q":[["mq12-l2-exercise-28",0]],"s":["سبب: منافقین پر مصیبت ان کے اپنے کرتوتوں کی وجہ سے آتی ہے — یعنی رسول ﷺ کو چھوڑ کر طاغوت سے فیصلہ کرانا اور نافرمانی۔ (النساء 62)","ردِ عمل: پھر وہ آپ ﷺ کے پاس آ کر اللہ کی قسمیں کھاتے ہیں کہ ہمارا ارادہ تو صرف بھلائی اور (فریقین میں) میل ملاپ کا تھا — یعنی جھوٹی قسموں سے اپنی بدنیتی چھپاتے ہیں۔"]},{"q":[["mq12-l2-exercise-28",1]],"s":["ترجمہ: اور اگر ہم ان پر فرض کر دیتے کہ اپنے آپ کو قتل کرو یا اپنے گھروں سے نکل جاؤ تو ان میں سے تھوڑے ہی ایسا کرتے؛ اور اگر یہ وہ کرتے جس کی انہیں نصیحت کی جاتی ہے تو یہ ان کے لیے بہتر اور (ایمان میں) زیادہ ثابت قدمی کا باعث ہوتا۔ (النساء 66)","تشریح: اللہ نے مسلمانوں پر بنی اسرائیل جیسے سخت احکام نہیں رکھے؛ آسان احکام کی پابندی ہی ان کے لیے بہتر اور ایمان کی پختگی کا ذریعہ ہے۔"]},{"q":[["mq12-l2-exercise-28",2]],"s":["آیت بتاتی ہے کہ جو اللہ اور رسول کی اطاعت کرے گا وہ قیامت میں ان لوگوں کے ساتھ ہوگا جن پر اللہ نے انعام کیا: انبیا، صدیقین، شہدا اور صالحین — اور یہ کیا ہی اچھے رفیق ہیں۔ (النساء 69)","یعنی اطاعتِ رسول کا انعام جنت میں انبیا اور نیک لوگوں کی رفاقت ہے؛ یہی وہ لوگ ہیں جن کے راستے کی دعا ہم سورۃ الفاتحہ میں کرتے ہیں (صراط الذین انعمت علیہم)۔"]}],"activities":[{"q":[["mq12-l2-exercise-28",4],["mq12-l2-exercise-28",5]],"s":["تیمم کا حکم (النساء 43): پانی نہ ملے یا بیماری کی وجہ سے پانی کا استعمال نقصان دہ ہو تو پاک مٹی سے تیمم کرو۔","طریقہ: نیت کریں، بسم اللہ پڑھیں، دونوں ہاتھ پاک مٹی پر مار کر جھاڑیں اور پورے چہرے کا مسح کریں، پھر دوبارہ ہاتھ مار کر کہنیوں سمیت دونوں ہاتھوں کا مسح کریں؛ تیمم وضو اور غسل دونوں کا قائم مقام ہے اور پانی ملنے یا عذر ختم ہونے پر ٹوٹ جاتا ہے۔","اللہ کے انعام یافتہ بندے (آیت 69): انبیا — اللہ کے پیغام پہنچانے والے؛ صدیقین — سچائی کے اعلیٰ درجے پر فائز (حضرت ابوبکرؓ)؛ شہدا — اللہ کی راہ میں جان دینے والے؛ صالحین — نیک عمل کرنے والے۔ طلبہ ان کی صفات پر گفتگو کریں۔"]}]}},"3":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l3-exercise-35",3]],"o":[["mq12-l3-exercise-35",4],["mq12-l3-exercise-35",5],["mq12-l3-exercise-35",6],["mq12-l3-exercise-35",7]],"s":["«اَوِ انْفِرُوْا جَمِيْعًا» — یا سب اکٹھے ہو کر (جہاد کے لیے) نکلو؛ ٹولیوں میں یا سب ایک ساتھ (آیت 71)۔"],"c":2},{"q":[["mq12-l3-exercise-35",8]],"o":[["mq12-l3-exercise-35",9],["mq12-l3-exercise-35",10],["mq12-l3-exercise-35",11],["mq12-l3-exercise-35",12]],"s":["«مَوَدَّةٌ» — دوستی، محبت کا تعلق (آیت 73)۔"],"c":0},{"q":[["mq12-l3-exercise-35",13]],"o":[["mq12-l3-exercise-35",14],["mq12-l3-exercise-35",15],["mq12-l3-exercise-35",16],["mq12-l3-exercise-35",17]],"s":["«اِنَّ كَيْدَ الشَّيْطٰنِ كَانَ ضَعِيْفًا» — شیطان کی چال کمزور ہے (آیت 76)۔"],"c":1},{"q":[["mq12-l3-exercise-35",18]],"o":[["mq12-l3-exercise-35",19],["mq12-l3-exercise-35",20],["mq12-l3-exercise-35",21],["mq12-l3-exercise-35",22]],"s":["«وَاللّٰهُ يَكْتُبُ مَا يُبَيِّتُوْنَ» — منافق رات کو جو مشورے کرتے ہیں اللہ انہیں لکھ رہا ہے (آیت 81)۔"],"c":2},{"q":[["mq12-l3-exercise-36",0]],"o":[["mq12-l3-exercise-36",1],["mq12-l3-exercise-36",2],["mq12-l3-exercise-36",3],["mq12-l3-exercise-36",4]],"s":["«كِفْلٌ» — حصہ، بوجھ؛ بری سفارش کرنے والے کو اس کے بوجھ (گناہ) میں سے حصہ ملے گا (آیت 85)؛ اچھی سفارش پر \"نصیب\" (حصہ) کا لفظ آیا ہے۔"],"c":0},{"q":[["mq12-l3-exercise-36",5]],"o":[["mq12-l3-exercise-36",6],["mq12-l3-exercise-36",7],["mq12-l3-exercise-36",8],["mq12-l3-exercise-36",9]],"s":["«فَتَبَيَّنُوْا» — اچھی طرح تحقیق کر لو؛ اللہ کی راہ میں نکلو تو تصدیق کیے بغیر کسی کو کافر قرار نہ دو (آیت 94)۔"],"c":1},{"q":[["mq12-l3-exercise-36",10]],"o":[["mq12-l3-exercise-36",11],["mq12-l3-exercise-36",12],["mq12-l3-exercise-36",13],["mq12-l3-exercise-36",14]],"s":["«مُسْتَضْعَفِيْنَ» — کمزور، بے بس (مغلوب) لوگ (آیات 75، 97–98)۔"],"c":1}],"shortQuestions":[{"q":[["mq12-l3-exercise-36",16]],"s":["اے ایمان والو! اپنے بچاؤ کا سامان (ہتھیار اور احتیاط) لے لو، پھر (دشمن کے مقابلے کے لیے) دستوں کی صورت میں نکلو یا سب اکٹھے نکلو۔"]},{"q":[["mq12-l3-exercise-36",17]],"s":["جو شخص اللہ کی راہ میں لڑے، پھر قتل ہو جائے (شہید) یا غالب آ جائے (غازی)، دونوں صورتوں میں اللہ اسے بڑا اجر عطا فرمائے گا۔"]},{"q":[["mq12-l3-exercise-36",18]],"s":["موت ایک اٹل حقیقت ہے؛ تم جہاں کہیں بھی ہو موت تمہیں آ پکڑے گی، چاہے تم مضبوط اور بلند قلعوں میں ہو — اس لیے موت کے ڈر سے جہاد سے گریز بے معنی ہے۔"]},{"q":[["mq12-l3-exercise-36",19]],"s":["جو بھلائی (نعمت) تمہیں پہنچتی ہے وہ اللہ کے فضل سے ہے، اور جو برائی (مصیبت) پہنچتی ہے وہ تمہارے اپنے اعمال (کوتاہیوں) کا نتیجہ ہے — اگرچہ سب کچھ اللہ کی تقدیر سے ہوتا ہے۔"]},{"q":[["mq12-l3-exercise-36",20]],"s":["اگر اللہ کا فضل اور اس کی رحمت تم پر نہ ہوتی تو چند لوگوں کے سوا تم سب شیطان کی پیروی کرنے لگتے (افواہیں پھیلانے اور گمراہ ہونے میں)۔"]},{"q":[["mq12-l3-exercise-36",21]],"s":["آیت میں اللہ کی صفات: وہ معبودِ واحد ہے، اس کے سوا کوئی معبود نہیں؛ وہ سب کو قیامت کے دن جمع کرے گا جس میں کوئی شک نہیں؛ اور وہ سب سے زیادہ سچی بات کہنے والا ہے۔"]},{"q":[["mq12-l3-exercise-36",22]],"s":["جب اللہ کی راہ میں سفر (جہاد) کرو تو تحقیق کر لیا کرو؛ جو تمہیں سلام کرے (اسلام ظاہر کرے) اسے یہ نہ کہو کہ تم مومن نہیں — دنیا کا مال (غنیمت) حاصل کرنے کے لیے کسی کے ایمان کا انکار نہ کرو۔"]}],"longQuestions":[{"q":[["mq12-l3-exercise-36",24]],"s":["ترجمہ: اور تم میں کوئی ایسا بھی ہے جو ضرور دیر لگاتا (پیچھے رہ جاتا) ہے؛ پھر اگر تم پر کوئی مصیبت آ پڑے تو کہتا ہے: اللہ نے مجھ پر احسان کیا کہ میں ان کے ساتھ موجود نہ تھا۔ (النساء 72)","تشریح: یہ منافقین کا حال ہے جو جہاد سے جی چراتے اور مسلمانوں کی مصیبت پر خوش ہوتے ہیں۔"]},{"q":[["mq12-l3-exercise-36",25]],"s":["تقابل: ایمان والے اللہ کی راہ میں لڑتے ہیں جبکہ کافر طاغوت (شیطان اور باطل) کی راہ میں لڑتے ہیں؛ پس شیطان کے دوستوں سے لڑو۔ (النساء 76)","حقیقت: شیطان کی چال کمزور ہے — اللہ پر بھروسا رکھنے والے مومنوں کے سامنے باطل کی تدبیریں ناکام رہتی ہیں۔"]},{"q":[["mq12-l3-exercise-36",26]],"s":["ترجمہ: اور اگر تمہیں اللہ کا فضل (فتح اور غنیمت) حاصل ہو تو (وہی منافق) اس طرح کہتا ہے گویا تمہارے اور اس کے درمیان کوئی دوستی تھی ہی نہیں: کاش میں بھی ان کے ساتھ ہوتا تو بڑی کامیابی حاصل کرتا۔ (النساء 73)","تشریح: منافق کی نظر صرف دنیاوی فائدے پر ہوتی ہے؛ مصیبت میں الگ رہنا اور فائدے میں حصے کی تمنا اس کی علامت ہے۔"]},{"q":[["mq12-l3-exercise-36",27]],"s":["رسول اللہ ﷺ کو ہدایت دی گئی کہ آپ اللہ کی راہ میں لڑیں، آپ پر صرف آپ کی اپنی ذات کی ذمہ داری ہے، اور مومنوں کو (جہاد پر) ابھاریں؛ امید ہے اللہ کافروں کا زور روک دے گا۔ (النساء 84)","اللہ کی قوت سب سے زیادہ اور اس کی سزا سب سے سخت ہے — یعنی اگر کوئی ساتھ نہ دے تب بھی آپ ﷺ اپنا فریضہ انجام دیں، نتیجہ اللہ کے ہاتھ میں ہے۔"]},{"q":[["mq12-l3-exercise-36",28]],"s":["ترجمہ: پھر تمہیں کیا ہوا کہ منافقوں کے بارے میں تم دو گروہ بن گئے ہو، حالانکہ اللہ نے ان کے کرتوتوں کی وجہ سے انہیں الٹا پھیر دیا ہے؛ کیا تم اسے ہدایت دینا چاہتے ہو جسے اللہ نے گمراہ کر دیا؟ اور جسے اللہ گمراہ کر دے تم اس کے لیے کوئی راستہ نہیں پاؤ گے۔ (النساء 88)","تشریح: منافقوں کے بارے میں نرمی اور سختی پر مسلمانوں میں اختلاف ہوا تو بتایا گیا کہ ان کے اعمال نے انہیں کفر کی طرف لوٹا دیا ہے۔"]},{"q":[["mq12-l3-exercise-37",0]],"s":["جو کسی مومن کو جان بوجھ کر قتل کرے اس کی سزا جہنم ہے جس میں وہ ہمیشہ رہے گا، اس پر اللہ کا غضب اور لعنت ہے اور اللہ نے اس کے لیے بڑا عذاب تیار کر رکھا ہے۔ (النساء 93)","یہ قرآن کی سخت ترین وعیدوں میں سے ہے؛ دنیا میں اس کی سزا قصاص ہے؛ جبکہ غلطی سے قتل پر دیت اور کفارہ (غلام آزاد کرنا یا دو ماہ کے روزے) کا حکم ہے (آیت 92)۔"]}],"activities":[{"q":[["mq12-l3-exercise-37",2],["mq12-l3-exercise-37",3]],"s":["سلام کے فضائل و آداب: سلام کو عام کرنا جنت کا ذریعہ اور باہمی محبت کا سبب ہے؛ \"السلام علیکم\" کہنا اور جواب میں \"وعلیکم السلام و رحمۃ اللہ\" یعنی بہتر جواب دینا (النساء 86)؛ چھوٹا بڑے کو، سوار پیدل کو، چلنے والا بیٹھے ہوئے کو اور تھوڑے زیادہ کو سلام کریں؛ گھر میں داخل ہوتے وقت سلام؛ سلام میں پہل کرنے والا اللہ کے زیادہ قریب ہے۔","منافقین کی چار اقسام (اس سبق میں): (1) جہاد سے پیچھے رہنے اور مسلمانوں کی مصیبت پر خوش ہونے والے (آیات 72–73)؛ (2) آپ ﷺ کے سامنے اطاعت ظاہر کر کے رات کو سازشیں کرنے والے (آیت 81)؛ (3) افواہیں پھیلانے والے (آیت 83)؛ (4) دو رخے لوگ جو مسلمانوں اور کافروں دونوں سے امن چاہتے اور فتنے کی طرف پلٹ جاتے ہیں (آیات 88–91)۔"]}]}},"4":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l4-exercise-44",2]],"o":[["mq12-l4-exercise-44",3],["mq12-l4-exercise-44",4],["mq12-l4-exercise-44",5],["mq12-l4-exercise-44",6]],"s":["«وَاِذَا ضَرَبْتُمْ فِي الْاَرْضِ…» — جب زمین میں سفر کرو تو نماز قصر کرنے میں تم پر کوئی گناہ نہیں؛ یعنی قصر کا حکم سفر میں ہے (آیت 101)۔"],"c":3},{"q":[["mq12-l4-exercise-44",7]],"o":[["mq12-l4-exercise-44",8],["mq12-l4-exercise-44",9],["mq12-l4-exercise-44",10],["mq12-l4-exercise-44",11]],"s":["قرآن آپ ﷺ پر حق کے ساتھ نازل کیا گیا تاکہ آپ لوگوں کے درمیان اس کے مطابق فیصلہ کریں (آیت 105)۔"],"c":1},{"q":[["mq12-l4-exercise-44",12]],"o":[["mq12-l4-exercise-44",13],["mq12-l4-exercise-44",14],["mq12-l4-exercise-44",15],["mq12-l4-exercise-44",16]],"s":["«خَصِيْمًا» — حمایتی، طرف داری کرنے والا (جھگڑنے والا وکیل)؛ خیانت کرنے والوں کے طرف دار نہ بنو (آیت 105)۔"],"c":2},{"q":[["mq12-l4-exercise-44",17]],"o":[["mq12-l4-exercise-44",18],["mq12-l4-exercise-44",19],["mq12-l4-exercise-44",20],["mq12-l4-exercise-44",21]],"s":["«خَوَّانًا اَثِيْمًا» — بڑا خائن اور بڑا گناہ گار (آیت 107)۔"],"c":3},{"q":[["mq12-l4-exercise-44",22]],"o":[["mq12-l4-exercise-44",23],["mq12-l4-exercise-44",24],["mq12-l4-exercise-44",25],["mq12-l4-exercise-44",26]],"s":["«وَاتَّخَذَ اللّٰهُ اِبْرٰهِيْمَ خَلِيْلًا» — اللہ نے حضرت ابراہیمؑ کو اپنا دوست (خلیل) بنایا (آیت 125)۔"],"c":0},{"q":[["mq12-l4-exercise-44",27]],"o":[["mq12-l4-exercise-44",28],["mq12-l4-exercise-44",29],["mq12-l4-exercise-44",30],["mq12-l4-exercise-44",31]],"s":["«وَاُحْضِرَتِ الْاَنْفُسُ الشُّحَّ» — جانوں میں بخل (تنگ دلی) حاضر رکھا گیا ہے (آیت 128)۔"],"c":2},{"q":[["mq12-l4-exercise-44",32]],"o":[["mq12-l4-exercise-44",33],["mq12-l4-exercise-44",34],["mq12-l4-exercise-44",35],["mq12-l4-exercise-44",36]],"s":["«وَكَفٰى بِاللّٰهِ وَكِيْلًا» — کارساز (کام بنانے والا) ہونے کے لیے اللہ ہی کافی ہے (آیات 109، 132)۔"],"c":1}],"shortQuestions":[{"q":[["mq12-l4-exercise-44",38]],"s":["نماز ادا کر لینے کے بعد کھڑے، بیٹھے اور لیٹے ہر حال میں اللہ کا ذکر کرتے رہو؛ اور جب اطمینان ہو جائے تو نماز کو پورے طریقے سے قائم کرو (آیت 103)۔"]},{"q":[["mq12-l4-exercise-44",39]],"s":["دشمن (کافر قوم) کا پیچھا کرنے میں ہمت نہ ہارو؛ اگر تمہیں تکلیف پہنچتی ہے تو انہیں بھی ویسی ہی تکلیف پہنچتی ہے، مگر تم اللہ سے وہ امید رکھتے ہو جو وہ نہیں رکھتے (آیت 104)۔"]},{"q":[["mq12-l4-exercise-44",40]],"s":["آپ ﷺ کو ان لوگوں کی طرف سے جھگڑنے (ان کی وکالت کرنے) سے منع کیا گیا جو اپنے آپ سے خیانت کرتے ہیں؛ اللہ بڑے خائن اور گناہ گار کو پسند نہیں کرتا — یہ آیت طعمہ بن ابیرق کی چوری کے واقعے میں نازل ہوئی جو الزام ایک یہودی پر ڈالنا چاہتا تھا۔"]},{"q":[["mq12-l4-exercise-44",41]],"s":["اللہ نے آپ ﷺ پر کتاب (قرآن) اور حکمت (سنت) نازل کی اور آپ کو وہ سکھایا جو آپ نہیں جانتے تھے؛ اور آپ پر اللہ کا بہت بڑا فضل ہے۔"]},{"q":[["mq12-l4-exercise-45",0]],"s":["اللہ شرک کو کبھی معاف نہیں کرے گا (اگر توبہ کے بغیر موت آ جائے)، اس کے علاوہ جو گناہ ہیں جسے چاہے معاف کر دے گا؛ اور جس نے اللہ کے ساتھ شریک ٹھہرایا وہ گمراہی میں بہت دور جا پڑا۔"]},{"q":[["mq12-l4-exercise-45",1]],"s":["کافر اللہ کو چھوڑ کر دیویوں (مؤنث بتوں — لات، منات، عزیٰ؛ اور فرشتوں کو اللہ کی بیٹیاں) کو پکارتے ہیں، اور درحقیقت وہ سرکش شیطان ہی کو پکارتے ہیں۔"]},{"q":[["mq12-l4-exercise-45",2]],"s":["تم جو بھی نیکی کرو اللہ اسے خوب جانتا ہے؛ کوئی نیکی ضائع نہیں ہوتی اور اس کا پورا بدلہ ملے گا۔"]}],"longQuestions":[{"q":[["mq12-l4-exercise-45",4]],"s":["ترجمہ: اور جب تم زمین میں سفر کرو تو تم پر کوئی گناہ نہیں کہ نماز میں قصر کرو (کمی کرو) اگر تمہیں اندیشہ ہو کہ کافر تمہیں فتنے (تکلیف) میں ڈالیں گے؛ بے شک کافر تمہارے کھلے دشمن ہیں۔ (النساء 101)","تشریح: سفر میں چار رکعت والی فرض نماز (ظہر، عصر، عشا) دو رکعت پڑھی جاتی ہے؛ اگرچہ آیت میں خوف کا ذکر ہے مگر حدیث کے مطابق امن کی حالت میں بھی قصر اللہ کا صدقہ ہے۔"]},{"q":[["mq12-l4-exercise-45",5]],"s":["ان کی اکثر سرگوشیوں میں کوئی بھلائی نہیں، سوائے اس شخص (کی سرگوشی) کے جو صدقے کا، کسی نیک کام کا یا لوگوں کے درمیان صلح کرانے کا حکم دے؛ اور جو یہ کام اللہ کی رضا کے لیے کرے اسے اللہ بڑا اجر دے گا۔ (النساء 114)","یعنی صدقہ، نیکی اور اصلاح بین الناس کے لیے کی گئی خفیہ مشاورت اجرِ عظیم کا باعث ہے۔"]},{"q":[["mq12-l4-exercise-45",6]],"s":["ترجمہ: ہاں! تم وہ لوگ ہو کہ دنیا کی زندگی میں تو ان کی طرف سے جھگڑ لیے، مگر قیامت کے دن اللہ کے سامنے ان کی طرف سے کون جھگڑے گا یا کون ان کا وکیل (کارساز) ہوگا؟ (النساء 109)","تشریح: دنیا میں مجرم کی جھوٹی وکالت سے وہ بچ سکتا ہے، مگر آخرت میں اللہ کے سامنے کوئی اس کا حمایتی نہیں ہوگا۔"]},{"q":[["mq12-l4-exercise-45",7]],"s":["وہ شخص جو ہدایت واضح ہو جانے کے بعد رسول ﷺ کی مخالفت کرے اور مومنوں کے راستے کے سوا کسی اور راستے پر چلے، اسے اللہ اسی طرف پھیر دے گا جدھر وہ پھرا اور جہنم میں داخل کرے گا، اور وہ بہت برا ٹھکانا ہے۔ (النساء 115)","اس آیت سے علما نے اجماعِ امت (سبیل المومنین) کے حجت ہونے پر استدلال کیا ہے۔"]},{"q":[["mq12-l4-exercise-45",8]],"s":["ترجمہ: اور جو کچھ آسمانوں اور زمین میں ہے سب اللہ ہی کا ہے؛ اور ہم نے تم سے پہلے کتاب والوں کو اور تمہیں بھی یہی حکم دیا ہے کہ اللہ سے ڈرو؛ اور اگر تم انکار کرو تو (اس کا کچھ نقصان نہیں) آسمانوں اور زمین میں جو کچھ ہے سب اللہ ہی کا ہے، اور اللہ بے نیاز، تعریف کے لائق ہے۔ (النساء 131)","تشریح: تقویٰ کی وصیت تمام امتوں کو کی گئی؛ انسان کی نافرمانی سے اللہ کا کچھ نہیں بگڑتا۔"]},{"q":[["mq12-l4-exercise-45",9]],"s":["دین کے لحاظ سے سب سے بہتر وہ شخص ہے جس نے اپنا چہرہ (اپنی ذات) اللہ کے سپرد کر دیا، وہ نیکوکار (محسن) بھی ہو اور یکسو ہو کر ملتِ ابراہیمی کی پیروی کرے؛ اور اللہ نے ابراہیمؑ کو اپنا خلیل بنایا۔ (النساء 125)","یعنی اخلاص (اللہ کی کامل اطاعت)، احسان (عمل کی خوبی) اور ملتِ ابراہیمی (توحید) — یہ تینوں بہترین دین داری کی بنیاد ہیں۔"]}],"activities":[{"q":[["mq12-l4-exercise-45",11],["mq12-l4-exercise-45",12],["mq12-l4-exercise-45",13]],"s":["صلوٰۃ الخوف (النساء 102): جنگ کی حالت میں امام لشکر کو دو حصوں میں بانٹے؛ ایک گروہ امام کے ساتھ ایک رکعت پڑھے اور دوسرا دشمن کے مقابل پہرہ دے؛ پھر وہ گروہ پہرے پر جائے اور دوسرا آ کر امام کے ساتھ دوسری رکعت پڑھے؛ دونوں گروہ اپنی باقی رکعت پوری کریں؛ ہتھیار ساتھ رکھیں۔","نمازوں کے اوقات کا چارٹ: طلبہ اپنے شہر کے کیلنڈر سے ایک ماہ (سردی اور گرمی الگ) کے لیے فجر، ظہر، عصر، مغرب اور عشا کے ابتدائی اور آخری اوقات کا جدول بنائیں (مثلاً گرمیوں میں فجر جلد اور عشا دیر سے، سردیوں میں برعکس)۔","نماز کے بعد مسنون اذکار: تین بار استغفار؛ «اَللّٰهُمَّ اَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْاِكْرَامِ»؛ آیت الکرسی؛ 33 بار سبحان اللہ، 33 بار الحمد للہ، 34 بار اللہ اکبر؛ معوذتین — انہیں روزانہ پڑھنے کا اہتمام کریں۔"]}]}},"5":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l5-exercise-54",2]],"o":[["mq12-l5-exercise-54",3],["mq12-l5-exercise-54",4],["mq12-l5-exercise-54",5],["mq12-l5-exercise-54",6]],"s":["«بَشِّرِ الْمُنٰفِقِيْنَ بِاَنَّ لَهُمْ عَذَابًا اَلِيْمًا» — منافقوں کو دردناک عذاب کی \"خوشخبری\" (طنزاً) سنا دو (آیت 138)۔"],"c":2},{"q":[["mq12-l5-exercise-54",7]],"o":[["mq12-l5-exercise-54",8],["mq12-l5-exercise-54",9],["mq12-l5-exercise-54",10],["mq12-l5-exercise-54",11]],"s":["«قَامُوْا كُسَالٰى» — منافق نماز کے لیے سستی سے کھڑے ہوتے ہیں اور لوگوں کو دکھاتے ہیں (آیت 142)۔"],"c":2},{"q":[["mq12-l5-exercise-54",12]],"o":[["mq12-l5-exercise-54",13],["mq12-l5-exercise-54",14],["mq12-l5-exercise-54",15],["mq12-l5-exercise-54",16]],"s":["«فِي الدَّرْكِ الْاَسْفَلِ مِنَ النَّارِ» — منافق جہنم کے سب سے نچلے درجے میں ہوں گے (آیت 145)۔"],"c":1},{"q":[["mq12-l5-exercise-54",17]],"o":[["mq12-l5-exercise-54",18],["mq12-l5-exercise-54",19],["mq12-l5-exercise-54",20],["mq12-l5-exercise-54",21]],"s":["«فَاَخَذَتْهُمُ الصّٰعِقَةُ» — (اللہ کو کھلم کھلا دیکھنے کے مطالبے پر) انہیں بجلی کی کڑک (صاعقہ) نے آ پکڑا (آیت 153)۔"],"c":2},{"q":[["mq12-l5-exercise-54",22]],"o":[["mq12-l5-exercise-54",23],["mq12-l5-exercise-54",24],["mq12-l5-exercise-54",25],["mq12-l5-exercise-54",26]],"s":["«الْعِجْلَ» — بچھڑا؛ بنی اسرائیل نے بچھڑے کو معبود بنا لیا تھا (آیت 153)۔"],"c":3},{"q":[["mq12-l5-exercise-54",27]],"o":[["mq12-l5-exercise-54",28],["mq12-l5-exercise-54",29],["mq12-l5-exercise-54",30],["mq12-l5-exercise-54",31]],"s":["«حَظِّ الْاُنْثَيَيْنِ» — دو عورتوں کا حصہ؛ کلالہ کی میراث میں بھائی کو دو بہنوں کے برابر حصہ ملتا ہے (آیت 176)۔"],"c":0},{"q":[["mq12-l5-exercise-54",32]],"o":[["mq12-l5-exercise-54",33],["mq12-l5-exercise-54",34],["mq12-l5-exercise-54",35],["mq12-l5-exercise-54",36]],"s":["«بُرْهَانٌ» — واضح دلیل؛ تمہارے رب کی طرف سے روشن دلیل (رسول ﷺ) آ چکی اور ہم نے تمہاری طرف واضح نور (قرآن) اتارا (آیت 174)۔"],"c":1}],"shortQuestions":[{"q":[["mq12-l5-exercise-54",38]],"s":["اے ایمان والو! انصاف پر مضبوطی سے قائم رہنے والے اور اللہ کے لیے گواہی دینے والے بنو، چاہے گواہی تمہارے اپنے، والدین یا رشتہ داروں کے خلاف ہو؛ امیر و غریب کی پروا نہ کرو اور خواہشِ نفس کی پیروی میں انصاف نہ چھوڑو (آیت 135)۔"]},{"q":[["mq12-l5-exercise-54",39]],"s":["اللہ، اس کے رسول (محمد ﷺ)، اس کتاب (قرآن) پر جو اللہ نے اپنے رسول پر اتاری اور ان کتابوں پر جو پہلے اتاریں، ایمان لانے کا حکم دیا گیا ہے (آیت 136)۔"]},{"q":[["mq12-l5-exercise-54",40]],"s":["جو اللہ، اس کے فرشتوں، اس کی کتابوں، اس کے رسولوں اور آخرت کے دن کا انکار کرے وہ گمراہی میں بہت دور جا پڑا۔"]},{"q":[["mq12-l5-exercise-54",41]],"s":["اللہ منافقوں اور کافروں سب کو جہنم میں اکٹھا کرنے والا ہے (آیت 140)۔"]},{"q":[["mq12-l5-exercise-54",42]],"s":["شکر گزاری اور ایمان — اگر تم شکر کرو اور ایمان لاؤ تو اللہ تمہیں عذاب دے کر کیا کرے گا؛ اللہ قدر دان اور سب کچھ جاننے والا ہے (آیت 147)۔"]},{"q":[["mq12-l5-exercise-54",43]],"s":["اہلِ کتاب (یہود) نے مطالبہ کیا کہ آپ ﷺ ان پر آسمان سے ایک (لکھی ہوئی) کتاب اتار لائیں؛ وہ اس سے پہلے موسیٰؑ سے اس سے بڑا مطالبہ کر چکے تھے کہ ہمیں اللہ کو کھلم کھلا دکھا دو (آیت 153)۔"]},{"q":[["mq12-l5-exercise-55",0]],"s":["اللہ نے حضرت موسیٰؑ سے براہِ راست کلام فرمایا، اسی لیے وہ \"کلیم اللہ\" کہلاتے ہیں (آیت 164)۔"]}],"longQuestions":[{"q":[["mq12-l5-exercise-55",2]],"s":["ترجمہ: بے شک جو لوگ ایمان لائے، پھر کافر ہو گئے، پھر ایمان لائے، پھر کافر ہو گئے، پھر کفر میں بڑھتے چلے گئے، اللہ نہ انہیں بخشے گا اور نہ انہیں (سیدھی) راہ دکھائے گا۔ (النساء 137)","تشریح: بار بار ایمان اور کفر کے درمیان ڈگمگانا اور کفر پر جم جانا منافقت کی علامت ہے؛ ایسے لوگ ہدایت سے محروم رہتے ہیں۔"]},{"q":[["mq12-l5-exercise-55",3]],"s":["فتح کے موقع پر: منافق تمہاری تاک میں رہتے ہیں؛ اگر اللہ کی طرف سے تمہیں فتح ملے تو کہتے ہیں: کیا ہم تمہارے ساتھ نہ تھے؟ (یعنی غنیمت میں حصہ مانگتے ہیں)۔ (النساء 141)","شکست کے موقع پر: اور اگر کافروں کو کچھ کامیابی ملے تو ان سے کہتے ہیں: کیا ہم تم پر غالب نہ آ گئے تھے اور ہم نے تمہیں مسلمانوں سے بچا نہیں لیا؟ — یعنی دونوں طرف رہنے والے ابن الوقت ہیں؛ اللہ قیامت کے دن فیصلہ کرے گا اور کافروں کو مومنوں پر ہرگز غلبہ نہیں دے گا۔"]},{"q":[["mq12-l5-exercise-55",4]],"s":["ترجمہ: اے ایمان والو! مومنوں کو چھوڑ کر کافروں کو دوست نہ بناؤ؛ کیا تم چاہتے ہو کہ اللہ کے لیے اپنے خلاف ایک کھلی دلیل قائم کر دو؟ (النساء 144)","تشریح: کافروں سے قلبی دوستی اور انہیں رازدار بنانا منافقین کا طریقہ ہے؛ ایسا کرنا اپنے خلاف سزا کی دلیل مہیا کرنا ہے۔"]},{"q":[["mq12-l5-exercise-55",5]],"s":["مومنوں کے ساتھی وہ لوگ قرار دیے گئے جنہوں نے (نفاق سے) توبہ کی، اپنی اصلاح کی، اللہ کو مضبوطی سے پکڑا اور اپنے دین کو اللہ کے لیے خالص کر لیا؛ یہ لوگ مومنوں کے ساتھ ہیں۔ (النساء 146)","اور اللہ عنقریب مومنوں کو بڑا اجر عطا فرمائے گا — یعنی توبہ کا دروازہ منافق کے لیے بھی کھلا ہے۔"]},{"q":[["mq12-l5-exercise-55",6]],"s":["ترجمہ: اگر تم کوئی بھلائی کھلم کھلا کرو یا اسے چھپا کر کرو یا کسی برائی سے درگزر کرو تو بے شک اللہ بہت معاف کرنے والا، قدرت والا ہے۔ (النساء 149)","تشریح: نیکی ظاہر ہو یا پوشیدہ اور دوسروں کی برائی معاف کرنا اللہ کی صفتِ عفو کی پیروی ہے؛ اللہ قدرت کے باوجود معاف کرتا ہے۔"]},{"q":[["mq12-l5-exercise-55",7]],"s":["آیت میں تمام انسانوں کو خطاب کر کے تعلیم دی گئی: اے لوگو! یہ رسول (محمد ﷺ) تمہارے رب کی طرف سے حق لے کر آ چکے ہیں، پس ایمان لاؤ، یہ تمہارے لیے بہتر ہے۔ (النساء 170)","اور اگر انکار کرو تو (اللہ کا کچھ نقصان نہیں) آسمانوں اور زمین میں جو کچھ ہے سب اللہ کا ہے، اور اللہ جاننے والا، حکمت والا ہے — یعنی رسالتِ محمدی عالمگیر ہے اور ایمان انسان کے اپنے فائدے کے لیے ہے۔"]}],"activities":[{"q":[["mq12-l5-exercise-55",9],["mq12-l5-exercise-55",10]],"s":["اولو العزم انبیا کا چارٹ (اس سبق میں مذکور): حضرت نوحؑ — پہلے رسول، نجی اللہ؛ حضرت ابراہیمؑ — خلیل اللہ؛ حضرت موسیٰؑ — کلیم اللہ (آیت 164)؛ حضرت عیسیٰؑ — روح اللہ، کلمۃ اللہ (آیت 171)؛ حضرت محمد ﷺ — خاتم النبیین، رحمۃ للعالمین (آیات 163–170)۔","غلو کا مفہوم: دین میں حد سے بڑھ جانا؛ آیت 171 میں اہلِ کتاب کو غلو سے منع کیا گیا — عیسائیوں نے حضرت عیسیٰؑ کو اللہ کا بیٹا اور خدا بنا دیا اور تثلیث کا عقیدہ گھڑا، جبکہ وہ اللہ کے رسول اور اس کا کلمہ تھے جو مریمؑ کی طرف ڈالا گیا؛ غلو کی صورتیں: بزرگوں کو خدائی صفات دینا، عبادت میں خود ساختہ سختیاں، یا دین میں اپنی طرف سے اضافہ۔"]}]}},"6":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l6-exercise-65",3]],"o":[["mq12-l6-exercise-65",4],["mq12-l6-exercise-65",5],["mq12-l6-exercise-65",6],["mq12-l6-exercise-65",7]],"s":["«الْمَآئِدَةُ» — دستر خوان (کھانے سے بھرا ہوا)؛ حواریوں نے آسمان سے دستر خوان اتارنے کی دعا کی تھی، اسی سے سورت کا نام ہے۔"],"c":2},{"q":[["mq12-l6-exercise-65",8]],"o":[["mq12-l6-exercise-65",9],["mq12-l6-exercise-65",10],["mq12-l6-exercise-65",11],["mq12-l6-exercise-65",12]],"s":["«وَاِذَا حَلَلْتُمْ فَاصْطَادُوْا» — جب احرام کھول دو تو (خشکی کا) شکار کر سکتے ہو (آیت 2)۔"],"c":2},{"q":[["mq12-l6-exercise-65",13]],"o":[["mq12-l6-exercise-65",14],["mq12-l6-exercise-65",15],["mq12-l6-exercise-65",16],["mq12-l6-exercise-65",17]],"s":["«الْمَوْقُوْذَةُ» — وہ جانور جو چوٹ (لاٹھی، پتھر) لگنے سے مر جائے (آیت 3)؛ گلا گھٹ کر مرنے والا \"منخنقہ\"، گر کر مرنے والا \"متردیہ\" اور سینگ لگنے سے مرنے والا \"نطیحہ\" ہے۔"],"c":1},{"q":[["mq12-l6-exercise-65",18]],"o":[["mq12-l6-exercise-65",19],["mq12-l6-exercise-65",20],["mq12-l6-exercise-65",21],["mq12-l6-exercise-65",22]],"s":["«وَطَعَامُ الَّذِيْنَ اُوْتُوا الْكِتٰبَ حِلٌّ لَّكُمْ» — اہلِ کتاب کا (ذبیحہ اور) کھانا تمہارے لیے حلال ہے (آیت 5)۔"],"c":2},{"q":[["mq12-l6-exercise-66",0]],"o":[["mq12-l6-exercise-66",1],["mq12-l6-exercise-66",2],["mq12-l6-exercise-66",3],["mq12-l6-exercise-66",4]],"s":["یہود و نصاریٰ کہتے تھے: ہم اللہ کے بیٹے اور اس کے محبوب ہیں (آیت 18)۔"],"c":0},{"q":[["mq12-l6-exercise-66",5]],"o":[["mq12-l6-exercise-66",6],["mq12-l6-exercise-66",7],["mq12-l6-exercise-66",8],["mq12-l6-exercise-66",9]],"s":["«غُرَابًا» — کوا؛ اللہ نے کوا بھیجا جو زمین کریدتا تھا تاکہ قابیل کو بھائی کی لاش چھپانا سکھائے (آیت 31)۔"],"c":3},{"q":[["mq12-l6-exercise-66",10]],"o":[["mq12-l6-exercise-66",11],["mq12-l6-exercise-66",12],["mq12-l6-exercise-66",13],["mq12-l6-exercise-66",14]],"s":["جس نے کسی ایک انسان کو ناحق قتل کیا گویا اس نے تمام انسانوں کو قتل کیا، اور جس نے ایک جان بچائی گویا اس نے سب کو بچایا (آیت 32)۔"],"c":3}],"shortQuestions":[{"q":[["mq12-l6-exercise-66",16]],"s":["اے ایمان والو! عہد و پیمان (عقود) پورے کرو؛ تمہارے لیے چوپائے (مویشی) حلال کیے گئے سوائے ان کے جن کا حکم تمہیں سنایا جائے گا، مگر احرام کی حالت میں شکار کو حلال نہ سمجھو؛ اللہ جو چاہتا ہے حکم دیتا ہے (آیت 1)۔"]},{"q":[["mq12-l6-exercise-66",17]],"s":["اللہ نے اعلان فرمایا: آج میں نے تمہارے لیے تمہارا دین مکمل کر دیا، تم پر اپنی نعمت پوری کر دی اور تمہارے لیے اسلام کو دین کے طور پر پسند کر لیا — یہ آیت حجۃ الوداع کے موقع پر عرفہ کے دن نازل ہوئی (آیت 3)۔"]},{"q":[["mq12-l6-exercise-66",18]],"s":["سدھائے ہوئے شکاری جانور (کتے، باز) جو شکار تمہارے لیے روک رکھیں اسے کھا سکتے ہو؛ شکار پر چھوڑتے وقت اللہ کا نام لو؛ اور اللہ سے ڈرتے رہو، بے شک اللہ جلد حساب لینے والا ہے (آیت 4)۔"]},{"q":[["mq12-l6-exercise-66",19]],"s":["وضو کے فرائض: (1) چہرہ دھونا؛ (2) دونوں ہاتھ کہنیوں سمیت دھونا؛ (3) سر کا مسح کرنا؛ (4) دونوں پاؤں ٹخنوں سمیت دھونا (آیت 6)؛ جنابت ہو تو غسل اور پانی نہ ملے تو تیمم۔"]},{"q":[["mq12-l6-exercise-66",20]],"s":["یہود و نصاریٰ کا جھوٹا عقیدہ کہ ہم اللہ کے بیٹے اور اس کے محبوب ہیں؛ جواب دیا گیا: پھر وہ تمہیں تمہارے گناہوں پر سزا کیوں دیتا ہے؟ بلکہ تم بھی اس کی مخلوق میں سے انسان ہی ہو (آیت 18)۔"]},{"q":[["mq12-l6-exercise-66",21]],"s":["بنی اسرائیل نے موسیٰؑ سے کہا: اے موسیٰ! جب تک وہ (طاقتور قوم) وہاں ہیں ہم اس (ارضِ مقدس) میں ہرگز داخل نہ ہوں گے؛ تم اور تمہارا رب جا کر لڑو، ہم تو یہیں بیٹھے ہیں (آیت 24)۔"]},{"q":[["mq12-l6-exercise-66",22]],"s":["اللہ نے فرمایا: وہ سرزمین (ارضِ مقدس) چالیس سال تک ان پر حرام کر دی گئی، وہ زمین (صحرائے تیہ) میں بھٹکتے پھریں گے (آیت 26)۔"]}],"longQuestions":[{"q":[["mq12-l6-exercise-66",24]],"s":["ترجمہ: اے ایمان والو! اللہ کی اس نعمت کو یاد کرو جو تم پر ہوئی، جب ایک قوم نے ارادہ کیا کہ تم پر دست درازی کرے تو اللہ نے ان کے ہاتھ تم سے روک دیے؛ اور اللہ سے ڈرو، اور مومنوں کو اللہ ہی پر بھروسا کرنا چاہیے۔ (المائدہ 11)","تشریح: اس میں ان واقعات کی طرف اشارہ ہے جب دشمنوں نے آپ ﷺ اور مسلمانوں کو نقصان پہنچانے کی سازش کی (مثلاً بنو نضیر کی سازش) اور اللہ نے انہیں ناکام کر دیا۔"]},{"q":[["mq12-l6-exercise-66",25]],"s":["سورۃ المائدہ مدنی سورت ہے؛ اس میں 120 آیات اور 16 رکوع ہیں؛ ترتیب میں پانچویں سورت ہے؛ یہ آخری دور (صلح حدیبیہ کے بعد سے حجۃ الوداع تک) میں نازل ہوئی۔","نام: آیت 112–115 میں حواریوں کے لیے آسمان سے \"مائدہ\" (دستر خوان) اترنے کا ذکر ہے، اسی سے نام رکھا گیا۔","اہمیت: اسی میں «اَلْيَوْمَ اَكْمَلْتُ لَكُمْ دِيْنَكُمْ» نازل ہوئی؛ اس کا موضوع عہد و پیمان کی پابندی، حلال و حرام، اور اسلامی ریاست کے قوانین ہیں۔"]},{"q":[["mq12-l6-exercise-66",26]],"s":["ترجمہ: اور جب موسیٰ نے اپنی قوم سے کہا: اے میری قوم! اللہ کی اس نعمت کو یاد کرو جو تم پر ہوئی جب اس نے تم میں نبی پیدا کیے اور تمہیں بادشاہ (آزاد اور خود مختار) بنایا اور تمہیں وہ کچھ دیا جو دنیا والوں میں کسی کو نہ دیا تھا۔ (المائدہ 20)","تشریح: بنی اسرائیل کو فرعون کی غلامی سے نجات، انبیا کا سلسلہ، من و سلویٰ اور بادل کا سایہ جیسی نعمتیں ملیں، مگر انہوں نے ناشکری کی۔"]},{"q":[["mq12-l6-exercise-66",27]],"s":["سورۃ المائدہ کے بنیادی مضامین: (1) عہد و پیمان پورے کرنا؛ (2) حلال و حرام جانور اور کھانے، شکار اور احرام کے احکام؛ (3) تکمیلِ دین کا اعلان؛ (4) وضو، غسل اور تیمم۔","(5) عدل و انصاف — دشمن کی دشمنی بھی ناانصافی پر آمادہ نہ کرے؛ نیکی اور تقویٰ میں تعاون؛ (6) قتل، ڈاکا (حرابہ) اور چوری کی سزائیں؛ ہابیل و قابیل کا واقعہ۔","(7) شراب، جوا، بت اور پانسوں کی حرمت؛ قسموں کا کفارہ؛ (8) یہود و نصاریٰ کی عہد شکنی، تحریفِ کتاب اور تثلیث کا رد؛ ان سے قلبی دوستی کی ممانعت؛ (9) حضرت عیسیٰؑ کے معجزات اور مائدہ کا واقعہ؛ قیامت میں حضرت عیسیٰؑ سے سوال۔"]},{"q":[["mq12-l6-exercise-67",0]],"s":["ترجمہ: اور انہیں آدم کے دو بیٹوں کا واقعہ ٹھیک ٹھیک سناؤ، جب دونوں نے قربانی پیش کی تو ایک کی قبول ہوئی اور دوسرے کی قبول نہ ہوئی؛ اس (قابیل) نے کہا: میں تجھے ضرور قتل کر دوں گا؛ اس (ہابیل) نے کہا: اللہ تو صرف پرہیزگاروں (کی قربانی) قبول کرتا ہے۔ (المائدہ 27)","تشریح: حسد قتل تک لے جاتا ہے؛ قبولیت کا معیار تقویٰ اور اخلاص ہے؛ ہابیل نے کہا کہ اگر تو مجھے قتل کرنے کو ہاتھ بڑھائے گا تو میں تجھے قتل کرنے کو ہاتھ نہیں بڑھاؤں گا۔"]},{"q":[["mq12-l6-exercise-67",1]],"s":["جو لوگ اللہ اور اس کے رسول سے لڑتے اور زمین میں فساد (ڈاکا، قتل و غارت) پھیلاتے ہیں ان کی سزا یہ ہے کہ (جرم کے لحاظ سے) قتل کیے جائیں، یا سولی دیے جائیں، یا ان کے ہاتھ پاؤں مخالف سمتوں سے کاٹے جائیں، یا انہیں جلاوطن (قید) کیا جائے۔ (المائدہ 33)","یہ ان کے لیے دنیا میں رسوائی ہے اور آخرت میں بڑا عذاب ہے، سوائے ان کے جو گرفتاری سے پہلے توبہ کر لیں (آیت 34) — اسے حدِ حرابہ کہتے ہیں۔"]}],"activities":[{"q":[["mq12-l6-exercise-67",3],["mq12-l6-exercise-67",4],["mq12-l6-exercise-67",5]],"s":["کھانے کے حلال و حرام احکام (المائدہ 3): حرام — مردار، بہتا خون، سور کا گوشت، غیر اللہ کے نام پر ذبح کیا گیا جانور، گلا گھٹ کر مرا ہوا (منخنقہ)، چوٹ سے مرا (موقوذہ)، گر کر مرا (متردیہ)، سینگ لگنے سے مرا (نطیحہ)، درندے کا کھایا ہوا (سوائے اس کے جسے مرنے سے پہلے ذبح کر لو)، آستانوں پر ذبح کیا گیا اور پانسوں سے قسمت معلوم کرنا؛ حلال — پاکیزہ چیزیں، سدھائے ہوئے جانوروں کا شکار، اہلِ کتاب کا ذبیحہ؛ مجبوری میں جان بچانے کی حد تک رخصت۔","ہابیل و قابیل کا واقعہ (آیات 27–31): دونوں نے قربانی پیش کی، ہابیل کی قبول ہوئی کیونکہ وہ متقی تھا؛ حسد میں قابیل نے اسے قتل کر دیا؛ پھر کوے کو زمین کریدتے دیکھ کر لاش دفن کرنا سیکھا اور پشیمان ہوا — یہ دنیا کا پہلا قتل تھا۔","«وَتَعَاوَنُوْا عَلَى الْبِرِّ وَالتَّقْوٰى وَلَا تَعَاوَنُوْا عَلَى الْاِثْمِ وَالْعُدْوَانِ» (آیت 2): نیکی اور تقویٰ کے کاموں میں ایک دوسرے سے تعاون کرو، گناہ اور زیادتی میں نہیں — طلبہ اس کی عملی مثالیں (غریب طالب علم کی مدد، صفائی مہم، خون کا عطیہ) پیش کریں۔"]}]}},"7":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l7-exercise-77",2]],"o":[["mq12-l7-exercise-77",3],["mq12-l7-exercise-77",4],["mq12-l7-exercise-77",5],["mq12-l7-exercise-77",6]],"s":["«وَالسَّارِقُ وَالسَّارِقَةُ فَاقْطَعُوْٓا اَيْدِيَهُمَا» — چوری کرنے والے مرد اور عورت کا ہاتھ کاٹنا چوری کی سزا ہے (آیت 38)۔"],"c":0},{"q":[["mq12-l7-exercise-77",7]],"o":[["mq12-l7-exercise-77",8],["mq12-l7-exercise-77",9],["mq12-l7-exercise-77",10],["mq12-l7-exercise-77",11]],"s":["«يُحَرِّفُوْنَ الْكَلِمَ» — وہ کلام (اللہ کے الفاظ) کو بدل دیتے ہیں (آیت 41)۔"],"c":2},{"q":[["mq12-l7-exercise-77",12]],"o":[["mq12-l7-exercise-77",13],["mq12-l7-exercise-77",14],["mq12-l7-exercise-77",15],["mq12-l7-exercise-77",16]],"s":["«وَالسِّنَّ بِالسِّنِّ» — دانت کے بدلے دانت (آیت 45)۔"],"c":3},{"q":[["mq12-l7-exercise-77",17]],"o":[["mq12-l7-exercise-77",18],["mq12-l7-exercise-77",19],["mq12-l7-exercise-77",20],["mq12-l7-exercise-77",21]],"s":["«قِصَاصٌ» — بدلہ، برابر کا بدلہ (آیت 45)۔"],"c":1},{"q":[["mq12-l7-exercise-77",22]],"o":[["mq12-l7-exercise-77",23],["mq12-l7-exercise-77",24],["mq12-l7-exercise-77",25],["mq12-l7-exercise-77",26]],"s":["«شِرْعَةً وَّمِنْهَاجًا» — ہر امت کے لیے ایک شریعت (قانون) اور راستہ (طریقہ) مقرر کیا (آیت 48)۔"],"c":1},{"q":[["mq12-l7-exercise-77",27]],"o":[["mq12-l7-exercise-77",28],["mq12-l7-exercise-77",29],["mq12-l7-exercise-77",30],["mq12-l7-exercise-77",31]],"s":["یہود و نصاریٰ کو (قلبی) دوست اور رازدار بنانے سے منع کیا گیا؛ وہ ایک دوسرے کے دوست ہیں (آیت 51)۔"],"c":1},{"q":[["mq12-l7-exercise-77",32]],"o":[["mq12-l7-exercise-77",33],["mq12-l7-exercise-77",34],["mq12-l7-exercise-77",35],["mq12-l7-exercise-77",36]],"s":["«مُهَيْمِنًا» — نگہبان؛ قرآن پچھلی کتابوں کی تصدیق کرنے والا اور ان پر نگہبان (کسوٹی) ہے (آیت 48)۔"],"c":1}],"shortQuestions":[{"q":[["mq12-l7-exercise-77",38]],"s":["یہود کی دو صفات: جھوٹ کو خوب سننے والے (جھوٹی باتیں شوق سے سنتے ہیں) اور حرام (رشوت، سحت) خوب کھانے والے (آیت 42)۔"]},{"q":[["mq12-l7-exercise-77",39]],"s":["جن کے دلوں میں (نفاق کی) بیماری ہے وہ دوڑ دوڑ کر اہلِ کتاب سے ملتے ہیں اور کہتے ہیں: ہمیں ڈر ہے کہ ہم پر زمانے کی کوئی گردش (مصیبت) نہ آ جائے — یعنی مسلمانوں کی شکست کی صورت میں اپنا بچاؤ چاہتے ہیں (آیت 52)۔"]},{"q":[["mq12-l7-exercise-77",40]],"s":["جب تم نماز کے لیے اذان دیتے ہو تو وہ (کافر اور اہلِ کتاب) اس کا مذاق اڑاتے اور اسے کھیل بنا لیتے ہیں، کیونکہ وہ بے عقل لوگ ہیں (آیت 58)۔"]},{"q":[["mq12-l7-exercise-77",41]],"s":["یہود نے کہا تھا کہ اللہ کا ہاتھ بندھا ہوا ہے (یعنی وہ بخیل ہے)؛ جواب دیا گیا: ان کے ہاتھ باندھے جائیں اور ان کے اس قول پر ان پر لعنت ہو؛ بلکہ اللہ کے دونوں ہاتھ کھلے ہوئے ہیں، وہ جیسے چاہتا ہے خرچ کرتا ہے (آیت 64)۔"]},{"q":[["mq12-l7-exercise-78",0]],"s":["اے رسول! جو کچھ آپ کے رب کی طرف سے آپ پر نازل ہوا ہے وہ (لوگوں تک) پہنچا دیجیے؛ اگر ایسا نہ کیا تو آپ نے اس کا پیغام نہ پہنچایا؛ اور اللہ آپ کو لوگوں سے محفوظ رکھے گا (آیت 67)۔"]},{"q":[["mq12-l7-exercise-78",1]],"s":["جنہوں نے کہا کہ اللہ تین میں کا تیسرا ہے وہ یقیناً کافر ہو گئے؛ حالانکہ ایک معبود کے سوا کوئی معبود نہیں؛ اگر وہ اپنی بات سے باز نہ آئے تو ان میں سے کفر کرنے والوں کو دردناک عذاب پہنچے گا (آیت 73)۔"]},{"q":[["mq12-l7-exercise-78",2]],"s":["مسیح ابنِ مریم ایک رسول کے سوا کچھ نہیں، ان سے پہلے بھی بہت سے رسول گزر چکے؛ ان کی ماں (مریمؑ) سچی (صدیقہ) تھیں؛ دونوں کھانا کھاتے تھے — یعنی وہ انسان تھے، خدا نہیں، کیونکہ کھانے کا محتاج خدا نہیں ہو سکتا (آیت 75)۔"]}],"longQuestions":[{"q":[["mq12-l7-exercise-78",4]],"s":["ترجمہ: اے ایمان والو! اللہ سے ڈرو اور اس کی طرف (قرب کا) وسیلہ تلاش کرو اور اس کی راہ میں جہاد کرو تاکہ تم کامیاب ہو جاؤ۔ (المائدہ 35)","تشریح: وسیلہ سے مراد ہر وہ نیک عمل ہے جو اللہ کے قرب کا ذریعہ بنے — ایمان، اطاعت، نماز، صدقہ اور نیک اعمال؛ کامیابی کی تین شرطیں: تقویٰ، وسیلہ اور جہاد۔"]},{"q":[["mq12-l7-exercise-78",5]],"s":["تورات میں قصاص کا قانون یہ تھا: جان کے بدلے جان، آنکھ کے بدلے آنکھ، ناک کے بدلے ناک، کان کے بدلے کان، دانت کے بدلے دانت، اور (تمام) زخموں کا بھی برابر بدلہ ہے۔ (المائدہ 45)","پھر جو بدلہ معاف کر دے تو یہ اس کے لیے (گناہوں کا) کفارہ ہے؛ اور جو اللہ کے نازل کردہ قانون کے مطابق فیصلہ نہ کریں وہی ظالم ہیں — اسلام نے بھی یہی قانونِ قصاص برقرار رکھا۔"]},{"q":[["mq12-l7-exercise-78",6]],"s":["ترجمہ: تمہارا دوست (مددگار) تو صرف اللہ، اس کا رسول اور وہ اہلِ ایمان ہیں جو نماز قائم کرتے ہیں، زکوٰۃ دیتے ہیں اور وہ (اللہ کے آگے) جھکنے والے ہیں۔ (المائدہ 55)","تشریح: مومن کی حقیقی دوستی اللہ، رسول اور نماز و زکوٰۃ کے پابند عاجز مومنوں سے ہے، نہ کہ اسلام دشمنوں سے۔"]},{"q":[["mq12-l7-exercise-78",7]],"s":["اہلِ کتاب کو منع کیا گیا: (1) اپنے دین میں ناحق غلو (حد سے بڑھنا) نہ کرو؛ (2) ان لوگوں کی خواہشات کی پیروی نہ کرو جو تم سے پہلے گمراہ ہو چکے، جنہوں نے بہت سوں کو گمراہ کیا اور سیدھی راہ سے بھٹک گئے۔ (المائدہ 77)","غلو کی مثال: عیسائیوں کا حضرت عیسیٰؑ کو خدا یا خدا کا بیٹا بنانا اور یہود کا اپنے علما کو رب کا درجہ دینا۔"]},{"q":[["mq12-l7-exercise-78",8]],"s":["ترجمہ: بے شک جو ایمان لائے اور جو یہودی ہوئے اور صابی اور نصاریٰ — ان میں سے جو بھی اللہ اور آخرت کے دن پر (صحیح) ایمان لائے اور نیک عمل کرے، تو نہ ان پر کوئی خوف ہوگا اور نہ وہ غمگین ہوں گے۔ (المائدہ 69)","تشریح: نجات کا دار و مدار نسلی یا گروہی نسبت پر نہیں بلکہ صحیح ایمان (جس میں آخری رسول ﷺ پر ایمان شامل ہے) اور نیک عمل پر ہے۔"]},{"q":[["mq12-l7-exercise-78",9]],"s":["عیسائیوں کا عقیدہ: انہوں نے کہا کہ اللہ ہی مسیح ابنِ مریم ہے (یعنی مسیح میں خدا نے حلول کیا) — ایسا کہنے والے کافر ہو گئے۔ (المائدہ 72)","حضرت عیسیٰؑ کی تردید: خود مسیح نے کہا تھا: اے بنی اسرائیل! اللہ کی عبادت کرو جو میرا بھی رب ہے اور تمہارا بھی رب؛ جو اللہ کے ساتھ شریک ٹھہرائے اللہ نے اس پر جنت حرام کر دی اور اس کا ٹھکانا آگ ہے، اور ظالموں کا کوئی مددگار نہیں۔"]}],"activities":[{"q":[["mq12-l7-exercise-78",11],["mq12-l7-exercise-78",12]],"s":["عقیدۂ تثلیث: عیسائیوں کے نزدیک خدا تین اقانیم — باپ (اللہ)، بیٹا (مسیح) اور روح القدس — کا مجموعہ ہے؛ قرآن نے اس کی تردید کی: اللہ ایک ہے (المائدہ 73)؛ مسیح صرف رسول تھے اور ماں بیٹا دونوں کھانا کھاتے تھے (75)؛ مسیح نے خود اللہ کو اپنا رب کہا (72)؛ اللہ کا کوئی بیٹا نہیں، وہ بے نیاز ہے (سورۃ الاخلاص)؛ حضرت عیسیٰؑ کی بغیر باپ پیدائش حضرت آدمؑ کی طرح اللہ کی قدرت ہے (آل عمران 59)۔","یہود کے باطل عقائد اور جرائم کی فہرست: اللہ کا بیٹا اور محبوب ہونے کا دعویٰ؛ اللہ کو بخیل کہنا (ید اللہ مغلولۃ)؛ کتاب میں تحریف؛ جھوٹ سننا اور رشوت کھانا؛ انبیا کا قتل؛ عہد شکنی؛ اذان کا مذاق؛ بچھڑے کی پوجا — رد: اللہ کی صفات کامل ہیں، نجات عمل سے ہے نہ نسب سے، اور سزا ان کے دعوے کو جھٹلاتی ہے۔"]}]}},"8":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l8-exercise-87",3]],"o":[["mq12-l8-exercise-87",4],["mq12-l8-exercise-87",5],["mq12-l8-exercise-87",6],["mq12-l8-exercise-87",7]],"s":["«طَيِّبٰتِ» — پاکیزہ چیزیں؛ اللہ کی حلال کی ہوئی پاکیزہ چیزوں کو اپنے اوپر حرام نہ کرو (آیت 87)۔"],"c":2},{"q":[["mq12-l8-exercise-87",8]],"o":[["mq12-l8-exercise-87",9],["mq12-l8-exercise-87",10],["mq12-l8-exercise-87",11],["mq12-l8-exercise-87",12]],"s":["قسم توڑنے کا کفارہ: دس مسکینوں کو اوسط درجے کا کھانا کھلانا، یا انہیں کپڑے پہنانا، یا ایک غلام آزاد کرنا؛ یہ نہ ہو سکے تو تین دن کے روزے (آیت 89)۔"],"c":3},{"q":[["mq12-l8-exercise-87",13]],"o":[["mq12-l8-exercise-87",14],["mq12-l8-exercise-87",15],["mq12-l8-exercise-87",16],["mq12-l8-exercise-87",17]],"s":["«صَيْدُ الْبَحْرِ» — سمندر (دریا) کا شکار؛ یہ احرام میں بھی حلال ہے (آیت 96)۔"],"c":1},{"q":[["mq12-l8-exercise-88",0]],"o":[["mq12-l8-exercise-88",1],["mq12-l8-exercise-88",2],["mq12-l8-exercise-88",3],["mq12-l8-exercise-88",4]],"s":["«مَا عَلَى الرَّسُوْلِ اِلَّا الْبَلٰغُ» — رسول کی ذمہ داری صرف پیغام پہنچا دینا ہے (آیت 99)۔"],"c":0},{"q":[["mq12-l8-exercise-88",5]],"o":[["mq12-l8-exercise-88",6],["mq12-l8-exercise-88",7],["mq12-l8-exercise-88",8],["mq12-l8-exercise-88",9]],"s":["اللہ جانتا ہے جو تم ظاہر کرتے ہو اور جو چھپاتے ہو (آیت 99)۔"],"c":2},{"q":[["mq12-l8-exercise-88",10]],"o":[["mq12-l8-exercise-88",11],["mq12-l8-exercise-88",12],["mq12-l8-exercise-88",13],["mq12-l8-exercise-88",14]],"s":["حواریوں نے حضرت عیسیٰؑ سے درخواست کی کہ ان کا رب آسمان سے (کھانے کا) دستر خوان اتارے (آیت 112)۔"],"c":1},{"q":[["mq12-l8-exercise-88",15]],"o":[["mq12-l8-exercise-88",16],["mq12-l8-exercise-88",17],["mq12-l8-exercise-88",18],["mq12-l8-exercise-88",19]],"s":["قیامت کا دن وہ دن ہے جس میں سچوں کو ان کی سچائی فائدہ دے گی (آیت 119)۔"],"c":0}],"shortQuestions":[{"q":[["mq12-l8-exercise-88",21]],"s":["بنی اسرائیل میں سے کفر کرنے والوں پر حضرت داؤدؑ اور حضرت عیسیٰ ابنِ مریمؑ کی زبان سے لعنت کی گئی، کیونکہ وہ نافرمانی کرتے اور حد سے بڑھ جاتے تھے (آیت 78)۔"]},{"q":[["mq12-l8-exercise-88",22]],"s":["وہ ایک دوسرے کو برے کاموں سے نہیں روکتے تھے جو وہ کرتے تھے — یعنی نہی عن المنکر چھوڑ دی تھی؛ کیا ہی برا کام تھا جو وہ کرتے تھے (آیت 79)۔"]},{"q":[["mq12-l8-exercise-88",23]],"s":["آیت نے یہودیوں اور مشرکوں کو مسلمانوں کا سب سے سخت دشمن قرار دیا ہے؛ اور ایمان والوں سے دوستی میں سب سے قریب ان لوگوں کو جو اپنے آپ کو نصاریٰ کہتے ہیں، کیونکہ ان میں عالم اور راہب ہیں اور وہ تکبر نہیں کرتے (آیت 82)۔"]},{"q":[["mq12-l8-exercise-88",24]],"s":["شیطان شراب اور جوئے کے ذریعے تمہارے درمیان دشمنی اور بغض ڈالنا چاہتا ہے اور تمہیں اللہ کے ذکر اور نماز سے روکنا چاہتا ہے (آیت 91)۔"]},{"q":[["mq12-l8-exercise-88",25]],"s":["پچھلی قوموں کی بری عادت: بے جا سوالات کرنا — ایسی باتیں پوچھنا جو ظاہر کر دی جائیں تو انہیں بری لگیں؛ پھر وہ ان (احکام) کا انکار کر بیٹھے (آیات 101–102)۔"]},{"q":[["mq12-l8-exercise-88",26]],"s":["حواریوں نے کہا: ہم چاہتے ہیں کہ اس میں سے کھائیں، ہمارے دل مطمئن ہو جائیں، ہم جان لیں کہ آپ نے ہم سے سچ کہا اور ہم اس پر گواہ بن جائیں (آیت 113)۔"]},{"q":[["mq12-l8-exercise-88",27]],"s":["اللہ پوچھے گا: اے عیسیٰ ابنِ مریم! کیا تم نے لوگوں سے کہا تھا کہ اللہ کے سوا مجھے اور میری ماں کو معبود بنا لو؟ وہ عرض کریں گے: تو پاک ہے، مجھے حق نہیں کہ وہ بات کہوں جس کا مجھے حق نہیں؛ اگر میں نے کہی ہوتی تو تو جانتا؛ میں نے انہیں صرف وہی کہا جس کا تو نے حکم دیا کہ اللہ کی عبادت کرو جو میرا اور تمہارا رب ہے (آیات 116–117)۔"]}],"longQuestions":[{"q":[["mq12-l8-exercise-88",29]],"s":["ترجمہ: اے ایمان والو! جو پاکیزہ چیزیں اللہ نے تمہارے لیے حلال کی ہیں انہیں (اپنے اوپر) حرام نہ کرو اور حد سے نہ بڑھو؛ بے شک اللہ حد سے بڑھنے والوں کو پسند نہیں کرتا۔ (المائدہ 87)","تشریح: کچھ صحابہ نے رہبانیت (گوشت، نیند اور نکاح چھوڑنا) کا ارادہ کیا تو یہ آیت نازل ہوئی؛ اسلام میں حلال چیزوں کو ترک کر دینا دین داری نہیں بلکہ اعتدال مطلوب ہے۔"]},{"q":[["mq12-l8-exercise-88",30]],"s":["مومنوں کو چار چیزوں سے بچنے کا حکم دیا گیا: شراب، جوا، بت (آستانے/تھان) اور پانسے (فال کے تیر) — یہ سب ناپاک اور شیطان کے کام ہیں، پس ان سے بچو تاکہ تم فلاح پاؤ۔ (المائدہ 90)","یہ آیت شراب اور جوئے کی قطعی حرمت کا اعلان ہے؛ اس کے بعد صحابہ نے مدینہ کی گلیوں میں شراب بہا دی۔"]},{"q":[["mq12-l8-exercise-88",31]],"s":["ترجمہ: کہہ دیجیے کہ ناپاک اور پاک برابر نہیں ہو سکتے، اگرچہ ناپاک کی کثرت تمہیں بھلی لگے؛ پس اے عقل والو! اللہ سے ڈرو تاکہ تم کامیاب ہو جاؤ۔ (المائدہ 100)","تشریح: حرام مال، برے لوگ اور باطل چاہے زیادہ ہوں، حلال، نیک اور حق کے برابر نہیں؛ معیار تعداد نہیں بلکہ پاکیزگی ہے۔"]},{"q":[["mq12-l8-exercise-89",0]],"s":["قسموں کے احکام: اللہ تمہاری بے ارادہ (لغو) قسموں پر مؤاخذہ نہیں کرتا، لیکن جو قسمیں تم پختہ ارادے سے کھاؤ ان پر مؤاخذہ کرتا ہے۔ (المائدہ 89)","پختہ قسم توڑنے کا کفارہ: دس مسکینوں کو اوسط درجے کا کھانا کھلانا جو تم اپنے گھر والوں کو کھلاتے ہو، یا انہیں کپڑے دینا، یا ایک غلام آزاد کرنا؛ جو یہ نہ پائے وہ تین دن کے روزے رکھے؛ اپنی قسموں کی حفاظت کرو۔"]},{"q":[["mq12-l8-exercise-89",1]],"s":["ترجمہ: (عیسیٰؑ عرض کریں گے) میں نے انہیں اس کے سوا کچھ نہیں کہا جس کا تو نے مجھے حکم دیا تھا کہ اللہ کی عبادت کرو جو میرا اور تمہارا رب ہے؛ اور جب تک میں ان میں رہا ان پر گواہ (نگران) تھا، پھر جب تو نے مجھے اٹھا لیا تو تو ہی ان کا نگہبان تھا، اور تو ہر چیز پر گواہ ہے۔ (المائدہ 117)","تشریح: حضرت عیسیٰؑ تثلیث اور اپنی الوہیت کے عقیدے سے برأت کا اعلان کریں گے۔"]},{"q":[["mq12-l8-exercise-89",2]],"s":["حضرت عیسیٰؑ اپنی قوم کے بارے میں عرض کریں گے: اگر تو انہیں عذاب دے تو وہ تیرے ہی بندے ہیں، اور اگر تو انہیں بخش دے تو بے شک تو ہی غالب، حکمت والا ہے۔ (المائدہ 118)","یعنی وہ فیصلہ پوری طرح اللہ کے سپرد کر دیں گے — نہ ان کی سفارش کریں گے نہ بددعا؛ نبی ﷺ نے ایک رات یہی آیت بار بار پڑھتے ہوئے قیام کیا۔"]}],"activities":[{"q":[["mq12-l8-exercise-89",4],["mq12-l8-exercise-89",5]],"s":["حضرت عیسیٰؑ کے معجزات (المائدہ 110): روح القدس (جبرائیلؑ) سے تائید؛ گہوارے میں اور بڑی عمر میں لوگوں سے کلام؛ کتاب، حکمت، تورات اور انجیل کا علم؛ مٹی سے پرندے کی صورت بنا کر پھونکنا اور اللہ کے حکم سے اس کا پرندہ بن جانا؛ پیدائشی اندھے اور کوڑھی کو شفا دینا؛ اللہ کے حکم سے مردوں کو زندہ کرنا؛ بنی اسرائیل کے حملے سے بچایا جانا؛ آسمان سے مائدہ کا نزول۔","قیامت کے دن اللہ اور حضرت عیسیٰؑ کا مکالمہ (آیات 116–120): (1) سوال: کیا تم نے لوگوں کو اپنی اور اپنی ماں کی عبادت کا کہا تھا؟ (2) جواب: تو پاک ہے، میں نے ایسا نہیں کہا، تو میرے دل کی بات جانتا ہے؛ (3) میں نے صرف اللہ کی عبادت کا حکم دیا؛ (4) جب تک ان میں رہا گواہ تھا، پھر تو نگہبان تھا؛ (5) عذاب دے تو تیرے بندے، بخش دے تو تو غالب و حکیم؛ (6) اللہ کا اعلان: آج سچوں کو ان کی سچائی فائدہ دے گی، ان کے لیے جنتیں ہیں، اللہ ان سے راضی اور وہ اللہ سے راضی؛ (7) آسمانوں اور زمین کی بادشاہی اللہ ہی کی ہے۔"]}]}},"9":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l9-exercise-97",2]],"o":[["mq12-l9-exercise-97",3],["mq12-l9-exercise-97",4],["mq12-l9-exercise-97",5],["mq12-l9-exercise-97",6]],"s":["غیر شادی شدہ زانی مرد اور عورت میں سے ہر ایک کو سو کوڑے مارنے کی سزا (حد) مقرر کی گئی ہے (النور 2)۔"],"c":0},{"q":[["mq12-l9-exercise-97",7]],"o":[["mq12-l9-exercise-97",8],["mq12-l9-exercise-97",9],["mq12-l9-exercise-97",10],["mq12-l9-exercise-97",11]],"s":["«ثَمٰنِيْنَ جَلْدَةً» — اسی کوڑے؛ پاک دامن عورتوں پر تہمت لگانے والوں (حدِ قذف) کی سزا (آیت 4)۔"],"c":1},{"q":[["mq12-l9-exercise-97",12]],"o":[["mq12-l9-exercise-97",13],["mq12-l9-exercise-97",14],["mq12-l9-exercise-97",15],["mq12-l9-exercise-97",16]],"s":["«اِفْكٌ» — بہتان، جھوٹا الزام؛ حضرت عائشہؓ پر لگائی گئی تہمت \"واقعۂ افک\" کہلاتی ہے (آیت 11)۔"],"c":3},{"q":[["mq12-l9-exercise-97",17]],"o":[["mq12-l9-exercise-97",18],["mq12-l9-exercise-97",19],["mq12-l9-exercise-97",20],["mq12-l9-exercise-97",21]],"s":["«حَتّٰى تَسْتَاْنِسُوْا» — جب تک (گھر والوں سے) اجازت نہ لے لو اور انہیں سلام نہ کر لو (آیت 27)۔"],"c":0},{"q":[["mq12-l9-exercise-97",22]],"o":[["mq12-l9-exercise-97",23],["mq12-l9-exercise-97",24],["mq12-l9-exercise-97",25],["mq12-l9-exercise-97",26]],"s":["«وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلٰى جُيُوْبِهِنَّ» — اپنی اوڑھنیاں اپنے سینوں (گریبانوں) پر ڈالے رہیں (آیت 31)۔"],"c":1},{"q":[["mq12-l9-exercise-97",27]],"o":[["mq12-l9-exercise-97",28],["mq12-l9-exercise-97",29],["mq12-l9-exercise-97",30],["mq12-l9-exercise-97",31]],"s":["«غَيْرِ اُولِي الْاِرْبَةِ» — ایسے تابع (خدمت گار) مرد جنہیں عورتوں کی خواہش نہ ہو (آیت 31)۔"],"c":3},{"q":[["mq12-l9-exercise-97",32]],"o":[["mq12-l9-exercise-97",33],["mq12-l9-exercise-97",34],["mq12-l9-exercise-97",35],["mq12-l9-exercise-97",36]],"s":["«الْاَيَامٰى» — بے نکاح (غیر شادی شدہ) مرد اور عورتیں (کنوارے، رنڈوے اور بیوائیں)؛ ان کے نکاح کر دو (آیت 32)۔"],"c":3}],"shortQuestions":[{"q":[["mq12-l9-exercise-97",38]],"s":["یہ ایک سورت ہے جسے ہم نے نازل کیا اور (اس کے احکام کو) فرض کیا اور اس میں واضح آیات اتاریں تاکہ تم نصیحت حاصل کرو (النور 1)۔"]},{"q":[["mq12-l9-exercise-97",39]],"s":["حد نافذ کرتے وقت تنبیہ کی گئی کہ اللہ کے دین (کے حکم) کے معاملے میں تمہیں ان دونوں پر ترس نہ آئے اگر تم اللہ اور آخرت پر ایمان رکھتے ہو؛ اور ان کی سزا کے وقت مومنوں کی ایک جماعت موجود ہو (آیت 2)۔"]},{"q":[["mq12-l9-exercise-97",40]],"s":["جو لوگ پاک دامن عورتوں پر تہمت لگائیں پھر چار گواہ نہ لائیں انہیں اسی کوڑے مارو، ان کی گواہی کبھی قبول نہ کرو اور وہی فاسق ہیں (آیت 4)۔"]},{"q":[["mq12-l9-exercise-97",41]],"s":["بہتان باندھنے والوں میں سے ہر ایک کے لیے اس کے کمائے ہوئے گناہ کا حصہ ہے، اور جس نے اس (بہتان) کا بڑا بوجھ اٹھایا (رئیس المنافقین عبداللہ بن ابی) اس کے لیے بڑا عذاب ہے (آیت 11)۔"]},{"q":[["mq12-l9-exercise-97",42]],"s":["شیطان اپنے پیروکاروں کو بے حیائی اور برائی کا حکم دیتا ہے؛ اس لیے شیطان کے نقشِ قدم پر نہ چلو (آیت 21)۔"]},{"q":[["mq12-l9-exercise-97",43]],"s":["ایمان والے مردوں سے کہہ دیجیے کہ اپنی نگاہیں نیچی رکھیں اور اپنی شرم گاہوں کی حفاظت کریں؛ یہ ان کے لیے زیادہ پاکیزگی کی بات ہے (آیت 30)۔"]},{"q":[["mq12-l9-exercise-98",0]],"s":["ایمان والی عورتوں سے کہہ دیجیے کہ اپنی نگاہیں نیچی رکھیں، شرم گاہوں کی حفاظت کریں، اپنی زینت ظاہر نہ کریں سوائے اس کے جو خود ظاہر ہو، اپنی اوڑھنیاں سینوں پر ڈالے رہیں، محرموں کے سوا کسی پر زینت ظاہر نہ کریں اور زمین پر پاؤں مار کر نہ چلیں کہ ان کی چھپی زینت معلوم ہو (آیت 31)۔"]}],"longQuestions":[{"q":[["mq12-l9-exercise-98",2]],"s":["ترجمہ: زانی مرد نکاح نہیں کرتا مگر زانیہ یا مشرکہ عورت سے، اور زانیہ عورت سے نکاح نہیں کرتا مگر زانی یا مشرک مرد؛ اور یہ (بدکاروں سے نکاح) ایمان والوں پر حرام کر دیا گیا ہے۔ (النور 3)","تشریح: بدکاری پر قائم شخص پاک دامن مومن کا جوڑ نہیں؛ مومنوں کو ایسے لوگوں سے رشتہ کرنے سے روکا گیا جب تک وہ توبہ نہ کریں۔"]},{"q":[["mq12-l9-exercise-98",3]],"s":["سورۃ النور مدنی سورت ہے؛ اس میں 64 آیات اور 9 رکوع ہیں؛ یہ 5ھ یا 6ھ میں غزوۂ بنی المصطلق کے بعد واقعۂ افک کے پس منظر میں نازل ہوئی۔","نام: آیت 35 «اَللّٰهُ نُوْرُ السَّمٰوٰتِ وَالْاَرْضِ» میں اللہ کے نور کی مثال بیان ہوئی، اسی سے نام \"النور\" ہے۔","مقصد: مسلم معاشرے کو بے حیائی سے پاک رکھنا، عصمت و عفت کی حفاظت اور خاندانی نظام کو مضبوط کرنے کے لیے معاشرتی قوانین اور آداب دینا۔"]},{"q":[["mq12-l9-exercise-98",4]],"s":["ترجمہ: گندی عورتیں گندے مردوں کے لیے ہیں اور گندے مرد گندی عورتوں کے لیے؛ اور پاکیزہ عورتیں پاکیزہ مردوں کے لیے ہیں اور پاکیزہ مرد پاکیزہ عورتوں کے لیے؛ یہ (پاک لوگ) ان باتوں سے بری ہیں جو (بہتان باز) کہتے ہیں؛ ان کے لیے مغفرت اور عزت کی روزی ہے۔ (النور 26)","تشریح: یہ آیت حضرت عائشہ صدیقہؓ کی برأت میں نازل ہوئی — نبی ﷺ پاکیزہ ترین ہیں تو ان کی زوجہ بھی پاکیزہ ہیں۔"]},{"q":[["mq12-l9-exercise-98",5]],"s":["سورۃ النور کے بنیادی مضامین: (1) زنا کی حد (سو کوڑے) اور تہمت (قذف) کی سزا (اسی کوڑے)؛ (2) لعان کا حکم — شوہر بیوی پر الزام لگائے اور گواہ نہ ہوں؛ (3) واقعۂ افک اور حضرت عائشہؓ کی برأت؛ بہتان اور افواہ پھیلانے کی مذمت۔","(4) گھروں میں داخلے کے آداب — اجازت اور سلام؛ (5) غضِ بصر، پردہ اور زینت کے احکام اور محرموں کی فہرست؛ (6) بے نکاحوں کے نکاح کی ترغیب؛ غلاموں کی مکاتبت؛ لونڈیوں کو بدکاری پر مجبور کرنے کی ممانعت۔","(7) آیتِ نور — اللہ کا نور اور مومن کا دل؛ مساجد اور اللہ کے ذکر والے؛ کافروں کے اعمال کی سراب اور اندھیروں سے مثال؛ (8) منافقین کا رویہ اور سچے مومنوں کی اطاعت؛ خلافت کا وعدہ (آیت 55)؛ (9) گھریلو آداب — تین اوقات میں اجازت، بوڑھی عورتوں کو رخصت، معذوروں اور رشتہ داروں کے گھروں سے کھانا؛ رسول ﷺ کے بلانے کا ادب۔"]},{"q":[["mq12-l9-exercise-98",6]],"s":["ترجمہ: اے ایمان والو! اپنے گھروں کے سوا دوسرے گھروں میں داخل نہ ہو جب تک اجازت نہ لے لو اور گھر والوں کو سلام نہ کر لو؛ یہ تمہارے لیے بہتر ہے تاکہ تم نصیحت حاصل کرو۔ (النور 27)","تشریح: اجازت تین بار مانگی جائے، اجازت نہ ملے تو لوٹ جاؤ؛ دروازے کے سامنے کھڑے نہ ہو اور اپنا نام بتاؤ — یہ اسلامی معاشرت کا ادب اور نجی زندگی (پرائیویسی) کا تحفظ ہے۔"]},{"q":[["mq12-l9-exercise-98",7]],"s":["آیت کے مطابق جو لوگ پاک دامن، (برائی سے) بے خبر، ایمان والی عورتوں پر (بدکاری کی) تہمت لگاتے ہیں ان پر دنیا اور آخرت میں لعنت ہے اور ان کے لیے بڑا عذاب ہے۔ (النور 23)","اس دن ان کی زبانیں، ہاتھ اور پاؤں ان کے اعمال کی گواہی دیں گے (آیت 24) — یعنی پاک دامن عورت پر بہتان کبیرہ گناہ ہے۔"]}],"activities":[{"q":[["mq12-l9-exercise-98",9],["mq12-l9-exercise-98",10]],"s":["دوسروں کے گھروں میں داخلے کے آداب (النور 27–29): (1) داخل ہونے سے پہلے اجازت لینا؛ (2) گھر والوں کو سلام کرنا؛ (3) اگر گھر میں کوئی نہ ہو تو اجازت کے بغیر داخل نہ ہونا؛ (4) واپس جانے کا کہا جائے تو لوٹ جانا — یہ زیادہ پاکیزہ ہے؛ (5) غیر رہائشی عوامی جگہوں (سرائے، دکانیں) میں جہاں تمہارا سامان ہو بغیر اجازت جانے میں حرج نہیں؛ (6) گھر کے اندر بھی نابالغ بچے اور ملازم تین اوقات (فجر سے پہلے، دوپہر کے آرام اور عشا کے بعد) میں اجازت لیں (آیت 58)۔","جن کے سامنے عورتوں کو پردے میں رخصت ہے (النور 31): شوہر، باپ (دادا، نانا)، سسر، اپنے بیٹے (پوتے، نواسے)، شوہر کے بیٹے، بھائی، بھتیجے، بھانجے، اپنی (مسلمان) عورتیں، اپنے غلام/کنیزیں، ایسے خدمت گار مرد جنہیں عورتوں کی خواہش نہ ہو، اور وہ بچے جو عورتوں کی پوشیدہ باتوں سے ابھی واقف نہ ہوں۔"]}]}},"10":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l10-exercise-105",3]],"o":[["mq12-l10-exercise-105",4],["mq12-l10-exercise-105",5],["mq12-l10-exercise-105",6],["mq12-l10-exercise-105",7]],"s":["«الْمِصْبَاحُ» — چراغ (آیتِ نور 35)۔"],"c":3},{"q":[["mq12-l10-exercise-105",8]],"o":[["mq12-l10-exercise-105",9],["mq12-l10-exercise-105",10],["mq12-l10-exercise-105",11],["mq12-l10-exercise-105",12]],"s":["«كَوْكَبٌ دُرِّيٌّ» — موتی جیسا چمکتا ہوا ستارہ؛ فانوس (شیشہ) گویا موتی کی طرح چمکتا ستارہ ہے (آیت 35)۔"],"c":2},{"q":[["mq12-l10-exercise-105",13]],"o":[["mq12-l10-exercise-105",14],["mq12-l10-exercise-105",15],["mq12-l10-exercise-105",16],["mq12-l10-exercise-105",17]],"s":["«الْاَعْرَجِ» — لنگڑا (آیت 61)۔"],"c":1},{"q":[["mq12-l10-exercise-105",18]],"o":[["mq12-l10-exercise-105",19],["mq12-l10-exercise-105",20],["mq12-l10-exercise-105",21],["mq12-l10-exercise-105",22]],"s":["«الظَّمْاٰنُ» — پیاسا؛ پیاسا سراب کو پانی سمجھتا ہے (آیت 39)۔"],"c":1},{"q":[["mq12-l10-exercise-106",0]],"o":[["mq12-l10-exercise-106",1],["mq12-l10-exercise-106",2],["mq12-l10-exercise-106",3],["mq12-l10-exercise-106",4]],"s":["«مِنْ جِبَالٍ فِيْهَا مِنْ بَرَدٍ» — پہاڑوں جیسے بادلوں سے اولے برساتا ہے (آیت 43)۔"],"c":0},{"q":[["mq12-l10-exercise-106",5]],"o":[["mq12-l10-exercise-106",6],["mq12-l10-exercise-106",7],["mq12-l10-exercise-106",8],["mq12-l10-exercise-106",9]],"s":["«وَاللّٰهُ خَلَقَ كُلَّ دَآبَّةٍ مِّنْ مَّآءٍ» — اللہ نے ہر جاندار کو پانی سے پیدا کیا (آیت 45)۔"],"c":0},{"q":[["mq12-l10-exercise-106",10]],"o":[["mq12-l10-exercise-106",11],["mq12-l10-exercise-106",12],["mq12-l10-exercise-106",13],["mq12-l10-exercise-106",14]],"s":["«فَمِنْهُمْ مَّنْ يَّمْشِيْ عَلٰى بَطْنِهٖ» — ان میں سے کچھ پیٹ کے بل چلتے ہیں (سانپ وغیرہ)، کچھ دو پاؤں پر اور کچھ چار پر (آیت 45)۔"],"c":2}],"shortQuestions":[{"q":[["mq12-l10-exercise-106",16]],"s":["اللہ نے حکم دیا ہے کہ ان گھروں (مساجد) کو بلند کیا جائے (ان کا ادب کیا جائے) اور ان میں اس کا نام لیا جائے؛ ان میں صبح و شام اس کی تسبیح کی جاتی ہے (آیت 36)۔"]},{"q":[["mq12-l10-exercise-106",17]],"s":["آسمانوں اور زمین میں جو کوئی ہے اور پر پھیلائے ہوئے پرندے، سب اللہ کی تسبیح کرتے ہیں؛ ہر ایک اپنی نماز اور تسبیح کا طریقہ جانتا ہے اور اللہ ان کے کاموں کو جانتا ہے (آیت 41)۔"]},{"q":[["mq12-l10-exercise-106",18]],"s":["اللہ بادلوں کو چلاتا، پھر انہیں جوڑتا اور تہ بہ تہ کرتا ہے، پھر ان کے بیچ سے بارش نکلتی ہے؛ وہ آسمان سے پہاڑوں (جیسے بادلوں) سے اولے برساتا ہے، جسے چاہے ان سے نقصان پہنچائے اور جس سے چاہے پھیر دے؛ اس کی بجلی کی چمک آنکھوں کی روشنی اچک لینے کو ہوتی ہے (آیت 43)۔"]},{"q":[["mq12-l10-exercise-106",19]],"s":["کامیاب وہ لوگ ہیں جنہیں اللہ اور رسول کی طرف بلایا جائے تاکہ وہ ان کے درمیان فیصلہ کریں تو کہیں: ہم نے سنا اور اطاعت کی (آیت 51)؛ اور جو اللہ اور رسول کی اطاعت کرے، اللہ سے ڈرے اور تقویٰ اختیار کرے وہی کامیاب ہیں (آیت 52)۔"]},{"q":[["mq12-l10-exercise-106",20]],"s":["اگر تم رسول ﷺ کی اطاعت کرو گے تو ہدایت پا لو گے (آیت 54)؛ نیز ایمان اور نیک عمل والوں سے اللہ کا وعدہ ہے کہ انہیں زمین میں خلافت دے گا، ان کے دین کو مضبوط کرے گا اور خوف کو امن سے بدل دے گا (آیت 55)؛ اطاعت پر رحمت کا وعدہ (آیت 56)۔"]},{"q":[["mq12-l10-exercise-106",21]],"s":["بچوں سے متعلق ادب: نابالغ بچے اور ملازم تین اوقات میں — فجر کی نماز سے پہلے، دوپہر کو جب کپڑے اتار کر آرام کرتے ہو، اور عشا کی نماز کے بعد — گھر والوں کے کمرے میں داخل ہونے سے پہلے اجازت لیں؛ یہ تین پردے کے اوقات ہیں؛ اور جب بچے بالغ ہو جائیں تو ہر وقت اجازت لیں (آیات 58–59)۔"]},{"q":[["mq12-l10-exercise-106",22]],"s":["جو لوگ رسول ﷺ کے حکم کی مخالفت کرتے ہیں انہیں ڈرنا چاہیے کہ ان پر کوئی فتنہ (آزمائش) آ پڑے یا انہیں دردناک عذاب پہنچے (آیت 63)۔"]}],"longQuestions":[{"q":[["mq12-l10-exercise-106",24]],"s":["ترجمہ: تاکہ اللہ انہیں ان کے بہترین اعمال کا بدلہ دے اور اپنے فضل سے انہیں مزید عطا کرے؛ اور اللہ جسے چاہتا ہے بے حساب رزق دیتا ہے۔ (النور 38)","تشریح: مسجدوں کو آباد رکھنے اور ذکر کرنے والوں کو ان کے اعمال کے بہترین بدلے کے ساتھ اللہ کا مزید فضل اور بے حساب رزق ملے گا۔"]},{"q":[["mq12-l10-exercise-106",25]],"s":["اللہ کے بندوں کی صفات: (1) انہیں تجارت اور خرید و فروخت اللہ کے ذکر سے غافل نہیں کرتی؛ (2) وہ نماز قائم کرتے ہیں؛ (3) زکوٰۃ ادا کرتے ہیں؛ (4) وہ اس دن (قیامت) سے ڈرتے ہیں جس میں دل اور آنکھیں الٹ پلٹ ہو جائیں گی۔ (النور 37)","یعنی وہ دنیاوی کاروبار کرتے ہیں مگر اللہ کے حقوق کو مقدم رکھتے ہیں — یہی متوازن مومن کی تصویر ہے۔"]},{"q":[["mq12-l10-exercise-106",26]],"s":["ترجمہ: اور جن لوگوں نے کفر کیا ان کے اعمال چٹیل میدان میں سراب کی طرح ہیں جسے پیاسا پانی سمجھتا ہے، یہاں تک کہ جب اس کے پاس آتا ہے تو کچھ نہیں پاتا، اور وہاں اللہ کو پاتا ہے جو اس کا پورا حساب چکا دیتا ہے؛ اور اللہ جلد حساب لینے والا ہے۔ (النور 39)","تشریح: ایمان کے بغیر کیے گئے نیک نظر آنے والے اعمال آخرت میں سراب کی طرح بے حقیقت ثابت ہوں گے۔"]},{"q":[["mq12-l10-exercise-106",27]],"s":["ہدایت: اے ایمان والو! تمہارے غلام (ملازم) اور تمہارے وہ بچے جو ابھی بلوغت کو نہیں پہنچے تین اوقات میں (تمہارے کمرے میں آنے سے پہلے) اجازت لیں: فجر کی نماز سے پہلے، دوپہر کو جب تم (آرام کے لیے) کپڑے اتار دیتے ہو، اور عشا کی نماز کے بعد۔ (النور 58)","یہ تین اوقات تمہارے پردے کے ہیں؛ ان کے علاوہ اوقات میں (بار بار آمد و رفت کی وجہ سے) نہ تم پر کوئی گناہ ہے نہ ان پر — یہ گھریلو حیا اور تربیت کا ادب ہے۔"]},{"q":[["mq12-l10-exercise-107",0]],"s":["ترجمہ: اور وہ (منافق) کہتے ہیں کہ ہم اللہ اور رسول پر ایمان لائے اور ہم نے اطاعت کی، پھر اس کے بعد ان میں سے ایک گروہ منہ پھیر لیتا ہے؛ اور یہ لوگ ایمان والے نہیں ہیں۔ (النور 47)","تشریح: زبانی ایمان اور عملی نافرمانی منافقت کی علامت ہے؛ جب فیصلہ ان کے خلاف ہو تو رسول ﷺ کے پاس آنے سے کتراتے ہیں۔"]},{"q":[["mq12-l10-exercise-107",1]],"s":["رخصت: وہ بڑی عمر کی عورتیں جو گھروں میں بیٹھ رہی ہوں (قواعد) اور نکاح کی امید نہ رکھتی ہوں، ان پر کوئی گناہ نہیں کہ اپنے (اوپر کے زائد) کپڑے (چادر) اتار دیں، بشرطیکہ زینت کی نمائش کرنے والی نہ ہوں۔ (النور 60)","تاہم اگر وہ بھی (پردے میں) احتیاط برتیں تو یہ ان کے لیے بہتر ہے؛ اور اللہ سننے والا، جاننے والا ہے۔"]}],"activities":[{"q":[["mq12-l10-exercise-107",3],["mq12-l10-exercise-107",4]],"s":["منافقین کا رویہ (سورۃ النور): واقعۂ افک میں بہتان تراشی (11–20)؛ زبان سے ایمان مگر عمل میں روگردانی (47)؛ اپنے حق میں فیصلہ ہو تو رسول ﷺ کے پاس آنا ورنہ کترانا (48–50)؛ جھوٹی قسمیں کھانا (53)؛ اجتماعی کاموں سے چپکے سے کھسک جانا (63)۔ سچے مومنوں کا رویہ: بہتان سن کر حسنِ ظن رکھنا (12)؛ \"سمعنا و اطعنا\" (51)؛ ذکر، نماز اور زکوٰۃ (37)؛ رسول ﷺ کی مجلس سے اجازت لے کر جانا (62)؛ ان سے خلافت کا وعدہ (55)۔","النور 61 کے مطابق وہ گھر جہاں سے کھانے کی اجازت ہے (معذوروں — اندھے، لنگڑے، بیمار — اور سب کے لیے): اپنے گھر، باپ دادا کے گھر، ماؤں کے گھر، بھائیوں کے، بہنوں کے، چچاؤں کے، پھوپھیوں کے، ماموؤں کے، خالاؤں کے گھر، وہ گھر جن کی کنجیاں تمہارے اختیار میں ہوں، اور دوستوں کے گھر؛ اکٹھے یا الگ الگ کھانے میں حرج نہیں؛ گھروں میں داخل ہوتے وقت سلام کرو۔"]}]}},"11":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l11-exercise-115",2]],"o":[["mq12-l11-exercise-115",3],["mq12-l11-exercise-115",4],["mq12-l11-exercise-115",5],["mq12-l11-exercise-115",6]],"s":["«وَاتَّبِعْ مَا يُوْحٰٓى اِلَيْكَ مِنْ رَّبِّكَ» — جو وحی آپ کے رب کی طرف سے آتی ہے اس کی پیروی کیجیے (الاحزاب 2)۔"],"c":2},{"q":[["mq12-l11-exercise-115",7]],"o":[["mq12-l11-exercise-115",8],["mq12-l11-exercise-115",9],["mq12-l11-exercise-115",10],["mq12-l11-exercise-115",11]],"s":["«اَلنَّبِيُّ اَوْلٰى بِالْمُؤْمِنِيْنَ مِنْ اَنْفُسِهِمْ» — نبی ﷺ مومنوں پر ان کی جانوں سے بھی زیادہ حق رکھتے ہیں (آیت 6)۔"],"c":0},{"q":[["mq12-l11-exercise-115",12]],"o":[["mq12-l11-exercise-115",13],["mq12-l11-exercise-115",14],["mq12-l11-exercise-115",15],["mq12-l11-exercise-115",16]],"s":["«اِنَّ بُيُوْتَنَا عَوْرَةٌ» — ہمارے گھر غیر محفوظ (کھلے) ہیں؛ منافقین یہ بہانہ بنا کر غزوۂ احزاب سے واپسی کی اجازت مانگتے تھے (آیت 13)۔"],"c":2},{"q":[["mq12-l11-exercise-115",17]],"o":[["mq12-l11-exercise-115",18],["mq12-l11-exercise-115",19],["mq12-l11-exercise-115",20],["mq12-l11-exercise-115",21]],"s":["«فَاَرْسَلْنَا عَلَيْهِمْ رِيْحًا» — ہم نے ان (کافر لشکروں) پر تیز آندھی بھیجی اور ایسے لشکر جو تم نے نہیں دیکھے (آیت 9)۔"],"c":0},{"q":[["mq12-l11-exercise-115",22]],"o":[["mq12-l11-exercise-115",23],["mq12-l11-exercise-115",24],["mq12-l11-exercise-115",25],["mq12-l11-exercise-115",26]],"s":["«اَشِحَّةً عَلَيْكُمْ» — منافق تمہارے بارے میں بہت بخیل ہیں (مدد اور مال میں) (آیت 19)۔"],"c":0},{"q":[["mq12-l11-exercise-115",27]],"o":[["mq12-l11-exercise-115",28],["mq12-l11-exercise-115",29],["mq12-l11-exercise-115",30],["mq12-l11-exercise-115",31]],"s":["«وَتَاْسِرُوْنَ فَرِيْقًا» — اور ایک گروہ (بنو قریظہ) کو تم نے قیدی بنا لیا (آیت 26)۔"],"c":2},{"q":[["mq12-l11-exercise-115",32]],"o":[["mq12-l11-exercise-115",33],["mq12-l11-exercise-115",34],["mq12-l11-exercise-115",35],["mq12-l11-exercise-115",36]],"s":["«فَلَا تَخْضَعْنَ بِالْقَوْلِ» — امہات المؤمنینؓ کو ہدایت کہ (غیر محرموں سے) نرم اور لچک دار لہجے میں بات نہ کریں تاکہ بیمار دل والا لالچ نہ کرے (آیت 32)۔"],"c":0}],"shortQuestions":[{"q":[["mq12-l11-exercise-115",38]],"s":["اے نبی! اللہ سے ڈرتے رہیے اور کافروں اور منافقوں کی بات نہ مانیے؛ بے شک اللہ جاننے والا، حکمت والا ہے (آیت 1)؛ اور وحی کی پیروی اور اللہ پر توکل کیجیے (آیات 2–3)۔"]},{"q":[["mq12-l11-exercise-115",39]],"s":["اللہ نے تمہارے منہ بولے بیٹوں کو تمہارا (حقیقی) بیٹا نہیں بنایا؛ یہ صرف تمہاری زبان کی باتیں ہیں؛ اللہ حق بات کہتا ہے اور سیدھی راہ دکھاتا ہے؛ انہیں ان کے اصل باپوں کے نام سے پکارو (آیات 4–5)۔"]},{"q":[["mq12-l11-exercise-115",40]],"s":["غزوۂ احزاب میں جب دشمن اوپر (مشرق) سے اور نیچے (مغرب) سے تم پر چڑھ آئے، جب آنکھیں پتھرا گئیں، کلیجے منہ کو آ گئے اور تم اللہ کے بارے میں طرح طرح کے گمان کرنے لگے — یہ مومنوں کی سخت آزمائش تھی اور وہ بری طرح ہلا دیے گئے (آیات 10–11)۔"]},{"q":[["mq12-l11-exercise-115",41]],"s":["کہہ دیجیے: اگر تم موت یا قتل سے بھاگو تو یہ بھاگنا تمہیں کوئی فائدہ نہ دے گا، اور اس صورت میں بھی تمہیں (زندگی کا) تھوڑا ہی فائدہ اٹھانے دیا جائے گا (آیت 16)۔"]},{"q":[["mq12-l11-exercise-116",0]],"s":["جب مومنوں نے لشکروں کو دیکھا تو کہا: یہ وہی ہے جس کا اللہ اور اس کے رسول نے ہم سے وعدہ کیا تھا، اور اللہ اور اس کے رسول نے سچ کہا؛ اور اس (منظر) نے ان کے ایمان اور فرمانبرداری کو اور بڑھا دیا (آیت 22)۔"]},{"q":[["mq12-l11-exercise-116",1]],"s":["تم (ازواجِ مطہراتؓ) میں سے جو اللہ اور اس کے رسول کی اطاعت کرے اور نیک عمل کرے ہم اسے دگنا اجر دیں گے اور اس کے لیے ہم نے عزت کی روزی تیار کر رکھی ہے (آیت 31)۔"]},{"q":[["mq12-l11-exercise-116",2]],"s":["امہات المؤمنینؓ کو ہدایات: اپنے گھروں میں وقار سے رہیں، پہلی جاہلیت کی طرح بناؤ سنگھار کی نمائش نہ کریں، نماز قائم کریں، زکوٰۃ دیں اور اللہ اور اس کے رسول کی اطاعت کریں؛ اللہ چاہتا ہے کہ اے اہلِ بیت! تم سے ناپاکی دور کرے اور تمہیں خوب پاک کرے (آیت 33)۔"]}],"longQuestions":[{"q":[["mq12-l11-exercise-116",4]],"s":["ترجمہ: نبی ﷺ مومنوں پر ان کی جانوں سے بھی زیادہ حق رکھتے ہیں، اور آپ کی بیویاں ان کی مائیں ہیں؛ اور اللہ کی کتاب میں رشتہ دار ایک دوسرے کے (وراثت میں) دوسرے مومنوں اور مہاجرین سے زیادہ حق دار ہیں، مگر یہ کہ تم اپنے دوستوں کے ساتھ کوئی بھلائی (وصیت) کرنا چاہو؛ یہ بات کتاب میں لکھی ہوئی ہے۔ (الاحزاب 6)","تشریح: نبی ﷺ کی محبت و اطاعت ہر چیز پر مقدم ہے؛ ازواجِ مطہرات احترام اور نکاح کی حرمت میں مومنوں کی مائیں ہیں؛ مواخاۃ کی بنیاد پر وراثت منسوخ ہو کر رشتہ داری پر قائم ہوئی۔"]},{"q":[["mq12-l11-exercise-116",5]],"s":["سورۃ الاحزاب مدنی سورت ہے؛ اس میں 73 آیات اور 9 رکوع ہیں؛ یہ 5ھ میں غزوۂ احزاب (خندق) اور غزوۂ بنی قریظہ کے موقع پر اور اس کے بعد نازل ہوئی۔","نام: اس میں کفار کے متحدہ لشکروں (احزاب) کے مدینہ پر حملے کا ذکر ہے، اسی سے نام \"الاحزاب\" ہے۔","پس منظر: قریش، غطفان اور یہود کے دس بارہ ہزار کے لشکر نے مدینہ کا محاصرہ کیا؛ مسلمانوں نے حضرت سلمان فارسیؓ کے مشورے سے خندق کھودی؛ اللہ نے آندھی اور فرشتوں سے مدد کی؛ اسی دور میں متبنیٰ (منہ بولے بیٹے) کی رسم کا خاتمہ، حضرت زینبؓ سے نکاح اور پردے کے احکام نازل ہوئے۔"]},{"q":[["mq12-l11-exercise-116",6]],"s":["ترجمہ: اور (یاد کرو) جب ہم نے نبیوں سے ان کا عہد لیا، اور آپ سے بھی، اور نوح، ابراہیم، موسیٰ اور عیسیٰ ابنِ مریم سے بھی؛ اور ہم نے ان سے پختہ عہد لیا۔ (الاحزاب 7)","تشریح: تمام انبیا سے — بالخصوص اولو العزم رسولوں سے — یہ پختہ عہد لیا گیا کہ وہ اللہ کا پیغام پوری طرح پہنچائیں گے اور ایک دوسرے کی تصدیق کریں گے؛ نبی ﷺ کا ذکر پہلے آنا آپ کی فضیلت کی دلیل ہے۔"]},{"q":[["mq12-l11-exercise-116",7]],"s":["سورۃ الاحزاب کے بنیادی مضامین: (1) غزوۂ احزاب کے حالات، مومنوں کی آزمائش، منافقین کے بہانے اور اللہ کی مدد؛ غزوۂ بنی قریظہ؛ (2) نبی ﷺ کی اسوۂ حسنہ کی پیروی؛ (3) متبنیٰ کی رسم کا خاتمہ اور حضرت زیدؓ اور حضرت زینبؓ کا واقعہ؛ (4) ختمِ نبوت کا اعلان (آیت 40)۔","(5) ازواجِ مطہراتؓ کو اختیار (تخییر) اور ان کے لیے خصوصی ہدایات؛ اہلِ بیت کی پاکیزگی؛ (6) پردے کے احکام — حجاب، جلباب، نبی ﷺ کے گھروں میں داخلے کے آداب؛ (7) طلاق قبل از رخصتی کا حکم (عدت نہیں)۔","(8) نبی ﷺ پر درود و سلام کا حکم؛ نبی ﷺ اور مومنوں کو ایذا دینے کی مذمت؛ (9) مومن مردوں اور عورتوں کی دس صفات (آیت 35)؛ (10) امانت کا بیان جو آسمان، زمین اور پہاڑوں نے نہ اٹھائی اور انسان نے اٹھا لی (آیت 72)۔"]},{"q":[["mq12-l11-exercise-116",8]],"s":["ترجمہ: اے ایمان والو! اللہ کی اس نعمت کو یاد کرو جو تم پر ہوئی جب تم پر (دشمن کے) لشکر چڑھ آئے تو ہم نے ان پر آندھی بھیجی اور ایسے لشکر (فرشتے) بھیجے جو تم نے نہیں دیکھے؛ اور اللہ تمہارے کاموں کو دیکھ رہا ہے۔ (الاحزاب 9)","تشریح: غزوۂ احزاب میں سخت سردی کی رات تیز آندھی نے کفار کے خیمے اکھاڑ دیے، آگ بجھ گئی اور وہ محاصرہ چھوڑ کر بھاگ گئے؛ یہ اللہ کی غیبی مدد تھی۔"]},{"q":[["mq12-l11-exercise-116",9]],"s":["تعلیم: بے شک تمہارے لیے رسول اللہ ﷺ (کی زندگی) میں بہترین نمونہ ہے، اس شخص کے لیے جو اللہ اور آخرت کے دن کی امید رکھتا ہو اور اللہ کو کثرت سے یاد کرتا ہو۔ (الاحزاب 21)","یعنی عقائد، عبادات، اخلاق، معاملات، صبر، بہادری اور زندگی کے ہر شعبے میں نبی ﷺ کی پیروی لازم ہے — غزوۂ خندق میں آپ ﷺ نے خود خندق کھودی، بھوک برداشت کی اور ثابت قدم رہے؛ اسوۂ حسنہ کی پیروی کی شرط اللہ اور آخرت کی امید اور کثرتِ ذکر ہے۔"]}],"activities":[{"q":[["mq12-l11-exercise-116",11],["mq12-l11-exercise-116",12]],"s":["اہلِ بیت کے فضائل کی احادیث: (1) حدیثِ کساء — آپ ﷺ نے حضرت علی، فاطمہ، حسن اور حسین رضی اللہ عنہم کو چادر میں لے کر فرمایا: اے اللہ! یہ میرے اہلِ بیت ہیں، ان سے ناپاکی دور کر دے (صحیح مسلم)؛ (2) فاطمہ میرے جگر کا ٹکڑا ہے؛ (3) حسن و حسین جنت کے نوجوانوں کے سردار ہیں؛ (4) میں تم میں اللہ کی کتاب اور اپنے اہلِ بیت چھوڑ رہا ہوں (حدیثِ ثقلین)۔ آیتِ تطہیر (الاحزاب 33) میں ازواجِ مطہرات بھی اہلِ بیت میں شامل ہیں۔","غزوۂ احزاب کے اہم نکات: 5ھ (شوال) میں قریش، غطفان اور یہود (بنو نضیر، بعد میں بنو قریظہ کی غداری) کا تقریباً دس ہزار کا لشکر؛ حضرت سلمان فارسیؓ کے مشورے سے مدینہ کے شمال میں خندق؛ تقریباً ایک ماہ محاصرہ؛ منافقین کے بہانے؛ شدید سردی، بھوک اور خوف؛ عمرو بن عبد ود کا حضرت علیؓ کے ہاتھوں قتل؛ آندھی اور فرشتوں کی مدد سے کفار کی پسپائی؛ اس کے بعد بنو قریظہ کا محاصرہ اور سزا؛ نبی ﷺ نے فرمایا: اب ہم ان پر چڑھائی کریں گے، وہ ہم پر نہیں۔"]}]}},"12":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l12-exercise-124",2]],"o":[["mq12-l12-exercise-124",3],["mq12-l12-exercise-124",4],["mq12-l12-exercise-124",5],["mq12-l12-exercise-124",6]],"s":["«الْقٰنِتِيْنَ» — فرمانبردار (اطاعت کرنے والے) مرد (الاحزاب 35)۔"],"c":2},{"q":[["mq12-l12-exercise-124",7]],"o":[["mq12-l12-exercise-124",8],["mq12-l12-exercise-124",9],["mq12-l12-exercise-124",10],["mq12-l12-exercise-124",11]],"s":["«وَالْحٰفِظِيْنَ فُرُوْجَهُمْ وَالْحٰفِظٰتِ» — اپنی شرم گاہوں کی حفاظت کرنے والے مرد اور عورتیں (آیت 35)۔"],"c":3},{"q":[["mq12-l12-exercise-124",12]],"o":[["mq12-l12-exercise-124",13],["mq12-l12-exercise-124",14],["mq12-l12-exercise-124",15],["mq12-l12-exercise-124",16]],"s":["«وَاللّٰهُ اَحَقُّ اَنْ تَخْشٰىهُ» — اللہ اس کا زیادہ حق دار ہے کہ اس سے ڈرا جائے (آیت 37)۔"],"c":3},{"q":[["mq12-l12-exercise-124",17]],"o":[["mq12-l12-exercise-124",18],["mq12-l12-exercise-124",19],["mq12-l12-exercise-124",20],["mq12-l12-exercise-124",21]],"s":["«مُبَشِّرًا» — خوشخبری دینے والا (آیت 45)۔"],"c":1},{"q":[["mq12-l12-exercise-124",22]],"o":[["mq12-l12-exercise-124",23],["mq12-l12-exercise-124",24],["mq12-l12-exercise-124",25],["mq12-l12-exercise-124",26]],"s":["«وَسِرَاجًا مُّنِيْرًا» — روشن کرنے والا چراغ (آیت 46)۔"],"c":2},{"q":[["mq12-l12-exercise-124",27]],"o":[["mq12-l12-exercise-124",28],["mq12-l12-exercise-124",29],["mq12-l12-exercise-124",30],["mq12-l12-exercise-124",31]],"s":["«مُسْتَاْنِسِيْنَ لِحَدِيْثٍ» — باتوں میں دل لگا کر (کھانے کے بعد) بیٹھے رہنا (آیت 53)۔"],"c":0},{"q":[["mq12-l12-exercise-124",32]],"o":[["mq12-l12-exercise-124",33],["mq12-l12-exercise-124",34],["mq12-l12-exercise-124",35],["mq12-l12-exercise-124",36]],"s":["«قَوْلًا سَدِيْدًا» — سیدھی، درست اور سچی بات (آیت 70)۔"],"c":2}],"shortQuestions":[{"q":[["mq12-l12-exercise-124",38]],"s":["انبیا کی صفات: وہ اللہ کے پیغامات پہنچاتے ہیں، اسی سے ڈرتے ہیں اور اللہ کے سوا کسی سے نہیں ڈرتے؛ اور حساب لینے کے لیے اللہ کافی ہے (آیت 39)۔"]},{"q":[["mq12-l12-exercise-124",39]],"s":["جس دن وہ اللہ سے ملیں گے ان کا استقبال \"سلام\" سے ہوگا اور اللہ نے ان کے لیے عزت والا اجر تیار کر رکھا ہے (آیت 44)۔"]},{"q":[["mq12-l12-exercise-125",0]],"s":["دو باتوں سے منع کیا گیا: (1) رسول اللہ ﷺ کو کسی طرح کی ایذا دینا؛ (2) آپ کے بعد آپ کی ازواجِ مطہرات سے کبھی نکاح کرنا؛ یہ اللہ کے نزدیک بہت بڑا گناہ ہے (آیت 53)۔"]},{"q":[["mq12-l12-exercise-125",1]],"s":["اللہ اور اس کے فرشتے نبی ﷺ پر درود بھیجتے ہیں؛ اے ایمان والو! تم بھی آپ پر درود بھیجو اور خوب سلام بھیجو (آیت 56)۔"]},{"q":[["mq12-l12-exercise-125",2]],"s":["اے نبی! اپنی بیویوں، بیٹیوں اور مومنوں کی عورتوں سے کہہ دیجیے کہ (باہر نکلتے وقت) اپنی چادروں (جلابیب) کا کچھ حصہ اپنے اوپر لٹکا لیا کریں (چہرہ اور جسم ڈھانپ لیں) (آیت 59)۔"]},{"q":[["mq12-l12-exercise-125",3]],"s":["پردے کی حکمت: اس سے وہ جلد پہچان لی جائیں گی (کہ شریف اور باحیا خواتین ہیں) تو انہیں ستایا (چھیڑا) نہ جائے گا؛ اور اللہ بخشنے والا، مہربان ہے (آیت 59)۔"]},{"q":[["mq12-l12-exercise-125",4]],"s":["لوگ آپ سے قیامت کے بارے میں پوچھتے ہیں؛ کہہ دیجیے: اس کا علم تو صرف اللہ کے پاس ہے؛ اور آپ کو کیا معلوم، شاید قیامت قریب ہی ہو (آیت 63)۔"]}],"longQuestions":[{"q":[["mq12-l12-exercise-125",6]],"s":["ترجمہ: اور کسی مومن مرد اور مومن عورت کو یہ حق نہیں کہ جب اللہ اور اس کا رسول کسی معاملے کا فیصلہ کر دیں تو انہیں اپنے معاملے میں (کوئی دوسرا) اختیار باقی رہے؛ اور جو اللہ اور اس کے رسول کی نافرمانی کرے وہ کھلی گمراہی میں جا پڑا۔ (الاحزاب 36)","تشریح: یہ آیت حضرت زینب بنت جحشؓ کے حضرت زیدؓ سے نکاح کے موقع پر نازل ہوئی؛ اللہ اور رسول ﷺ کا فیصلہ آ جائے تو مومن کو سرِ تسلیم خم کرنا چاہیے۔"]},{"q":[["mq12-l12-exercise-125",7]],"s":["عدت کے احکام: اے ایمان والو! جب تم مومن عورتوں سے نکاح کرو پھر انہیں چھونے (رخصتی/خلوت) سے پہلے طلاق دے دو تو ان پر تمہارے لیے کوئی عدت نہیں جس کی تم گنتی کرو۔ (الاحزاب 49)","انہیں کچھ سامان (متاع/تحفہ) دو اور خوبصورتی سے رخصت کرو — یعنی ایسی مطلقہ فوراً دوسرا نکاح کر سکتی ہے؛ اگر مہر مقرر تھا تو آدھا مہر دینا ہوگا (البقرہ 237)۔"]},{"q":[["mq12-l12-exercise-125",8]],"s":["ترجمہ: محمد (ﷺ) تمہارے مردوں میں سے کسی کے باپ نہیں، لیکن وہ اللہ کے رسول اور خاتم النبیین (سب نبیوں کے آخر میں آنے والے) ہیں؛ اور اللہ ہر چیز کو جاننے والا ہے۔ اے ایمان والو! اللہ کو کثرت سے یاد کرو۔ (الاحزاب 40–41)","تشریح: پہلی آیت متبنیٰ کی رسم کے خاتمے کے ساتھ ختمِ نبوت کا صریح اعلان ہے؛ دوسری آیت میں کثرتِ ذکر اور صبح و شام تسبیح کا حکم ہے۔"]},{"q":[["mq12-l12-exercise-125",9]],"s":["ازواجِ مطہراتؓ کو ان لوگوں کے سامنے پردے سے استثنا دیا گیا: اپنے باپ، اپنے بیٹے، اپنے بھائی، اپنے بھتیجے، اپنے بھانجے، اپنی (مسلمان) عورتیں اور اپنے غلام۔ (الاحزاب 55)","اور (اے نبی کی بیویو!) اللہ سے ڈرتی رہو؛ بے شک اللہ ہر چیز پر گواہ ہے۔"]},{"q":[["mq12-l12-exercise-125",10]],"s":["ترجمہ: اور جو لوگ مومن مردوں اور مومن عورتوں کو بغیر کسی قصور کے ایذا دیتے ہیں انہوں نے بہتان اور کھلے گناہ کا بوجھ اٹھایا۔ (الاحزاب 58)","تشریح: کسی بے قصور مسلمان کو زبان یا ہاتھ سے تکلیف دینا، اس پر الزام لگانا یا اس کی عزت پر حملہ کرنا کبیرہ گناہ ہے۔"]},{"q":[["mq12-l12-exercise-125",11]],"s":["تعلیمات (آدابِ مہمانی): اے ایمان والو! نبی ﷺ کے گھروں میں داخل نہ ہو مگر جب تمہیں کھانے کے لیے اجازت دی جائے، اور کھانا پکنے کا انتظار کرتے ہوئے (پہلے سے) نہ بیٹھو؛ لیکن جب بلایا جائے تو داخل ہو، اور جب کھا چکو تو منتشر ہو جاؤ اور باتوں میں دل لگا کر نہ بیٹھے رہو۔ (الاحزاب 53)","اس سے نبی ﷺ کو تکلیف ہوتی تھی مگر وہ حیا کی وجہ سے کچھ نہیں کہتے تھے؛ اور جب ازواجِ مطہرات سے کوئی چیز مانگو تو پردے کے پیچھے سے مانگو — یہ تمہارے اور ان کے دلوں کے لیے زیادہ پاکیزہ ہے (آیتِ حجاب)۔"]}],"activities":[{"q":[["mq12-l12-exercise-126",1],["mq12-l12-exercise-126",2],["mq12-l12-exercise-126",3]],"s":["مومن مردوں اور عورتوں کی صفات (الاحزاب 35): مسلمان (فرمانبردار)، مومن، قانت (اطاعت گزار)، صادق (سچے)، صابر، خاشع (عاجزی کرنے والے)، صدقہ دینے والے، روزہ رکھنے والے، شرم گاہوں کی حفاظت کرنے والے، اور اللہ کو کثرت سے یاد کرنے والے — ان کے لیے مغفرت اور اجرِ عظیم ہے۔","نبی ﷺ سے متعلق خصوصی احکام: آپ مومنوں پر ان کی جانوں سے زیادہ حق رکھتے ہیں؛ ازواجِ مطہرات مومنوں کی مائیں ہیں اور آپ کے بعد ان سے نکاح حرام؛ آپ خاتم النبیین ہیں؛ آپ کی ذات اسوۂ حسنہ ہے؛ آپ کے گھروں میں داخلے کے آداب؛ آپ کو ایذا دینا حرام؛ آپ پر درود و سلام کا حکم؛ اللہ اور رسول کے فیصلے کے بعد کسی کو اختیار نہیں۔","درود شریف کے فضائل کی احادیث: (1) جو مجھ پر ایک بار درود بھیجے اللہ اس پر دس رحمتیں نازل فرماتا ہے (صحیح مسلم)؛ (2) قیامت کے دن مجھ سے سب سے زیادہ قریب وہ ہوگا جو مجھ پر سب سے زیادہ درود بھیجے (ترمذی)؛ (3) بخیل وہ ہے جس کے سامنے میرا ذکر ہو اور وہ مجھ پر درود نہ بھیجے (ترمذی) — روزانہ درودِ ابراہیمی پڑھنے کا معمول بنائیں۔"]}]}},"13":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l13-exercise-135",3]],"o":[["mq12-l13-exercise-135",4],["mq12-l13-exercise-135",5],["mq12-l13-exercise-135",6],["mq12-l13-exercise-135",7]],"s":["سورۃ حٰم السجدہ (فصلت) ان سات سورتوں میں سے ہے جو \"حم\" سے شروع ہوتی ہیں اور حوامیم کہلاتی ہیں (المؤمن سے الاحقاف تک)۔"],"c":3},{"q":[["mq12-l13-exercise-135",8]],"o":[["mq12-l13-exercise-135",9],["mq12-l13-exercise-135",10],["mq12-l13-exercise-135",11],["mq12-l13-exercise-135",12]],"s":["«وَيْلٌ» — تباہی، ہلاکت (خرابی)؛ مشرکوں کے لیے تباہی ہے (آیت 6)۔"],"c":2},{"q":[["mq12-l13-exercise-135",13]],"o":[["mq12-l13-exercise-135",14],["mq12-l13-exercise-135",15],["mq12-l13-exercise-135",16],["mq12-l13-exercise-135",17]],"s":["«اِدْفَعْ بِالَّتِيْ هِيَ اَحْسَنُ» — برائی کو اس طریقے سے دور کرو جو سب سے اچھا ہو، یعنی بھلائی سے (آیت 34)۔"],"c":2},{"q":[["mq12-l13-exercise-135",18]],"o":[["mq12-l13-exercise-135",19],["mq12-l13-exercise-135",20],["mq12-l13-exercise-135",21],["mq12-l13-exercise-135",22]],"s":["«فَاسْتَعِذْ بِاللّٰهِ» — تو اللہ کی پناہ مانگو (آیت 36)۔"],"c":0},{"q":[["mq12-l13-exercise-135",23]],"o":[["mq12-l13-exercise-135",24],["mq12-l13-exercise-135",25],["mq12-l13-exercise-135",26],["mq12-l13-exercise-135",27]],"s":["«وَقْرٌ» — بوجھ، ڈاٹ (بھاری پن)؛ ہمارے کانوں میں بوجھ ہے (آیت 5، 44)۔"],"c":1},{"q":[["mq12-l13-exercise-136",0]],"o":[["mq12-l13-exercise-136",1],["mq12-l13-exercise-136",2],["mq12-l13-exercise-136",3],["mq12-l13-exercise-136",4]],"s":["«مَّحِيْصٍ» — بھاگنے کی جگہ، چھٹکارا (آیت 48)۔"],"c":2},{"q":[["mq12-l13-exercise-136",5]],"o":[["mq12-l13-exercise-136",6],["mq12-l13-exercise-136",7],["mq12-l13-exercise-136",8],["mq12-l13-exercise-136",9]],"s":["«فَيَئُوْسٌ قَنُوْطٌ» — مایوس اور ناامید ہو جاتا ہے (آیت 49)۔"],"c":2}],"shortQuestions":[{"q":[["mq12-l13-exercise-136",11]],"s":["کافروں نے دعوتِ توحید کے جواب میں کہا: جس چیز کی طرف تم ہمیں بلاتے ہو ہمارے دل اس سے پردوں میں ہیں، ہمارے کانوں میں بوجھ ہے اور ہمارے اور تمہارے درمیان پردہ (رکاوٹ) ہے؛ پس تم اپنا کام کرو، ہم اپنا کام کر رہے ہیں (آیت 5)۔"]},{"q":[["mq12-l13-exercise-136",12]],"s":["اگر وہ منہ موڑیں تو کہہ دیجیے کہ میں تمہیں ایسی کڑک (صاعقہ، عذاب) سے ڈراتا ہوں جیسی عاد اور ثمود پر آئی تھی (آیت 13)۔"]},{"q":[["mq12-l13-exercise-136",13]],"s":["قومِ عاد نے تکبر کیا تو ہم نے ان پر منحوس دنوں میں سخت ٹھنڈی تیز آندھی بھیجی تاکہ انہیں دنیا ہی میں رسوائی کا عذاب چکھائیں، اور آخرت کا عذاب اس سے بڑھ کر رسوا کن ہے اور ان کی کوئی مدد نہ ہوگی (آیت 16)۔"]},{"q":[["mq12-l13-exercise-136",14]],"s":["قیامت کے دن انسان کے کان، آنکھیں اور کھالیں (جلد) اس کے اعمال کی گواہی دیں گی (آیات 20–22)۔"]},{"q":[["mq12-l13-exercise-136",15]],"s":["کافروں نے کہا: اس قرآن کو نہ سنو اور (اس کی تلاوت کے وقت) شور مچاؤ تاکہ تم غالب آ جاؤ (آیت 26)۔"]},{"q":[["mq12-l13-exercise-136",16]],"s":["سب سے اچھی بات اس شخص کی ہے جو اللہ کی طرف بلائے، نیک عمل کرے اور کہے کہ میں مسلمانوں (فرمانبرداروں) میں سے ہوں (آیت 33)۔"]},{"q":[["mq12-l13-exercise-136",17]],"s":["جب ہم انسان پر انعام کرتے ہیں تو وہ منہ پھیر لیتا اور پہلو بدل لیتا ہے (تکبر سے دور ہو جاتا ہے)، اور جب اسے تکلیف پہنچتی ہے تو لمبی چوڑی دعائیں کرنے لگتا ہے (آیت 51) — یعنی خوشی میں غفلت اور غم میں بے صبری۔"]}],"longQuestions":[{"q":[["mq12-l13-exercise-136",19]],"s":["ترجمہ: بے شک جن لوگوں نے کہا کہ ہمارا رب اللہ ہے، پھر اس پر ثابت قدم رہے، ان پر فرشتے اترتے ہیں (اور کہتے ہیں) کہ نہ ڈرو اور نہ غم کرو، اور اس جنت کی خوشخبری سنو جس کا تم سے وعدہ کیا جاتا تھا۔ (حٰم السجدہ 30)","تشریح: ایمان کے ساتھ استقامت (عقیدے اور عمل پر جمے رہنا) سب سے بڑی کرامت ہے؛ موت کے وقت، قبر میں اور قیامت میں فرشتے انہیں تسلی دیں گے اور کہیں گے: ہم دنیا اور آخرت میں تمہارے دوست ہیں۔"]},{"q":[["mq12-l13-exercise-136",20]],"s":["سورۃ حٰم السجدہ (فصلت) مکی سورت ہے؛ اس میں 54 آیات اور 6 رکوع ہیں؛ یہ حوامیم میں سے دوسری سورت ہے۔","نام: آیت 37 پر سجدۂ تلاوت ہے، اس لیے \"حٰم السجدہ\" کہلاتی ہے؛ اس کا دوسرا نام \"فصلت\" (آیت 3: کتابٌ فصلت آیاته) ہے۔","پس منظر: مکہ میں جب قریش کی مخالفت عروج پر تھی، حضرت حمزہؓ اور حضرت عمرؓ کے قبولِ اسلام کے دور میں نازل ہوئی؛ روایت ہے کہ عتبہ بن ربیعہ آپ ﷺ کو لالچ دینے آیا تو آپ نے اس کی ابتدائی آیات سنائیں جن سے وہ مبہوت ہو کر لوٹا۔"]},{"q":[["mq12-l13-exercise-136",21]],"s":["ترجمہ: اور اس کی نشانیوں میں سے یہ ہے کہ تم زمین کو دبی ہوئی (خشک اور بنجر) دیکھتے ہو، پھر جب ہم اس پر پانی برساتے ہیں تو وہ لہلہانے اور ابھرنے لگتی ہے؛ بے شک جس نے اسے زندہ کیا وہ مردوں کو بھی زندہ کرنے والا ہے؛ بے شک وہ ہر چیز پر قادر ہے۔ (حٰم السجدہ 39)","تشریح: بارش سے مردہ زمین کا زندہ ہونا مرنے کے بعد دوبارہ زندہ کیے جانے کی واضح دلیل ہے۔"]},{"q":[["mq12-l13-exercise-136",22]],"s":["سورۃ حٰم السجدہ کے بنیادی مضامین: (1) قرآن کی عظمت — عربی میں واضح کتاب، بشیر و نذیر؛ کافروں کا اعراض؛ (2) توحید اور کائنات کی تخلیق — زمین دو دن میں، اس میں پہاڑ اور روزی چار دن میں، آسمان دو دن میں (آیات 9–12)۔","(3) عاد و ثمود کا انجام؛ (4) قیامت کے دن انسان کے اعضا کی گواہی؛ برے ساتھیوں (قرناء) کا انجام؛ (5) قرآن سننے سے روکنے اور شور مچانے کی کافرانہ چال۔","(6) استقامت والوں پر فرشتوں کا نزول؛ داعیِ حق کی فضیلت؛ برائی کا بدلہ بھلائی سے؛ (7) اللہ کی نشانیاں — رات دن، سورج چاند؛ سورج چاند کو سجدہ نہ کرو بلکہ خالق کو؛ (8) انسان کی ناشکری اور مایوسی؛ آفاق و انفس میں نشانیاں دکھانے کا وعدہ (آیت 53)۔"]},{"q":[["mq12-l13-exercise-136",23]],"s":["ترجمہ: جو نیک عمل کرے تو اپنے ہی (فائدے کے) لیے، اور جو برائی کرے تو اس کا وبال اسی پر ہے؛ اور آپ کا رب بندوں پر ذرا بھی ظلم کرنے والا نہیں۔ (حٰم السجدہ 46)","تشریح: ہر شخص اپنے عمل کا ذمہ دار ہے؛ اللہ کسی کو بلا وجہ سزا نہیں دیتا، بلکہ ہر ایک کو اس کے عمل کا پورا بدلہ ملے گا۔"]},{"q":[["mq12-l13-exercise-136",24]],"s":["مکالمہ: قیامت کے دن جب کان، آنکھیں اور کھالیں گواہی دیں گی تو وہ اپنی کھالوں سے کہیں گے: تم نے ہمارے خلاف گواہی کیوں دی؟ وہ جواب دیں گی: ہمیں اسی اللہ نے بولنے کی طاقت دی جس نے ہر چیز کو گویائی دی، اسی نے تمہیں پہلی بار پیدا کیا اور اسی کی طرف تم لوٹائے جا رہے ہو۔ (حٰم السجدہ 21)","اور تم (دنیا میں گناہ کرتے وقت) اس سے نہیں چھپتے تھے کہ تمہارے کان، آنکھیں اور کھالیں تمہارے خلاف گواہی دیں گی، بلکہ تم سمجھتے تھے کہ اللہ تمہارے بہت سے اعمال نہیں جانتا (آیت 22)۔"]}],"activities":[{"q":[["mq12-l13-exercise-137",1],["mq12-l13-exercise-137",2]],"s":["دعوتِ دین پر گفتگو کے مفید نکات: گھر میں — نماز کی پابندی اور اہلِ خانہ کو محبت سے یاد دہانی، روزانہ چند منٹ قرآن و حدیث کی تعلیم، اچھا کردار؛ سکول میں — سچائی، دیانت اور حسنِ اخلاق کا نمونہ، ساتھیوں کو نماز اور نیک کاموں کی ترغیب، برائی سے نرمی سے روکنا، دینی موضوعات پر تقریر و مباحثہ؛ محلے میں — سلام کو عام کرنا، پڑوسیوں کی خدمت، مسجد کو آباد کرنا، صفائی اور فلاحی مہمات؛ اصول: «ادْفَعْ بِالَّتِيْ هِيَ اَحْسَنُ» — حکمت، نرمی اور اچھے نمونے سے دعوت (آیات 33–35)۔","سورۃ حٰم السجدہ میں زمین کے بارے میں: اللہ نے زمین کو دو دن میں پیدا کیا (9)؛ اس میں اوپر سے پہاڑ گاڑ دیے، برکت رکھی اور چار دن میں اس کی خوراک کا اندازہ مقرر کیا (10)؛ آسمان و زمین نے کہا: ہم خوشی سے حاضر ہیں (11)؛ زمین بنجر اور دبی ہوئی ہوتی ہے، بارش سے لہلہا اٹھتی ہے (39) — یہ اللہ کی قدرت، ربوبیت اور دوبارہ زندہ کرنے کی دلیل ہے؛ جدید سائنس بھی زمین کے مراحل میں بننے اور پہاڑوں کے توازن قائم رکھنے کی تصدیق کرتی ہے۔"]}]}},"14":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l14-exercise-146",3]],"o":[["mq12-l14-exercise-146",4],["mq12-l14-exercise-146",5],["mq12-l14-exercise-146",6],["mq12-l14-exercise-146",7]],"s":["«لِتُنْذِرَ اُمَّ الْقُرٰى» — تاکہ آپ ام القریٰ (بستیوں کی ماں، یعنی مکہ) والوں کو ڈرائیں (الشوریٰ 7)۔"],"c":0},{"q":[["mq12-l14-exercise-146",8]],"o":[["mq12-l14-exercise-146",9],["mq12-l14-exercise-146",10],["mq12-l14-exercise-146",11],["mq12-l14-exercise-146",12]],"s":["«وَمِنَ الْاَنْعَامِ اَزْوَاجًا» — اور چوپایوں (مویشیوں) کے بھی جوڑے بنائے (آیت 11)۔"],"c":2},{"q":[["mq12-l14-exercise-146",13]],"o":[["mq12-l14-exercise-146",14],["mq12-l14-exercise-146",15],["mq12-l14-exercise-146",16],["mq12-l14-exercise-146",17]],"s":["«وَيَهْدِيْٓ اِلَيْهِ مَنْ يُّنِيْبُ» — جو اس کی طرف رجوع کرے (لوٹ آئے) اسے اپنی طرف راہ دکھاتا ہے (آیت 13)۔"],"c":0},{"q":[["mq12-l14-exercise-146",18]],"o":[["mq12-l14-exercise-146",19],["mq12-l14-exercise-146",20],["mq12-l14-exercise-146",21],["mq12-l14-exercise-146",22]],"s":["«حَرْثَ الْاٰخِرَةِ» — آخرت کی کھیتی (آیت 20)۔"],"c":2},{"q":[["mq12-l14-exercise-146",23]],"o":[["mq12-l14-exercise-146",24],["mq12-l14-exercise-146",25],["mq12-l14-exercise-146",26],["mq12-l14-exercise-146",27]],"s":["«الْجَوَارِ فِي الْبَحْرِ كَالْاَعْلَامِ» — سمندر میں پہاڑوں جیسے چلتے جہاز اس کی نشانیوں میں سے ہیں (آیت 32)۔"],"c":3},{"q":[["mq12-l14-exercise-146",28]],"o":[["mq12-l14-exercise-146",29],["mq12-l14-exercise-146",30],["mq12-l14-exercise-146",31],["mq12-l14-exercise-146",32]],"s":["«وَاَمْرُهُمْ شُوْرٰى بَيْنَهُمْ» — ان کے معاملات باہمی مشورے سے طے ہوتے ہیں (آیت 38)۔"],"c":3},{"q":[["mq12-l14-exercise-147",0]],"o":[["mq12-l14-exercise-147",1],["mq12-l14-exercise-147",2],["mq12-l14-exercise-147",3],["mq12-l14-exercise-147",4]],"s":["«يَبْغُوْنَ» — وہ سرکشی (زیادتی) کرتے ہیں (آیت 42)۔"],"c":3}],"shortQuestions":[{"q":[["mq12-l14-exercise-147",6]],"s":["قرآن کو عربی زبان میں اس لیے نازل کیا گیا کہ آپ ﷺ ام القریٰ (مکہ) اور اس کے اردگرد والوں کو ڈرائیں اور جمع ہونے کے دن (قیامت) سے خبردار کریں جس میں کوئی شک نہیں؛ ایک گروہ جنت میں ہوگا اور ایک دوزخ میں (آیت 7)۔"]},{"q":[["mq12-l14-exercise-147",7]],"s":["آپ ﷺ کو حکم دیا گیا کہ تمہارے درمیان انصاف کروں؛ اللہ ہمارا اور تمہارا رب ہے؛ ہمارے اعمال ہمارے لیے اور تمہارے اعمال تمہارے لیے؛ ہمارے اور تمہارے درمیان کوئی جھگڑا نہیں؛ اللہ ہم سب کو جمع کرے گا (آیت 15)۔"]},{"q":[["mq12-l14-exercise-147",8]],"s":["اللہ کی نشانیوں میں سے آسمانوں اور زمین کی پیدائش اور وہ جاندار ہیں جو اس نے ان دونوں میں پھیلا دیے؛ اور وہ جب چاہے انہیں جمع کرنے پر قادر ہے (آیت 29)۔"]},{"q":[["mq12-l14-exercise-147",9]],"s":["مومنوں کی صفات: وہ کبیرہ گناہوں اور بے حیائی کے کاموں سے بچتے ہیں، اور جب غصہ آئے تو معاف کر دیتے ہیں (آیت 37)۔"]},{"q":[["mq12-l14-exercise-147",10]],"s":["وہ اپنے رب کا حکم مانتے ہیں، نماز قائم کرتے ہیں، ان کے معاملات باہمی مشورے سے طے ہوتے ہیں اور ہمارے دیے ہوئے رزق میں سے خرچ کرتے ہیں (آیت 38)۔"]},{"q":[["mq12-l14-exercise-147",11]],"s":["جو (زیادتی پر) صبر کرے اور معاف کر دے تو بے شک یہ ہمت کے کاموں میں سے ہے (آیت 43)۔"]},{"q":[["mq12-l14-exercise-147",12]],"s":["جب ہم انسان کو اپنی رحمت کا مزہ چکھاتے ہیں تو وہ اس پر اترانے لگتا ہے، اور جب انہیں ان کے اپنے کرتوتوں کی وجہ سے کوئی مصیبت پہنچتی ہے تو انسان بڑا ناشکرا بن جاتا ہے (آیت 48)۔"]}],"longQuestions":[{"q":[["mq12-l14-exercise-147",14]],"s":["ترجمہ: اللہ نے تمہارے لیے دین کا وہی راستہ مقرر کیا جس کا اس نے نوح کو حکم دیا تھا اور جو (اے نبی) ہم نے آپ کی طرف وحی کیا اور جس کا ہم نے ابراہیم، موسیٰ اور عیسیٰ کو حکم دیا تھا کہ دین کو قائم رکھو اور اس میں تفرقہ نہ ڈالو۔ (الشوریٰ 13)","تشریح: تمام انبیا کا دین ایک (توحید) ہے؛ ان کی بعثت کا مقصد اقامتِ دین اور امت کو اتحاد پر قائم رکھنا تھا۔"]},{"q":[["mq12-l14-exercise-147",15]],"s":["سورۃ الشوریٰ مکی سورت ہے؛ اس میں 53 آیات اور 5 رکوع ہیں؛ یہ حوامیم میں سے تیسری ہے (حم، عسق سے آغاز)۔","نام: آیت 38 «وَاَمْرُهُمْ شُوْرٰى بَيْنَهُمْ» سے نام \"الشوریٰ\" (مشاورت) رکھا گیا۔","پس منظر: مکی دور کے آخر میں نازل ہوئی جب کفار کی مخالفت عروج پر تھی؛ اس میں وحی کی حقیقت، توحید، رسالت اور مومنوں کی صفات بیان کر کے مسلمانوں کو صبر، اتحاد اور باہمی مشاورت کی تعلیم دی گئی۔"]},{"q":[["mq12-l14-exercise-147",16]],"s":["ترجمہ: یا (جسے چاہتا ہے) بیٹے اور بیٹیاں ملا جلا کر دیتا ہے، اور جسے چاہتا ہے بانجھ کر دیتا ہے؛ بے شک وہ جاننے والا، قدرت والا ہے۔ (الشوریٰ 50)","تشریح: اولاد دینا یا نہ دینا صرف اللہ کے اختیار میں ہے — کسی کو صرف بیٹیاں، کسی کو صرف بیٹے، کسی کو دونوں اور کسی کو کچھ نہیں؛ یہ اس کی حکمت ہے، اس پر صبر و شکر لازم ہے۔"]},{"q":[["mq12-l14-exercise-147",17]],"s":["سورۃ الشوریٰ کے بنیادی مضامین: (1) وحی کی حقیقت اور قرآن کا عربی میں نزول؛ وحی کی تین صورتیں (آیت 51)؛ (2) توحید — اللہ کی مثل کوئی چیز نہیں (لیس کمثلہ شیء)؛ آسمان و زمین کی کنجیاں اسی کے پاس؛ رزق کی کمی بیشی اس کی حکمت سے۔","(3) تمام انبیا کا ایک دین اور تفرقے کی ممانعت؛ (4) آخرت کی کھیتی اور دنیا کی کھیتی چاہنے والوں کا انجام؛ (5) قرابت داروں کی محبت (مودۃ فی القربیٰ)۔","(6) مومنوں کی صفات — توکل، کبائر سے پرہیز، غصے میں معافی، نماز، شوریٰ، انفاق، ظلم کا بدلہ اور معاف کرنے کی فضیلت؛ (7) انسان کی ناشکری؛ (8) اولاد اللہ کی عطا؛ (9) قرآن روح اور نور ہے جس سے اللہ ہدایت دیتا ہے۔"]},{"q":[["mq12-l14-exercise-147",18]],"s":["ترجمہ: اور کسی انسان کی یہ شان نہیں کہ اللہ اس سے (روبرو) کلام کرے مگر وحی (دل میں ڈال کر) کے ذریعے، یا پردے کے پیچھے سے، یا کوئی فرشتہ (پیغامبر) بھیجے جو اس کے حکم سے جو اللہ چاہے وحی کرے؛ بے شک وہ بلند، حکمت والا ہے۔ (الشوریٰ 51)","تشریح: وحی کی تین صورتیں — (1) الہام یا سچا خواب، (2) پردے کے پیچھے سے کلام (جیسے موسیٰؑ سے)، (3) فرشتے (جبرائیلؑ) کے ذریعے پیغام — قرآن اسی تیسری صورت سے نازل ہوا۔"]},{"q":[["mq12-l14-exercise-147",19]],"s":["سورۃ الشوریٰ میں مشاورت کو مومنوں کی بنیادی صفت قرار دیا گیا اور اسے نماز اور انفاق کے ساتھ ذکر کیا گیا: «وَاَمْرُهُمْ شُوْرٰى بَيْنَهُمْ» (آیت 38) — جس سے اس کی دینی اہمیت واضح ہے۔","شوریٰ کی اہمیت: اجتماعی معاملات (حکومت، خاندان، ادارے) باہمی مشورے سے طے کرنا آمریت کی نفی اور عدل کی ضمانت ہے؛ اس سے بہتر رائے سامنے آتی، غلطی کا امکان کم ہوتا اور لوگوں میں اعتماد اور اتحاد پیدا ہوتا ہے۔","نبی ﷺ کو بھی مشورے کا حکم دیا گیا (آل عمران 159) اور آپ نے بدر، احد اور خندق میں صحابہ سے مشورہ کیا؛ خلفائے راشدین کا انتخاب اور حکومت بھی شوریٰ سے ہوتی تھی؛ حدیث: جس سے مشورہ لیا جائے وہ امانت دار ہے، اور جو مشورہ کرے وہ ندامت نہیں اٹھاتا۔"]}],"activities":[{"q":[["mq12-l14-exercise-147",21],["mq12-l14-exercise-147",22]],"s":["«اَنْ اَقِيْمُوا الدِّيْنَ وَلَا تَتَفَرَّقُوْا فِيْهِ» کی روشنی میں انبیا کی بعثت کا مقصد: (1) توحید کی دعوت اور اللہ کی بندگی کا قیام؛ (2) دین کو زندگی کے ہر شعبے — عقائد، عبادات، اخلاق، معاشرت، معیشت اور سیاست — میں نافذ کرنا؛ (3) انسانوں کو ایک امت بنا کر تفرقے سے بچانا؛ (4) عدل و انصاف کا قیام؛ (5) لوگوں کا تزکیہ اور کتاب و حکمت کی تعلیم — آج کے مسلمانوں کے لیے سبق: فرقہ واریت چھوڑ کر قرآن و سنت پر متحد ہونا۔","اسلامی شوریٰ اور موجودہ قومی نظام کا موازنہ: اسلامی شوریٰ میں حاکمیت اللہ کی ہے، شوریٰ قرآن و سنت کے دائرے میں مشورہ دیتی ہے، اراکین کا معیار تقویٰ، علم اور امانت ہے اور امیر جواب دہ ہوتا ہے؛ موجودہ پارلیمانی نظام (پاکستان) میں منتخب نمائندے قانون سازی کرتے ہیں، آئین میں قرآن و سنت کی بالادستی (آرٹیکل 227) اور اسلامی نظریاتی کونسل موجود ہے، مگر عملی طور پر دولت، برادری اور جماعتی مفادات غالب آ جاتے ہیں؛ بہتری کے لیے اہل اور دیانت دار نمائندوں کا انتخاب ضروری ہے۔"]}]}},"15":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l15-exercise-155",2]],"o":[["mq12-l15-exercise-155",3],["mq12-l15-exercise-155",4],["mq12-l15-exercise-155",5],["mq12-l15-exercise-155",6]],"s":["«الرِّقَابِ» — گردنیں؛ (جنگ میں) کافروں سے مقابلہ ہو تو ان کی گردنیں مارو (سورۃ محمد 4)۔"],"c":0},{"q":[["mq12-l15-exercise-155",7]],"o":[["mq12-l15-exercise-155",8],["mq12-l15-exercise-155",9],["mq12-l15-exercise-155",10],["mq12-l15-exercise-155",11]],"s":["«الْحَرْبُ» — جنگ؛ یہاں تک کہ جنگ اپنے ہتھیار رکھ دے (آیت 4)۔"],"c":2},{"q":[["mq12-l15-exercise-155",12]],"o":[["mq12-l15-exercise-155",13],["mq12-l15-exercise-155",14],["mq12-l15-exercise-155",15],["mq12-l15-exercise-155",16]],"s":["کافر (دنیا کا) مزہ لیتے اور اس طرح کھاتے ہیں جیسے چوپائے (مویشی) کھاتے ہیں (آیت 12)۔"],"c":1},{"q":[["mq12-l15-exercise-155",17]],"o":[["mq12-l15-exercise-155",18],["mq12-l15-exercise-155",19],["mq12-l15-exercise-155",20],["mq12-l15-exercise-155",21]],"s":["«عَسَلٍ مُّصَفًّى» — صاف کیا ہوا (خالص) شہد (آیت 15)۔"],"c":1},{"q":[["mq12-l15-exercise-155",22]],"o":[["mq12-l15-exercise-155",23],["mq12-l15-exercise-155",24],["mq12-l15-exercise-155",25],["mq12-l15-exercise-155",26]],"s":["انہیں کھولتا ہوا پانی پلایا جائے گا جو ان کی آنتیں کاٹ ڈالے گا (آیت 15)۔"],"c":3},{"q":[["mq12-l15-exercise-155",27]],"o":[["mq12-l15-exercise-155",28],["mq12-l15-exercise-155",29],["mq12-l15-exercise-155",30],["mq12-l15-exercise-155",31]],"s":["«فَلَا تَهِنُوْا» — پس ہمت نہ ہارو (اور صلح کی طرف نہ بلاؤ جبکہ تم ہی غالب ہو) (آیت 35)۔"],"c":1},{"q":[["mq12-l15-exercise-155",32]],"o":[["mq12-l15-exercise-155",33],["mq12-l15-exercise-155",34],["mq12-l15-exercise-155",35],["mq12-l15-exercise-155",36]],"s":["«اِنَّمَا الْحَيٰوةُ الدُّنْيَا لَعِبٌ وَّلَهْوٌ» — دنیا کی زندگی تو صرف کھیل تماشا ہے (آیت 36)۔"],"c":3}],"shortQuestions":[{"q":[["mq12-l15-exercise-155",38]],"s":["جن لوگوں نے کفر کیا اور (دوسروں کو) اللہ کے راستے سے روکا، اللہ نے ان کے اعمال ضائع کر دیے (آیت 1)۔"]},{"q":[["mq12-l15-exercise-155",39]],"s":["جب تم (جنگ میں) انہیں خوب کچل دو تو (قیدیوں کو) مضبوط باندھ لو؛ پھر اس کے بعد یا تو احسان کر کے چھوڑ دو یا فدیہ لے کر، یہاں تک کہ جنگ اپنے ہتھیار رکھ دے (آیت 4)۔"]},{"q":[["mq12-l15-exercise-155",40]],"s":["کتنی ہی بستیاں جو آپ کی اس بستی (مکہ) سے زیادہ طاقتور تھیں جس نے آپ کو نکالا، ہم نے انہیں ہلاک کر دیا اور ان کا کوئی مددگار نہ ہوا (آیت 13)۔"]},{"q":[["mq12-l15-exercise-155",41]],"s":["جب جہاد کا واضح حکم نازل ہوتا ہے تو منافق آپ کی طرف اس شخص کی طرح دیکھتے ہیں جس پر موت کی غشی طاری ہو؛ سو ان کے لیے خرابی ہے (آیت 20)۔"]},{"q":[["mq12-l15-exercise-155",42]],"s":["جن کے دلوں میں (نفاق کی) بیماری ہے کیا وہ سمجھتے ہیں کہ اللہ ان کے کینے (بغض) کبھی ظاہر نہیں کرے گا؟ (آیت 29) — اللہ ان کے لہجے اور طرزِ گفتگو سے انہیں پہچنوا دے گا۔"]},{"q":[["mq12-l15-exercise-155",43]],"s":["تم میں سے کچھ بخل کرتے ہیں، اور جو بخل کرتا ہے وہ دراصل اپنے ہی آپ سے بخل کرتا ہے (اس کا نقصان اسی کو ہے)؛ اللہ بے نیاز ہے اور تم محتاج ہو (آیت 38)۔"]},{"q":[["mq12-l15-exercise-155",44]],"s":["اگر تم (اللہ کے حکم سے) منہ پھیرو گے تو اللہ تمہاری جگہ کسی اور قوم کو لے آئے گا، پھر وہ تمہاری طرح نہ ہوں گے (آیت 38)۔"]}],"longQuestions":[{"q":[["mq12-l15-exercise-156",1]],"s":["ترجمہ: اور جو لوگ ایمان لائے اور نیک عمل کیے اور اس (کتاب) پر ایمان لائے جو محمد (ﷺ) پر نازل کی گئی — اور وہی ان کے رب کی طرف سے حق ہے — اللہ نے ان کی برائیاں ان سے دور کر دیں اور ان کا حال درست کر دیا۔ (سورۃ محمد 2)","تشریح: ایمان، عملِ صالح اور قرآن پر ایمان کا نتیجہ گناہوں کی معافی اور دنیا و آخرت میں حالات کی اصلاح ہے۔"]},{"q":[["mq12-l15-exercise-156",2]],"s":["سورۃ محمد مدنی سورت ہے؛ اس میں 38 آیات اور 4 رکوع ہیں؛ یہ ہجرت کے فوراً بعد غزوۂ بدر سے پہلے یا اس کے قریب نازل ہوئی۔","نام: آیت 2 میں نبی ﷺ کا اسمِ مبارک \"محمد\" آیا ہے، اسی سے نام رکھا گیا؛ اس کا دوسرا نام \"القتال\" ہے کیونکہ اس میں جہاد و قتال کے احکام ہیں۔","پس منظر: مدینہ میں مسلمانوں کو کفار مکہ کی جارحیت کا سامنا تھا؛ جہاد کی ترغیب، جنگی قیدیوں کے احکام اور منافقین کے رویے کی وضاحت اس کا موضوع ہے۔"]},{"q":[["mq12-l15-exercise-156",3]],"s":["ترجمہ: اور جو لوگ اللہ کی راہ میں قتل کیے گئے اللہ ان کے اعمال ہرگز ضائع نہیں کرے گا؛ وہ انہیں (منزل کی) راہ دکھائے گا اور ان کا حال درست کر دے گا، اور انہیں اس جنت میں داخل کرے گا جس کی پہچان انہیں کرا دی ہے۔ (سورۃ محمد 4–6)","تشریح: شہدا کے لیے چار انعام — اعمال کی حفاظت، ہدایت، حالت کی اصلاح اور جانی پہچانی جنت میں داخلہ۔"]},{"q":[["mq12-l15-exercise-156",4]],"s":["سورۃ محمد کے بنیادی مضامین: (1) کافروں کے اعمال کا ضائع ہونا اور مومنوں کی اصلاح؛ (2) جنگ کے احکام — کافروں سے مقابلہ، قیدیوں کو باندھنا، احسان یا فدیہ؛ (3) شہدا کا مقام؛ اللہ کی مدد کرنے والوں کی مدد اور ثابت قدمی کا وعدہ (آیت 7)۔","(4) پچھلی قوموں کی ہلاکت سے عبرت؛ (5) جنت کی چار نہریں (پانی، دودھ، شراب، شہد) اور دوزخیوں کا کھولتا پانی؛ (6) منافقین کا جہاد کے حکم پر رویہ، قرآن میں تدبر نہ کرنا (کیا ان کے دلوں پر تالے ہیں؟)، ان کے کینے کا ظاہر ہونا۔","(7) توحید کا علم اور استغفار کا حکم (فاعلم انہ لا الٰہ الا اللہ)؛ (8) اللہ اور رسول کی اطاعت اور اعمال کو باطل نہ کرنا؛ ہمت نہ ہارنا؛ دنیا کی بے ثباتی؛ بخل کی مذمت اور قوم کی تبدیلی کی وعید۔"]},{"q":[["mq12-l15-exercise-156",5]],"s":["ترجمہ: بے شک اللہ ایمان والوں اور نیک عمل کرنے والوں کو ایسے باغوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہیں؛ اور جو کافر ہیں وہ (دنیا کا) مزہ لیتے اور اس طرح کھاتے ہیں جیسے چوپائے کھاتے ہیں، اور آگ ان کا ٹھکانا ہے۔ (سورۃ محمد 12)","تشریح: کافر کا مقصدِ زندگی صرف کھانا پینا اور لذت ہے، جانوروں کی طرح بے فکر؛ جبکہ مومن کا مقصد اللہ کی رضا اور آخرت ہے۔"]},{"q":[["mq12-l15-exercise-156",6]],"s":["جنت کی صفات (سورۃ محمد 15): (1) ایسے پانی کی نہریں جس میں بو یا تبدیلی نہیں آتی؛ (2) ایسے دودھ کی نہریں جس کا ذائقہ نہیں بدلتا؛ (3) ایسی شراب کی نہریں جو پینے والوں کے لیے لذیذ ہے (نشہ اور خرابی سے پاک)؛ (4) صاف کیے ہوئے شہد کی نہریں۔","مزید یہ کہ ان کے لیے ہر قسم کے پھل اور ان کے رب کی طرف سے مغفرت ہے؛ کیا یہ (جنتی) اس جیسے ہو سکتے ہیں جو ہمیشہ آگ میں رہے گا اور انہیں کھولتا پانی پلایا جائے گا جو آنتیں کاٹ ڈالے؟"]}],"activities":[{"q":[["mq12-l15-exercise-156",8],["mq12-l15-exercise-156",9]],"s":["جنت کی نہروں سے متعلق احادیث: (1) جنت میں پانی، دودھ، شراب اور شہد کے سمندر ہیں جن سے نہریں پھوٹتی ہیں (ترمذی)؛ (2) سیحان، جیحان، فرات اور نیل جنت کی نہروں میں سے ہیں (صحیح مسلم)؛ (3) کوثر جنت کی ایک نہر ہے جس کے کنارے موتیوں کے گنبد ہیں، اس کا پانی دودھ سے زیادہ سفید اور شہد سے زیادہ میٹھا ہے (بخاری)؛ (4) جنت کی نہریں مشک کے پہاڑوں سے نکلتی ہیں۔","دنیا کی بے ثباتی سے متعلق احادیث: (1) دنیا میں ایسے رہو جیسے مسافر یا راہ گیر (بخاری)؛ (2) اگر دنیا کی قدر اللہ کے نزدیک مچھر کے پر کے برابر بھی ہوتی تو کافر کو ایک گھونٹ پانی نہ پلاتا (ترمذی)؛ (3) دنیا مومن کا قید خانہ اور کافر کی جنت ہے (مسلم)؛ (4) لذتوں کو توڑنے والی چیز (موت) کو کثرت سے یاد کرو (ترمذی)۔"]}]}},"16":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l16-exercise-163",2]],"o":[["mq12-l16-exercise-163",3],["mq12-l16-exercise-163",4],["mq12-l16-exercise-163",5],["mq12-l16-exercise-163",6]],"s":["«اِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِيْنًا» — یہاں کھلی فتح سے مراد صلح حدیبیہ (6ھ) ہے جو بعد میں فتحِ مکہ کا پیش خیمہ بنی (الفتح 1)۔"],"c":2},{"q":[["mq12-l16-exercise-163",7]],"o":[["mq12-l16-exercise-163",8],["mq12-l16-exercise-163",9],["mq12-l16-exercise-163",10],["mq12-l16-exercise-163",11]],"s":["«جُنُوْدُ» — لشکر؛ آسمانوں اور زمین کے لشکر اللہ ہی کے ہیں (آیت 4)۔"],"c":0},{"q":[["mq12-l16-exercise-163",12]],"o":[["mq12-l16-exercise-163",13],["mq12-l16-exercise-163",14],["mq12-l16-exercise-163",15],["mq12-l16-exercise-163",16]],"s":["«لَيْسَ عَلَى الْاَعْمٰى حَرَجٌ» — اندھے پر (جہاد میں شریک نہ ہونے کا) کوئی گناہ نہیں، نہ لنگڑے پر اور نہ بیمار پر (آیت 17)۔"],"c":2},{"q":[["mq12-l16-exercise-163",17]],"o":[["mq12-l16-exercise-163",18],["mq12-l16-exercise-163",19],["mq12-l16-exercise-163",20],["mq12-l16-exercise-163",21]],"s":["«مَغَانِمَ» — غنیمتیں (مالِ غنیمت) (آیات 15، 19–20)۔"],"c":2},{"q":[["mq12-l16-exercise-163",22]],"o":[["mq12-l16-exercise-163",23],["mq12-l16-exercise-163",24],["mq12-l16-exercise-163",25],["mq12-l16-exercise-163",26]],"s":["«حَمِيَّةَ الْجَاهِلِيَّةِ» — جاہلیت کی ضد اور تعصب (آیت 26)۔"],"c":2},{"q":[["mq12-l16-exercise-163",27]],"o":[["mq12-l16-exercise-163",28],["mq12-l16-exercise-163",29],["mq12-l16-exercise-163",30],["mq12-l16-exercise-163",31]],"s":["اللہ نے اپنے رسول کو ہدایت اور دینِ حق کے ساتھ بھیجا تاکہ اسے تمام ادیان پر غالب کر دے (آیت 28)۔"],"c":1},{"q":[["mq12-l16-exercise-163",32]],"o":[["mq12-l16-exercise-163",33],["mq12-l16-exercise-163",34],["mq12-l16-exercise-163",35],["mq12-l16-exercise-163",36]],"s":["«اَشِدَّآءُ عَلَى الْكُفَّارِ رُحَمَآءُ بَيْنَهُمْ» — یہ صحابہ کرامؓ (محمد ﷺ کے ساتھیوں) کی صفات ہیں (آیت 29)۔"],"c":1}],"shortQuestions":[{"q":[["mq12-l16-exercise-163",38]],"s":["نبی ﷺ کو کھلی فتح (صلح حدیبیہ) کی خوشخبری دی گئی، جس کے ساتھ یہ بشارتیں بھی ہیں کہ اللہ آپ کی اگلی پچھلی لغزشیں معاف کرے، اپنی نعمت پوری کرے، سیدھی راہ پر چلائے اور زبردست مدد کرے (آیات 1–3)۔"]},{"q":[["mq12-l16-exercise-163",39]],"s":["آپ ﷺ کی صفات: شاہد (گواہی دینے والا)، مبشر (خوشخبری دینے والا) اور نذیر (ڈرانے والا) (آیت 8)۔"]},{"q":[["mq12-l16-exercise-163",40]],"s":["حقوق: اللہ اور اس کے رسول پر ایمان لانا؛ رسول کی مدد (تعزیر) اور تعظیم و توقیر کرنا؛ اور صبح و شام اللہ کی تسبیح کرنا (آیت 9)۔"]},{"q":[["mq12-l16-exercise-164",0]],"s":["پیچھے رہ جانے والے دیہاتیوں (اعراب) نے بہانہ بنایا کہ ہمارے مالوں اور گھر والوں نے ہمیں مشغول رکھا، لہٰذا ہمارے لیے مغفرت کی دعا کیجیے؛ وہ زبان سے وہ کہتے ہیں جو ان کے دلوں میں نہیں (آیت 11)۔"]},{"q":[["mq12-l16-exercise-164",1]],"s":["بیعتِ رضوان کرنے والے صحابہؓ کو انعامات: (1) اللہ ان سے راضی ہو گیا؛ (2) ان کے دلوں کا اخلاص جان کر ان پر سکینت (اطمینان) نازل کی؛ (3) انہیں قریب کی فتح (خیبر) عطا کی؛ (4) اور بہت سی غنیمتیں دیں (آیات 18–19)۔"]},{"q":[["mq12-l16-exercise-164",2]],"s":["صحابہؓ کی صفات: کافروں پر سخت، آپس میں رحم دل؛ تم انہیں رکوع و سجود میں دیکھو گے، وہ اللہ کے فضل اور رضا کے طالب ہیں؛ ان کے چہروں پر سجدوں کے اثر سے نشان (نور) ہے (آیت 29)۔"]},{"q":[["mq12-l16-exercise-164",3]],"s":["اللہ نے ان میں سے ایمان والوں اور نیک عمل کرنے والوں سے مغفرت اور بڑے اجر کا وعدہ کیا ہے (آیت 29)۔"]}],"longQuestions":[{"q":[["mq12-l16-exercise-164",5]],"s":["ترجمہ: (اے نبی!) جو لوگ آپ سے بیعت کرتے ہیں وہ دراصل اللہ سے بیعت کرتے ہیں؛ اللہ کا ہاتھ ان کے ہاتھوں کے اوپر ہے؛ پھر جو عہد توڑے گا تو اس کے توڑنے کا وبال اسی پر ہے، اور جو اس عہد کو پورا کرے گا جو اس نے اللہ سے کیا تو وہ اسے عنقریب بڑا اجر دے گا۔ (الفتح 10)","تشریح: بیعتِ رضوان رسول ﷺ کے ہاتھ پر تھی مگر اللہ نے اسے اپنی بیعت قرار دیا؛ عہد کی پاسداری اجرِ عظیم کا باعث اور عہد شکنی کا نقصان خود عہد شکن کو ہے۔"]},{"q":[["mq12-l16-exercise-164",6]],"s":["سورۃ الفتح مدنی سورت ہے؛ اس میں 29 آیات اور 4 رکوع ہیں؛ یہ ذوالقعدہ 6ھ میں صلح حدیبیہ سے واپسی پر مکہ اور مدینہ کے درمیان (کراع الغمیم کے مقام پر) نازل ہوئی۔","نام: پہلی آیت «اِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِيْنًا» سے نام \"الفتح\" رکھا گیا۔","اہمیت: نبی ﷺ نے فرمایا: آج رات مجھ پر ایسی سورت نازل ہوئی جو مجھے ہر اس چیز سے زیادہ محبوب ہے جس پر سورج طلوع ہوتا ہے (بخاری)؛ اس میں صلح حدیبیہ کو \"فتحِ مبین\" قرار دے کر مسلمانوں کو تسلی دی گئی۔"]},{"q":[["mq12-l16-exercise-164",7]],"s":["ترجمہ: اور آسمانوں اور زمین کی بادشاہی اللہ ہی کی ہے؛ وہ جسے چاہے بخش دے اور جسے چاہے عذاب دے؛ اور اللہ بخشنے والا، مہربان ہے۔ (الفتح 14)","تشریح: مغفرت اور عذاب اللہ کے اختیار میں ہے، مگر اس کی رحمت غالب ہے — اس لیے منافقین اور پیچھے رہنے والوں کے لیے بھی توبہ کا دروازہ کھلا ہے۔"]},{"q":[["mq12-l16-exercise-164",8]],"s":["سورۃ الفتح کے بنیادی مضامین: (1) صلح حدیبیہ کو فتحِ مبین قرار دینا اور نبی ﷺ کو مغفرت، اتمامِ نعمت اور نصرت کی بشارت؛ (2) مومنوں کے دلوں پر سکینت کا نزول اور ایمان میں اضافہ؛ (3) منافقین اور مشرکین کا بدگمانی کی وجہ سے انجام۔","(4) رسول ﷺ کی صفات (شاہد، مبشر، نذیر) اور ان کی تعظیم کا حکم؛ (5) بیعتِ رضوان اور اللہ کی رضا؛ (6) پیچھے رہ جانے والے اعراب کے بہانے اور ان کا امتحان؛ معذوروں کی رخصت۔","(7) خیبر کی فتح اور غنیمتوں کا وعدہ؛ (8) کفار کی جاہلانہ ضد اور مومنوں کا تقویٰ؛ (9) نبی ﷺ کے خواب کی تصدیق کہ تم امن کے ساتھ مسجدِ حرام میں داخل ہو گے؛ (10) دینِ حق کے غلبے کا اعلان اور صحابہ کرامؓ کی صفات (تورات و انجیل میں ان کی مثال)۔"]},{"q":[["mq12-l16-exercise-164",9]],"s":["ترجمہ: وہی ہے جس نے اپنے رسول کو ہدایت اور دینِ حق کے ساتھ بھیجا تاکہ اسے تمام دینوں پر غالب کر دے؛ اور (اس پر) اللہ کی گواہی کافی ہے۔ (الفتح 28)","تشریح: رسالتِ محمدی کا مقصد دینِ اسلام کو دلیل اور قوت دونوں لحاظ سے تمام ادیان پر غالب کرنا ہے؛ یہ وعدہ فتحِ مکہ اور بعد کی فتوحات سے پورا ہوا۔"]},{"q":[["mq12-l16-exercise-164",10]],"s":["شانِ نزول: ذوالقعدہ 6ھ میں نبی ﷺ تقریباً چودہ سو صحابہ کے ساتھ عمرے کے ارادے سے مکہ روانہ ہوئے؛ قریش نے حدیبیہ کے مقام پر روک دیا؛ حضرت عثمانؓ کو سفیر بنا کر بھیجا گیا اور ان کی شہادت کی افواہ پر آپ ﷺ نے ببول کے درخت کے نیچے صحابہ سے موت تک لڑنے کی بیعت (بیعتِ رضوان) لی۔","پھر سہیل بن عمرو کے ذریعے صلح ہوئی جس کی شرائط بظاہر مسلمانوں کے لیے ناگوار تھیں (اس سال واپسی، دس سال جنگ بندی، مکہ سے آنے والے مسلمان کی واپسی)؛ صحابہ غمگین تھے؛ واپسی پر یہ سورت نازل ہوئی اور اسے فتحِ مبین قرار دیا — اسی صلح سے اسلام تیزی سے پھیلا اور دو سال بعد مکہ فتح ہوا۔"]}],"activities":[{"q":[["mq12-l16-exercise-164",12],["mq12-l16-exercise-164",13]],"s":["صلح حدیبیہ کے اہم نکات: (1) ذوالقعدہ 6ھ، تقریباً 1400 صحابہ، عمرے کی نیت، قربانی کے جانور ساتھ؛ (2) قریش کی رکاوٹ؛ حضرت عثمانؓ کی سفارت اور بیعتِ رضوان؛ (3) سہیل بن عمرو سے معاہدہ؛ شرائط: دس سال جنگ بندی، اس سال واپسی اور اگلے سال تین دن کے لیے عمرہ، مکہ سے مدینہ جانے والا واپس کیا جائے گا مگر مدینہ سے مکہ جانے والا واپس نہ ہوگا، قبائل کو کسی بھی فریق کا حلیف بننے کی آزادی؛ (4) حضرت ابو جندلؓ کا واقعہ؛ (5) حدیبیہ میں ہی قربانی اور حلق؛ (6) نتائج — امن سے دعوت کا پھیلاؤ، خیبر کی فتح، بادشاہوں کو خطوط، اور 8ھ میں قریش کی عہد شکنی پر فتحِ مکہ۔","صحابہؓ کے ادب و تعظیم کے واقعات: (1) صلح حدیبیہ میں عروہ بن مسعود نے دیکھا کہ صحابہ آپ ﷺ کے وضو کے پانی پر ٹوٹ پڑتے، آپ کے سامنے آواز پست رکھتے اور نظر بھر کر نہ دیکھتے — اس نے کہا: میں نے قیصر و کسریٰ کے درباروں میں بھی ایسی تعظیم نہیں دیکھی؛ (2) آیت «لَا تَرْفَعُوْٓا اَصْوَاتَكُمْ» کے نزول کے بعد حضرت ثابت بن قیسؓ گھر بیٹھ گئے کہ ان کی آواز بلند تھی؛ (3) حضرت ابوبکرؓ آپ ﷺ سے سرگوشی کی طرح بات کرتے؛ (4) صحابہؓ آپ کی مجلس میں ایسے بیٹھتے جیسے ان کے سروں پر پرندے بیٹھے ہوں۔"]}]}},"17":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l17-exercise-170",2]],"o":[["mq12-l17-exercise-170",3],["mq12-l17-exercise-170",4],["mq12-l17-exercise-170",5],["mq12-l17-exercise-170",6]],"s":["«اِنْ جَآءَكُمْ فَاسِقٌ بِنَبَاٍ فَتَبَيَّنُوْٓا» — اگر کوئی فاسق خبر لائے تو اس کی تحقیق کر لو (الحجرات 6)۔"],"c":1},{"q":[["mq12-l17-exercise-170",7]],"o":[["mq12-l17-exercise-170",8],["mq12-l17-exercise-170",9],["mq12-l17-exercise-170",10],["mq12-l17-exercise-170",11]],"s":["«اِنَّ اللّٰهَ يُحِبُّ الْمُقْسِطِيْنَ» — اللہ انصاف کرنے والوں کو پسند کرتا ہے (آیت 9)۔"],"c":2},{"q":[["mq12-l17-exercise-170",12]],"o":[["mq12-l17-exercise-170",13],["mq12-l17-exercise-170",14],["mq12-l17-exercise-170",15],["mq12-l17-exercise-170",16]],"s":["«وَلَا تَلْمِزُوْٓا اَنْفُسَكُمْ» — ایک دوسرے کو طعنے نہ دو (عیب نہ لگاؤ) (آیت 11)۔"],"c":0},{"q":[["mq12-l17-exercise-170",17]],"o":[["mq12-l17-exercise-170",18],["mq12-l17-exercise-170",19],["mq12-l17-exercise-170",20],["mq12-l17-exercise-170",21]],"s":["«وَلَا تَجَسَّسُوْا» — جاسوسی (ٹوہ) نہ کرو (آیت 12)۔"],"c":2},{"q":[["mq12-l17-exercise-170",22]],"o":[["mq12-l17-exercise-170",23],["mq12-l17-exercise-170",24],["mq12-l17-exercise-170",25],["mq12-l17-exercise-170",26]],"s":["«لَحْمَ» — گوشت (آیت 12)۔"],"c":0},{"q":[["mq12-l17-exercise-170",27]],"o":[["mq12-l17-exercise-170",28],["mq12-l17-exercise-170",29],["mq12-l17-exercise-170",30],["mq12-l17-exercise-170",31]],"s":["قومیں اور قبیلے اس لیے بنائے تاکہ ایک دوسرے کو پہچانو (آیت 13)۔"],"c":0},{"q":[["mq12-l17-exercise-170",32]],"o":[["mq12-l17-exercise-170",33],["mq12-l17-exercise-170",34],["mq12-l17-exercise-170",35],["mq12-l17-exercise-170",36]],"s":["اللہ کے نزدیک سب سے عزت والا وہ ہے جو سب سے زیادہ پرہیزگار ہے — عزت کا معیار تقویٰ ہے (آیت 13)۔"],"c":1}],"shortQuestions":[{"q":[["mq12-l17-exercise-170",38]],"s":["اے ایمان والو! اپنی آوازیں نبی ﷺ کی آواز سے بلند نہ کرو، اور ان سے اس طرح زور سے بات نہ کرو جیسے آپس میں کرتے ہو، کہیں تمہارے اعمال ضائع نہ ہو جائیں اور تمہیں خبر بھی نہ ہو (آیت 2)؛ نیز اللہ اور رسول سے آگے نہ بڑھو (آیت 1)۔"]},{"q":[["mq12-l17-exercise-170",39]],"s":["جو لوگ آپ کو حجروں (گھروں) کے باہر سے (زور زور سے) پکارتے ہیں ان میں سے اکثر بے عقل ہیں؛ اگر وہ صبر کرتے یہاں تک کہ آپ خود باہر تشریف لاتے تو ان کے لیے بہتر تھا (آیات 4–5) — یہ واقعہ بنو تمیم کے وفد کا ہے۔"]},{"q":[["mq12-l17-exercise-170",40]],"s":["مومن تو آپس میں بھائی بھائی ہیں، پس اپنے دو بھائیوں کے درمیان صلح کرا دو اور اللہ سے ڈرو تاکہ تم پر رحم کیا جائے (آیت 10)۔"]},{"q":[["mq12-l17-exercise-170",41]],"s":["تعلیمات: کوئی قوم کسی قوم کا مذاق نہ اڑائے، ممکن ہے وہ ان سے بہتر ہوں؛ نہ عورتیں دوسری عورتوں کا مذاق اڑائیں، ممکن ہے وہ ان سے بہتر ہوں؛ ایک دوسرے کو طعنے نہ دو اور نہ برے القاب سے پکارو؛ ایمان کے بعد فسق کا نام برا ہے؛ جو توبہ نہ کریں وہی ظالم ہیں (آیت 11)۔"]},{"q":[["mq12-l17-exercise-170",42]],"s":["تین چیزوں سے بچنے کی ہدایت: بہت زیادہ گمان سے بچو کیونکہ بعض گمان گناہ ہیں؛ جاسوسی (کسی کے عیبوں کی ٹوہ) نہ کرو؛ اور ایک دوسرے کی غیبت نہ کرو (آیت 12)۔"]},{"q":[["mq12-l17-exercise-171",0]],"s":["غیبت کو مردہ بھائی کا گوشت کھانے سے تشبیہ دی گئی: کیا تم میں سے کوئی پسند کرے گا کہ اپنے مردہ بھائی کا گوشت کھائے؟ تم اسے ناپسند کرتے ہو (تو غیبت کو بھی ناپسند کرو)؛ اللہ سے ڈرو، بے شک اللہ توبہ قبول کرنے والا، مہربان ہے (آیت 12)۔"]},{"q":[["mq12-l17-exercise-171",1]],"s":["سچے مومنوں کی صفات: اللہ اور اس کے رسول پر ایمان لائے، پھر شک میں نہ پڑے، اور اپنے مالوں اور جانوں سے اللہ کی راہ میں جہاد کیا — یہی سچے ہیں (آیت 15)۔"]}],"longQuestions":[{"q":[["mq12-l17-exercise-171",3]],"s":["ترجمہ: بے شک جو لوگ رسول اللہ ﷺ کے پاس اپنی آوازیں پست رکھتے ہیں، یہی وہ لوگ ہیں جن کے دلوں کو اللہ نے تقویٰ کے لیے جانچ لیا ہے؛ ان کے لیے مغفرت اور بڑا اجر ہے۔ (الحجرات 3)","تشریح: نبی ﷺ کے ادب میں آواز پست رکھنا تقویٰ کی علامت ہے؛ یہی ادب آپ کی قبرِ مبارک اور احادیث کے سننے کے وقت بھی ملحوظ رکھا جاتا ہے۔"]},{"q":[["mq12-l17-exercise-171",4]],"s":["اللہ نے ایمان کو مومنوں کے لیے محبوب بنا دیا اور اسے ان کے دلوں میں خوشنما کر دیا؛ اور کفر، فسق (گناہ) اور نافرمانی کو ان کے لیے ناپسندیدہ بنا دیا — یہی لوگ ہدایت یافتہ (راشدون) ہیں۔ (الحجرات 7)","یعنی اللہ کا فضل ہے کہ مومن کا دل نیکی کی طرف مائل اور برائی سے متنفر رہتا ہے؛ اس لیے رسول ﷺ کی بات مانو، اپنی رائے ان پر نہ تھوپو۔"]},{"q":[["mq12-l17-exercise-171",5]],"s":["ترجمہ: اور ایک دوسرے کو عیب نہ لگاؤ (طعنے نہ دو) اور نہ ایک دوسرے کو برے القاب سے پکارو؛ ایمان لانے کے بعد گناہ کا نام (برا لقب) بہت برا ہے؛ اور جو توبہ نہ کریں وہی ظالم ہیں۔ (الحجرات 11)","تشریح: طعنہ زنی اور برے نام رکھنا بھائی چارے کو توڑتے ہیں؛ کسی مسلمان کو فاسق، کافر یا تحقیر آمیز نام سے پکارنا گناہ ہے۔"]},{"q":[["mq12-l17-exercise-171",6]],"s":["سورۃ الحجرات مدنی سورت ہے؛ اس میں 18 آیات اور 2 رکوع ہیں؛ یہ 9ھ (عام الوفود) کے آس پاس نازل ہوئی جب عرب کے وفود آ رہے تھے۔","نام: آیت 4 میں \"الحجرات\" (نبی ﷺ کے حجرے/گھر) کا ذکر ہے، اسی سے نام رکھا گیا۔","موضوع: اسے \"سورۃ الآداب\" کہا جا سکتا ہے؛ اس میں رسول ﷺ کے ادب، خبر کی تحقیق، مسلمانوں کے باہمی تعلقات، معاشرتی برائیوں (مذاق، طعنہ، بدگمانی، جاسوسی، غیبت) سے بچنے اور انسانی مساوات کی تعلیم دی گئی ہے۔"]},{"q":[["mq12-l17-exercise-171",7]],"s":["ترجمہ: اے لوگو! ہم نے تمہیں ایک مرد اور ایک عورت سے پیدا کیا اور تمہیں قومیں اور قبیلے بنایا تاکہ ایک دوسرے کو پہچانو؛ بے شک اللہ کے نزدیک تم میں سب سے عزت والا وہ ہے جو تم میں سب سے زیادہ پرہیزگار ہے؛ بے شک اللہ جاننے والا، خبر رکھنے والا ہے۔ (الحجرات 13)","تشریح: یہ آیت انسانی مساوات کا منشور ہے — رنگ، نسل، قوم اور قبیلے کی بنیاد پر کوئی برتری نہیں؛ فضیلت کا واحد معیار تقویٰ ہے؛ خطبۂ حجۃ الوداع میں بھی یہی اعلان کیا گیا۔"]},{"q":[["mq12-l17-exercise-171",8]],"s":["سورۃ الحجرات کے بنیادی مضامین: (1) اللہ اور رسول سے آگے نہ بڑھنا؛ نبی ﷺ کے سامنے آواز پست رکھنا اور حجروں کے باہر سے نہ پکارنا؛ (2) فاسق کی خبر کی تحقیق (افواہوں سے بچاؤ)؛ (3) مومنوں کی باہمی لڑائی میں صلح کرانا اور زیادتی کرنے والے کو روکنا؛ اخوتِ اسلامی۔","(4) معاشرتی برائیوں کی ممانعت — مذاق اڑانا، طعنہ دینا، برے القاب، بدگمانی، جاسوسی اور غیبت؛ (5) انسانی مساوات اور تقویٰ کا معیار؛ (6) اسلام اور ایمان کا فرق — دیہاتیوں کا دعویٰ کہ ہم ایمان لائے، جواب: کہو ہم نے اسلام قبول کیا؛ (7) سچے مومنوں کی صفات؛ (8) اسلام قبول کرنے کا احسان جتانے کی مذمت — ہدایت دینا اللہ کا احسان ہے۔"]}],"activities":[{"q":[["mq12-l17-exercise-171",10]],"s":["سورۃ الحجرات میں بیان کردہ معاشرتی برائیوں کا چارٹ: (1) بلا تحقیق خبر پھیلانا — نقصان: بے گناہوں کو تکلیف، فساد اور ندامت (آیت 6)؛ (2) باہمی لڑائی جھگڑا — اخوت کا خاتمہ (9–10)؛ (3) مذاق اڑانا — دل آزاری، تکبر (11)؛ (4) طعنہ زنی — نفرت اور عداوت (11)؛ (5) برے القاب سے پکارنا — تحقیر اور فسق (11)؛ (6) بدگمانی — بلا وجہ الزام اور قطع تعلق (12)؛ (7) جاسوسی — راز فاش اور عزت کی پامالی (12)؛ (8) غیبت — مردہ بھائی کا گوشت کھانے کے برابر، معاشرتی بگاڑ (12)؛ (9) نسلی و قبائلی تفاخر — تفرقہ اور ظلم (13)۔"]}]}},"18":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l18-exercise-179",2]],"o":[["mq12-l18-exercise-179",3],["mq12-l18-exercise-179",4],["mq12-l18-exercise-179",5],["mq12-l18-exercise-179",6]],"s":["اللہ نے آسمانوں اور زمین کو چھ دنوں (ادوار) میں پیدا کیا (الحدید 4)۔"],"c":0},{"q":[["mq12-l18-exercise-179",7]],"o":[["mq12-l18-exercise-179",8],["mq12-l18-exercise-179",9],["mq12-l18-exercise-179",10],["mq12-l18-exercise-179",11]],"s":["«اسْتَوٰى» — (عرش پر) مستوی ہوا؛ اس کی کیفیت اللہ ہی جانتا ہے (آیت 4)۔"],"c":2},{"q":[["mq12-l18-exercise-179",12]],"o":[["mq12-l18-exercise-179",13],["mq12-l18-exercise-179",14],["mq12-l18-exercise-179",15],["mq12-l18-exercise-179",16]],"s":["قیامت کے دن مومن مردوں اور عورتوں کا نور ان کے آگے اور ان کے دائیں جانب دوڑ رہا ہوگا (آیت 12)۔"],"c":1},{"q":[["mq12-l18-exercise-179",17]],"o":[["mq12-l18-exercise-179",18],["mq12-l18-exercise-179",19],["mq12-l18-exercise-179",20],["mq12-l18-exercise-179",21]],"s":["«سُوْرٍ» — دیوار؛ مومنوں اور منافقوں کے درمیان ایک دیوار کھڑی کر دی جائے گی جس میں دروازہ ہوگا (آیت 13)۔"],"c":2},{"q":[["mq12-l18-exercise-179",22]],"o":[["mq12-l18-exercise-179",23],["mq12-l18-exercise-179",24],["mq12-l18-exercise-179",25],["mq12-l18-exercise-179",26]],"s":["«الْغَرُوْرُ» — بڑا دھوکا باز (شیطان) (آیت 14)۔"],"c":0},{"q":[["mq12-l18-exercise-179",27]],"o":[["mq12-l18-exercise-179",28],["mq12-l18-exercise-179",29],["mq12-l18-exercise-179",30],["mq12-l18-exercise-179",31]],"s":["«سَابِقُوْٓا» — آگے بڑھو، ایک دوسرے سے سبقت لے جاؤ؛ اپنے رب کی مغفرت اور اس جنت کی طرف جس کی چوڑائی آسمان و زمین جیسی ہے (آیت 21)۔"],"c":0},{"q":[["mq12-l18-exercise-179",32]],"o":[["mq12-l18-exercise-179",33],["mq12-l18-exercise-179",34],["mq12-l18-exercise-179",35],["mq12-l18-exercise-179",36]],"s":["«وَاَنْزَلْنَا الْحَدِيْدَ» — اور ہم نے لوہا اتارا جس میں سخت (جنگی) قوت اور لوگوں کے لیے فائدے ہیں (آیت 25)۔"],"c":3}],"shortQuestions":[{"q":[["mq12-l18-exercise-179",38]],"s":["اللہ کی صفات: وہی اوّل (سب سے پہلے) ہے، وہی آخر (سب کے بعد) ہے، وہی ظاہر (ہر چیز پر غالب اور نشانیوں سے ظاہر) ہے، وہی باطن (نگاہوں سے پوشیدہ) ہے، اور وہ ہر چیز کو جاننے والا ہے (آیت 3)۔"]},{"q":[["mq12-l18-exercise-179",39]],"s":["کون ہے جو اللہ کو قرضِ حسنہ دے (اس کی راہ میں خلوص سے خرچ کرے) تاکہ اللہ اسے کئی گنا بڑھا دے اور اس کے لیے عزت والا اجر ہے (آیت 11)۔"]},{"q":[["mq12-l18-exercise-179",40]],"s":["جو اللہ اور اس کے رسولوں پر ایمان لائے وہی اپنے رب کے نزدیک صدیق اور شہید (گواہ) ہیں؛ ان کے لیے ان کا اجر اور ان کا نور ہے (آیت 19)۔"]},{"q":[["mq12-l18-exercise-179",41]],"s":["ہر مصیبت پہلے سے لکھی ہوئی ہے تاکہ جو چیز تم سے جاتی رہے اس پر غم نہ کرو اور جو اللہ تمہیں دے اس پر اتراؤ نہیں؛ اللہ اترانے اور شیخی بگھارنے والے کو پسند نہیں کرتا (آیت 23)۔"]},{"q":[["mq12-l18-exercise-179",42]],"s":["ہم نے اپنے رسولوں کو واضح دلیلوں کے ساتھ بھیجا اور ان کے ساتھ کتاب اور میزان (عدل کا معیار) اتاری تاکہ لوگ انصاف پر قائم ہوں (آیت 25)۔"]},{"q":[["mq12-l18-exercise-179",43]],"s":["رہبانیت (ترکِ دنیا) عیسائیوں نے خود ایجاد کی، ہم نے اسے ان پر فرض نہیں کیا تھا؛ انہوں نے اللہ کی رضا کے لیے اسے اپنایا مگر پھر اس کا حق ادا نہ کیا (نباہ نہ سکے) (آیت 27)۔"]},{"q":[["mq12-l18-exercise-180",0]],"s":["اہلِ کتاب کا یہ گمان رد کیا گیا کہ اللہ کا فضل (نبوت اور ہدایت) صرف ان کے لیے مخصوص ہے؛ بتایا گیا کہ وہ اللہ کے فضل پر کچھ اختیار نہیں رکھتے؛ فضل اللہ کے ہاتھ میں ہے، جسے چاہے دے، اور اللہ بڑے فضل والا ہے (آیت 29)۔"]}],"longQuestions":[{"q":[["mq12-l18-exercise-180",2]],"s":["ترجمہ: وہی ہے جس نے آسمانوں اور زمین کو چھ دنوں میں پیدا کیا، پھر عرش پر مستوی ہوا؛ وہ جانتا ہے جو کچھ زمین میں داخل ہوتا ہے اور جو اس سے نکلتا ہے، اور جو آسمان سے اترتا ہے اور جو اس میں چڑھتا ہے؛ اور وہ تمہارے ساتھ ہے تم جہاں کہیں بھی ہو؛ اور اللہ تمہارے کاموں کو دیکھنے والا ہے۔ (الحدید 4)","تشریح: اللہ کی قدرتِ تخلیق، اقتدار اور کامل علم کا بیان؛ وہ اپنے علم اور قدرت سے ہر جگہ ہمارے ساتھ ہے، اس لیے ہر عمل اس کی نگاہ میں ہے۔"]},{"q":[["mq12-l18-exercise-180",3]],"s":["سورۃ الحدید مدنی سورت ہے؛ اس میں 29 آیات اور 4 رکوع ہیں؛ یہ غزوۂ احد اور صلح حدیبیہ کے درمیانی دور میں نازل ہوئی۔","نام: آیت 25 «وَاَنْزَلْنَا الْحَدِيْدَ» میں لوہے کا ذکر ہے، اسی سے نام \"الحدید\" (لوہا) رکھا گیا۔","موضوع: یہ مسبحات میں سے ہے (سبّح للّٰہ سے آغاز)؛ اس میں مسلمانوں کو اللہ کی راہ میں مال خرچ کرنے اور جہاد پر ابھارا گیا، دنیا کی بے ثباتی بیان کی گئی اور منافقین کا انجام بتایا گیا۔"]},{"q":[["mq12-l18-exercise-180",4]],"s":["ترجمہ: وہی ہے جو اپنے بندے (محمد ﷺ) پر واضح آیتیں نازل کرتا ہے تاکہ تمہیں اندھیروں سے روشنی کی طرف نکالے؛ اور بے شک اللہ تم پر بہت شفقت کرنے والا، نہایت مہربان ہے۔ (الحدید 9)","تشریح: قرآن کا مقصد انسان کو کفر، جہالت اور گمراہی کے اندھیروں سے ایمان، علم اور ہدایت کی روشنی میں لانا ہے؛ یہ اللہ کی رحمت ہے۔"]},{"q":[["mq12-l18-exercise-180",5]],"s":["سورۃ الحدید کے بنیادی مضامین: (1) اللہ کی تسبیح، صفات (اول، آخر، ظاہر، باطن) اور علم و قدرت؛ (2) ایمان اور انفاق فی سبیل اللہ کی دعوت؛ فتح سے پہلے اور بعد خرچ کرنے والوں کا فرق؛ قرضِ حسنہ۔","(3) قیامت کے دن مومنوں کا نور اور منافقوں کی بے بسی، دونوں کے درمیان دیوار؛ (4) دلوں کی سختی سے بچنے اور اللہ کے ذکر سے دل نرم کرنے کی تلقین؛ (5) دنیا کی زندگی کی حقیقت — کھیل تماشا، زینت، فخر اور مال و اولاد کی کثرت، بارش سے اگنے والی کھیتی کی مثال۔","(6) مغفرت اور جنت کی طرف سبقت؛ مصیبتیں تقدیر میں لکھی ہوئی؛ (7) رسولوں، کتاب، میزان اور لوہے کا نزول عدل کے قیام کے لیے؛ (8) نوحؑ، ابراہیمؑ اور عیسیٰؑ کا ذکر؛ رہبانیت کی حقیقت؛ اللہ کا فضل اس کے ہاتھ میں۔"]},{"q":[["mq12-l18-exercise-180",6]],"s":["ترجمہ: کوئی مصیبت نہ زمین میں پہنچتی ہے اور نہ تمہاری جانوں میں، مگر وہ ایک کتاب (لوحِ محفوظ) میں لکھی ہوئی ہے اس سے پہلے کہ ہم اسے پیدا کریں؛ بے شک یہ اللہ کے لیے آسان ہے۔ (الحدید 22)","تشریح: تقدیر پر ایمان کا فائدہ یہ ہے کہ انسان نقصان پر مایوس اور نعمت پر مغرور نہیں ہوتا؛ صبر اور شکر دونوں میں توازن رہتا ہے۔"]},{"q":[["mq12-l18-exercise-180",7]],"s":["آیت میں دو گروہوں کا موازنہ کیا گیا: تم میں سے جنہوں نے فتح (مکہ) سے پہلے (اللہ کی راہ میں) خرچ کیا اور جہاد کیا، وہ ان لوگوں سے درجے میں بہت بڑے ہیں جنہوں نے بعد میں خرچ کیا اور جہاد کیا۔ (الحدید 10)","وجہ: کمزوری اور خطرے کے دور میں قربانی زیادہ قیمتی ہے؛ تاہم اللہ نے دونوں سے بھلائی (جنت) کا وعدہ کیا ہے؛ اور تمہیں کیا ہوا کہ اللہ کی راہ میں خرچ نہیں کرتے حالانکہ آسمانوں اور زمین کی میراث اللہ ہی کی ہے۔"]}],"activities":[{"q":[["mq12-l18-exercise-180",9],["mq12-l18-exercise-180",10]],"s":["قیامت کے دن مومنوں اور منافقوں کا حال (الحدید 12–15): مومنوں کا نور ان کے آگے اور دائیں دوڑ رہا ہوگا اور انہیں جنت کی خوشخبری ملے گی؛ منافق مرد و عورت کہیں گے: ذرا ہمارا انتظار کرو تاکہ تمہارے نور سے کچھ روشنی لے لیں؛ جواب ملے گا: پیچھے لوٹ جاؤ اور روشنی تلاش کرو؛ پھر ان کے درمیان دیوار کھڑی کر دی جائے گی جس کے اندر رحمت اور باہر عذاب ہوگا؛ منافق پکاریں گے: کیا ہم تمہارے ساتھ نہ تھے؟ مومن کہیں گے: ہاں، مگر تم نے اپنے آپ کو فتنے میں ڈالا، انتظار کرتے رہے، شک میں پڑے اور جھوٹی امیدوں اور بڑے دھوکے باز (شیطان) نے تمہیں دھوکا دیا؛ آج تم سے کوئی فدیہ قبول نہ ہوگا، تمہارا ٹھکانا آگ ہے۔","لوہے کی خصوصیات اور فوائد (الحدید 25): جنگی قوت — ہتھیار، ٹینک، جہاز؛ تعمیرات — پل، عمارتیں، ریلوے؛ زراعت — ہل، ٹریکٹر اور اوزار؛ صنعت — مشینیں، گاڑیاں، برتن؛ طب — جسم میں ہیموگلوبن کا اہم جزو، خون کی کمی کا علاج؛ سائنسی نکتہ: «اَنْزَلْنَا» (اتارا) — جدید سائنس کے مطابق لوہا زمین پر خلا (شہابِ ثاقب اور ستاروں) سے آیا؛ طلبہ ان نکات پر مباحثہ کریں۔"]}]}},"19":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l19-exercise-186",3]],"o":[["mq12-l19-exercise-186",4],["mq12-l19-exercise-186",5],["mq12-l19-exercise-186",6],["mq12-l19-exercise-186",7]],"s":["سورۃ المجادلہ کے آغاز میں ظہار کے احکام بیان ہوئے ہیں — حضرت خولہ بنت ثعلبہؓ کے شوہر نے ان سے ظہار کیا تھا (آیات 1–4)۔"],"c":1},{"q":[["mq12-l19-exercise-186",8]],"o":[["mq12-l19-exercise-186",9],["mq12-l19-exercise-186",10],["mq12-l19-exercise-186",11],["mq12-l19-exercise-186",12]],"s":["«تَحَاوُرَكُمَا» — تم دونوں کی گفتگو (بات چیت) (آیت 1)۔"],"c":2},{"q":[["mq12-l19-exercise-186",13]],"o":[["mq12-l19-exercise-186",14],["mq12-l19-exercise-186",15],["mq12-l19-exercise-186",16],["mq12-l19-exercise-186",17]],"s":["ظہار کرنے والا پھر اپنی بات سے رجوع کرنا چاہے تو اس کا کفارہ ایک غلام آزاد کرنا ہے، اس سے پہلے کہ دونوں ایک دوسرے کو چھوئیں (آیت 3)۔"],"c":1},{"q":[["mq12-l19-exercise-186",18]],"o":[["mq12-l19-exercise-186",19],["mq12-l19-exercise-186",20],["mq12-l19-exercise-186",21],["mq12-l19-exercise-186",22]],"s":["«نَجْوٰى» — سرگوشی، خفیہ مشورہ (آیت 7)۔"],"c":0},{"q":[["mq12-l19-exercise-187",0]],"o":[["mq12-l19-exercise-187",1],["mq12-l19-exercise-187",2],["mq12-l19-exercise-187",3],["mq12-l19-exercise-187",4]],"s":["«وَتَنَاجَوْا بِالْبِرِّ وَالتَّقْوٰى» — نیکی اور تقویٰ کے لیے سرگوشی (مشورہ) کرو (آیت 9)۔"],"c":1},{"q":[["mq12-l19-exercise-187",5]],"o":[["mq12-l19-exercise-187",6],["mq12-l19-exercise-187",7],["mq12-l19-exercise-187",8],["mq12-l19-exercise-187",9]],"s":["اللہ تم میں سے ایمان والوں اور ان لوگوں کے درجے بلند کرتا ہے جنہیں علم دیا گیا (آیت 11)۔"],"c":3},{"q":[["mq12-l19-exercise-187",10]],"o":[["mq12-l19-exercise-187",11],["mq12-l19-exercise-187",12],["mq12-l19-exercise-187",13],["mq12-l19-exercise-187",14]],"s":["«جُنَّةً» — ڈھال؛ منافقوں نے اپنی قسموں کو ڈھال بنا رکھا ہے (آیت 16)۔"],"c":3}],"shortQuestions":[{"q":[["mq12-l19-exercise-187",16]],"s":["ظہار کرنے والوں کو بتایا گیا کہ (بیوی کو ماں کہہ دینے سے) وہ ان کی مائیں نہیں بن جاتیں؛ ان کی مائیں تو وہی ہیں جنہوں نے انہیں جنا؛ وہ ایک بری اور جھوٹی بات کہتے ہیں؛ اور اللہ معاف کرنے والا، بخشنے والا ہے (آیت 2)۔"]},{"q":[["mq12-l19-exercise-187",17]],"s":["جو غلام آزاد کرنے کی طاقت نہ پائے وہ (بیوی کو چھونے سے پہلے) دو ماہ کے لگاتار روزے رکھے؛ اور جو اس کی بھی طاقت نہ رکھے وہ ساٹھ مسکینوں کو کھانا کھلائے (آیت 4)۔"]},{"q":[["mq12-l19-exercise-187",18]],"s":["جو لوگ اللہ اور اس کے رسول کی مخالفت کرتے ہیں وہ ذلیل کیے جائیں گے جیسے ان سے پہلے لوگ ذلیل کیے گئے؛ ہم نے واضح آیتیں اتار دی ہیں، اور کافروں کے لیے ذلت والا عذاب ہے (آیت 5)۔"]},{"q":[["mq12-l19-exercise-187",19]],"s":["بری سرگوشی شیطان کی طرف سے ہے تاکہ ایمان والوں کو غمگین کرے؛ حالانکہ وہ اللہ کے حکم کے بغیر انہیں کچھ نقصان نہیں پہنچا سکتی؛ اور مومنوں کو اللہ ہی پر بھروسا رکھنا چاہیے (آیت 10)۔"]},{"q":[["mq12-l19-exercise-187",20]],"s":["منافقوں نے اپنی (جھوٹی) قسموں کو ڈھال بنا لیا ہے اور (اس کی آڑ میں) لوگوں کو اللہ کی راہ سے روکتے ہیں؛ پس ان کے لیے ذلت والا عذاب ہے (آیت 16)۔"]},{"q":[["mq12-l19-exercise-187",21]],"s":["جس دن اللہ ان سب کو اٹھائے گا تو وہ اس کے سامنے بھی (جھوٹی) قسمیں کھائیں گے جیسے تمہارے سامنے کھاتے ہیں، اور سمجھیں گے کہ وہ کسی (اچھی) بات پر ہیں؛ خبردار! وہی جھوٹے ہیں؛ شیطان ان پر غالب آ گیا اور انہیں اللہ کا ذکر بھلا دیا؛ وہ شیطان کا گروہ ہیں (آیات 18–19)۔"]},{"q":[["mq12-l19-exercise-187",22]],"s":["اللہ نے لکھ دیا ہے کہ میں اور میرے رسول ضرور غالب رہیں گے؛ بے شک اللہ طاقتور، زبردست ہے — یعنی حقیقی غلبہ اللہ اور اس کے رسولوں (اور ان کے پیروکاروں — حزب اللہ) کا ہے (آیت 21)۔"]}],"longQuestions":[{"q":[["mq12-l19-exercise-187",24]],"s":["ترجمہ: جس دن اللہ ان سب کو (دوبارہ زندہ کر کے) اٹھائے گا پھر انہیں ان کے اعمال بتائے گا؛ اللہ نے ان (اعمال) کو گن رکھا ہے اور وہ انہیں بھول گئے؛ اور اللہ ہر چیز پر گواہ ہے۔ (المجادلہ 6)","تشریح: انسان اپنے گناہ بھول جاتا ہے مگر اللہ کے پاس سب کا مکمل ریکارڈ ہے؛ قیامت کے دن ہر عمل سامنے آ جائے گا۔"]},{"q":[["mq12-l19-exercise-187",25]],"s":["سورۃ المجادلہ مدنی سورت ہے؛ اس میں 22 آیات اور 3 رکوع ہیں؛ یہ تقریباً 5ھ کے قریب نازل ہوئی۔","نام: آیت 1 میں اس عورت (حضرت خولہ بنت ثعلبہؓ) کا ذکر ہے جو اپنے شوہر حضرت اوس بن صامتؓ کے ظہار کے بارے میں نبی ﷺ سے \"مجادلہ\" (تکرار کے ساتھ بات) کر رہی تھیں اور اللہ سے فریاد کر رہی تھیں؛ اسی سے نام \"المجادلہ\" ہے۔","اہمیت: حضرت عائشہؓ نے فرمایا: پاک ہے وہ ذات جس کی سماعت ہر آواز کو گھیرے ہوئے ہے؛ وہ عورت گھر کے کونے میں بات کر رہی تھی اور میں پوری نہ سن سکی، مگر اللہ نے آسمان سے سن لی۔"]},{"q":[["mq12-l19-exercise-187",26]],"s":["ترجمہ: اے ایمان والو! جب تم رسول سے سرگوشی (علیحدگی میں بات) کرنا چاہو تو اپنی سرگوشی سے پہلے کچھ صدقہ دے دیا کرو؛ یہ تمہارے لیے بہتر اور زیادہ پاکیزہ ہے؛ پھر اگر (صدقے کے لیے کچھ) نہ پاؤ تو بے شک اللہ بخشنے والا، مہربان ہے۔ (المجادلہ 12)","تشریح: اس حکم کا مقصد بلا ضرورت طویل سرگوشیوں سے نبی ﷺ کا وقت بچانا اور غریبوں کی مدد تھا؛ یہ حکم بعد میں آیت 13 سے منسوخ ہو گیا اور نماز، زکوٰۃ اور اطاعت کی تلقین باقی رہی۔"]},{"q":[["mq12-l19-exercise-187",27]],"s":["سورۃ المجادلہ کے بنیادی مضامین: (1) ظہار کی حقیقت، اس کا حکم اور کفارہ (غلام آزاد کرنا، دو ماہ کے روزے یا ساٹھ مسکینوں کو کھانا)؛ اللہ کا ہر بات سننا؛ (2) اللہ اور رسول کے مخالفین کی ذلت؛ اللہ کا ہر سرگوشی میں موجود ہونا (تین ہوں تو چوتھا وہ)۔","(3) سرگوشی کے آداب — گناہ، زیادتی اور رسول کی نافرمانی کی سرگوشی ممنوع، نیکی اور تقویٰ کی جائز؛ یہود اور منافقین کا \"السام علیک\" کہنا؛ (4) مجلس کے آداب — جگہ کشادہ کرنا، کہا جائے تو اٹھ جانا؛ اہلِ ایمان اور اہلِ علم کے درجات کی بلندی؛ نبی ﷺ سے سرگوشی سے پہلے صدقہ۔","(5) منافقین کی یہود سے دوستی، جھوٹی قسمیں اور انجام — حزب الشیطان؛ (6) اللہ اور رسولوں کے غلبے کا اعلان؛ (7) اللہ اور رسول کے دشمنوں سے دوستی نہ رکھنا، چاہے باپ، بیٹے، بھائی یا رشتہ دار ہوں — ایسے لوگ حزب اللہ ہیں اور وہی کامیاب ہیں (آیت 22)۔"]},{"q":[["mq12-l19-exercise-188",0]],"s":["ترجمہ: کیا آپ نے ان لوگوں کو نہیں دیکھا جنہوں نے ایسی قوم (یہود) سے دوستی کی جس پر اللہ کا غضب ہے؟ وہ نہ تم میں سے ہیں اور نہ ان میں سے، اور وہ جان بوجھ کر جھوٹی بات پر قسمیں کھاتے ہیں۔ (المجادلہ 14)","تشریح: یہ منافقین کا حال ہے جو مسلمانوں اور یہود دونوں کے ساتھ رہنا چاہتے تھے؛ ان کا کوئی ٹھکانا نہیں اور ان کی پہچان جھوٹی قسمیں ہیں۔"]},{"q":[["mq12-l19-exercise-188",1]],"s":["تعلیم: اے ایمان والو! جب تم آپس میں سرگوشی کرو تو گناہ، زیادتی اور رسول کی نافرمانی کی سرگوشی نہ کرو، بلکہ نیکی اور تقویٰ کی سرگوشی کرو؛ اور اللہ سے ڈرو جس کی طرف تم جمع کیے جاؤ گے۔ (المجادلہ 9)","یعنی خفیہ مشورے بذاتِ خود منع نہیں، ان کا مقصد اچھا ہونا چاہیے؛ حدیث میں ہے کہ جب تین آدمی ہوں تو دو آپس میں سرگوشی نہ کریں کیونکہ اس سے تیسرا غمگین ہوگا۔"]}],"activities":[{"q":[["mq12-l19-exercise-188",3],["mq12-l19-exercise-188",4]],"s":["مجلس کے آداب (المجادلہ 11 اور احادیث): مجلس میں جگہ کشادہ کرو؛ کہا جائے تو اٹھ جاؤ؛ کسی کو اس کی جگہ سے اٹھا کر خود نہ بیٹھو (بخاری)؛ جو اپنی جگہ سے اٹھ کر واپس آئے وہی اس کا زیادہ حق دار ہے (مسلم)؛ دو آدمیوں کے درمیان ان کی اجازت کے بغیر نہ بیٹھو (ابو داؤد)؛ جہاں جگہ ملے وہیں بیٹھ جاؤ؛ مجلس میں آتے اور جاتے وقت سلام کرو؛ مجلس کے اختتام پر کفارۂ مجلس کی دعا پڑھو: «سُبْحَانَكَ اللّٰهُمَّ وَبِحَمْدِكَ اَشْهَدُ اَنْ لَّا اِلٰهَ اِلَّا اَنْتَ اَسْتَغْفِرُكَ وَاَتُوْبُ اِلَيْكَ» (ترمذی)۔","سرگوشی سے متعلق حدیث: «اِذَا كَانُوْا ثَلَاثَةً فَلَا يَتَنَاجَى اثْنَانِ دُوْنَ الثَّالِثِ» — جب تین آدمی ہوں تو دو آدمی تیسرے کو چھوڑ کر سرگوشی نہ کریں، یہاں تک کہ لوگوں میں مل جائیں، کیونکہ یہ اسے غمگین کرے گا (بخاری و مسلم)۔"]}]}},"20":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l20-exercise-194",3]],"o":[["mq12-l20-exercise-194",4],["mq12-l20-exercise-194",5],["mq12-l20-exercise-194",6],["mq12-l20-exercise-194",7]],"s":["اللہ نے اہلِ کتاب (بنو نضیر) کے کافروں کو ان کے گھروں سے نکال دیا (الحشر 2)۔"],"c":2},{"q":[["mq12-l20-exercise-194",8]],"o":[["mq12-l20-exercise-194",9],["mq12-l20-exercise-194",10],["mq12-l20-exercise-194",11],["mq12-l20-exercise-194",12]],"s":["یہود نے سمجھا کہ ان کے قلعے انہیں اللہ (کے عذاب) سے بچا لیں گے (آیت 2)۔"],"c":0},{"q":[["mq12-l20-exercise-194",13]],"o":[["mq12-l20-exercise-194",14],["mq12-l20-exercise-194",15],["mq12-l20-exercise-194",16],["mq12-l20-exercise-194",17]],"s":["«الْجَلَآءَ» — جلاوطنی (آیت 3)۔"],"c":1},{"q":[["mq12-l20-exercise-194",18]],"o":[["mq12-l20-exercise-194",19],["mq12-l20-exercise-194",20],["mq12-l20-exercise-194",21],["mq12-l20-exercise-194",22]],"s":["«لِيْنَةٍ» — کھجور کا درخت؛ بنو نضیر کے محاصرے میں کھجور کے کچھ درخت کاٹے گئے (آیت 5)۔"],"c":0},{"q":[["mq12-l20-exercise-195",0]],"o":[["mq12-l20-exercise-195",1],["mq12-l20-exercise-195",2],["mq12-l20-exercise-195",3],["mq12-l20-exercise-195",4]],"s":["«وَمَنْ يُّوْقَ شُحَّ نَفْسِهٖ» — جو اپنے نفس کے بخل (لالچ) سے بچا لیا گیا وہی کامیاب ہیں (آیت 9)۔"],"c":3},{"q":[["mq12-l20-exercise-195",5]],"o":[["mq12-l20-exercise-195",6],["mq12-l20-exercise-195",7],["mq12-l20-exercise-195",8],["mq12-l20-exercise-195",9]],"s":["یہ مثالیں ہم لوگوں کے لیے بیان کرتے ہیں تاکہ وہ غور و فکر کریں (آیت 21)۔"],"c":3},{"q":[["mq12-l20-exercise-195",10]],"o":[["mq12-l20-exercise-195",11],["mq12-l20-exercise-195",12],["mq12-l20-exercise-195",13],["mq12-l20-exercise-195",14]],"s":["«الْقُدُّوْسُ» — نہایت پاک (ہر عیب سے پاک) ذات (آیت 23)۔"],"c":2}],"shortQuestions":[{"q":[["mq12-l20-exercise-195",16]],"s":["اگر اللہ نے ان کے لیے جلاوطنی نہ لکھ دی ہوتی تو انہیں دنیا ہی میں (قتل و قید کا) عذاب دیتا، اور آخرت میں ان کے لیے آگ کا عذاب ہے (آیت 3)۔"]},{"q":[["mq12-l20-exercise-195",17]],"s":["سزا کی وجہ یہ ہے کہ انہوں نے اللہ اور اس کے رسول کی مخالفت کی؛ اور جو اللہ کی مخالفت کرے تو اللہ سخت سزا دینے والا ہے (آیت 4)۔"]},{"q":[["mq12-l20-exercise-195",18]],"s":["منافقین کا رویہ: اگر یہود نکالے گئے تو وہ (منافق) ان کے ساتھ نہیں نکلیں گے، اگر ان سے جنگ ہوئی تو ان کی مدد نہیں کریں گے، اور اگر مدد کی بھی تو پیٹھ پھیر کر بھاگیں گے، پھر ان کی کوئی مدد نہ ہوگی (آیت 12) — یعنی ان کے وعدے جھوٹے ہیں۔"]},{"q":[["mq12-l20-exercise-195",19]],"s":["یہود کے دلوں میں تمہارا خوف اللہ سے بھی زیادہ ہے؛ یہ اس لیے کہ وہ ناسمجھ لوگ ہیں (آیت 13)۔"]},{"q":[["mq12-l20-exercise-195",20]],"s":["یہود سب مل کر تم سے کھلے میدان میں نہیں لڑیں گے بلکہ قلعہ بند بستیوں میں یا دیواروں کے پیچھے سے لڑیں گے؛ ان کی آپس کی لڑائی سخت ہے؛ تم انہیں متحد سمجھتے ہو حالانکہ ان کے دل پھٹے ہوئے ہیں (آیت 14)۔"]},{"q":[["mq12-l20-exercise-195",21]],"s":["اے ایمان والو! اللہ سے ڈرو، اور ہر شخص دیکھ لے کہ اس نے کل (قیامت) کے لیے آگے کیا بھیجا ہے، اور اللہ سے ڈرو؛ بے شک اللہ تمہارے کاموں سے باخبر ہے (آیت 18)۔"]},{"q":[["mq12-l20-exercise-195",22]],"s":["دوزخ والے اور جنت والے برابر نہیں ہو سکتے؛ جنت والے ہی کامیاب ہیں (آیت 20)۔"]}],"longQuestions":[{"q":[["mq12-l20-exercise-195",24]],"s":["ترجمہ: تم نے کھجور کے جو درخت کاٹے یا انہیں ان کی جڑوں پر کھڑا رہنے دیا تو یہ اللہ ہی کے حکم سے تھا، اور تاکہ وہ نافرمانوں کو رسوا کرے۔ (الحشر 5)","تشریح: بنو نضیر کے محاصرے میں جنگی ضرورت کے تحت کچھ درخت کاٹے گئے؛ یہود نے اعتراض کیا تو بتایا گیا کہ یہ اللہ کی اجازت سے تھا اور اس کا مقصد دشمن کی شکست اور رسوائی تھا۔"]},{"q":[["mq12-l20-exercise-195",25]],"s":["سورۃ الحشر مدنی سورت ہے؛ اس میں 24 آیات اور 3 رکوع ہیں؛ یہ ربیع الاول 4ھ میں یہود کے قبیلہ بنو نضیر کی جلاوطنی کے موقع پر نازل ہوئی؛ حضرت ابن عباسؓ اسے \"سورۃ بنی النضیر\" کہتے تھے۔","نام: آیت 2 «لِاَوَّلِ الْحَشْرِ» (پہلی بار اکٹھا کر کے نکالنا) سے نام \"الحشر\" رکھا گیا۔","پس منظر: بنو نضیر نے معاہدہ توڑ کر نبی ﷺ کو (دیوار سے پتھر گرا کر) شہید کرنے کی سازش کی؛ آپ ﷺ نے ان کا محاصرہ کیا؛ منافقین (عبداللہ بن ابی) کی امداد کے وعدے جھوٹے نکلے اور یہود جلاوطن ہو کر خیبر اور شام چلے گئے۔"]},{"q":[["mq12-l20-exercise-195",26]],"s":["ترجمہ: اور جو مال اللہ نے ان (یہود) سے (بغیر جنگ) اپنے رسول کو دلوایا، اس پر تم نے نہ گھوڑے دوڑائے نہ اونٹ، لیکن اللہ اپنے رسولوں کو جس پر چاہتا ہے مسلط کر دیتا ہے؛ اور اللہ ہر چیز پر قادر ہے۔ (الحشر 6)","تشریح: یہ مالِ فے ہے جو بغیر لڑائی کے حاصل ہو؛ یہ مجاہدین میں غنیمت کی طرح تقسیم نہیں ہوتا بلکہ رسول ﷺ (اور بعد میں بیت المال) کے اختیار میں ہوتا ہے۔"]},{"q":[["mq12-l20-exercise-195",27]],"s":["سورۃ الحشر کے بنیادی مضامین: (1) کائنات کی ہر چیز اللہ کی تسبیح کرتی ہے؛ (2) بنو نضیر کی عہد شکنی، جلاوطنی اور اس سے عبرت (فاعتبروا یا اولی الابصار)؛ (3) درخت کاٹنے کی اجازت؛ (4) مالِ فے کے احکام اور مستحقین؛ اس کی حکمت کہ دولت صرف مالداروں میں گردش نہ کرے؛ رسول ﷺ جو دیں لے لو اور جس سے روکیں رک جاؤ۔","(5) مہاجرین کی فضیلت (اللہ کا فضل اور رضا چاہنے والے، سچے)؛ انصار کا ایثار — خود محتاج ہو کر دوسروں کو ترجیح دینا؛ بعد میں آنے والوں کی دعا (ربنا اغفر لنا ولاخواننا)؛ (6) منافقین کے جھوٹے وعدے اور شیطان کی مثال؛ یہود کی بزدلی اور باہمی انتشار۔","(7) تقویٰ اور آخرت کی تیاری؛ اللہ کو بھولنے والوں جیسا نہ بننا؛ (8) قرآن کی عظمت — پہاڑ پر اترتا تو خشیت سے پھٹ جاتا؛ (9) اسمائے حسنیٰ کا بیان (آیات 22–24)۔"]},{"q":[["mq12-l20-exercise-195",28]],"s":["ترجمہ: کیا آپ نے منافقوں کو نہیں دیکھا جو اپنے کافر اہلِ کتاب بھائیوں سے کہتے ہیں: اگر تم نکالے گئے تو ہم بھی ضرور تمہارے ساتھ نکلیں گے اور تمہارے معاملے میں کبھی کسی کی بات نہیں مانیں گے، اور اگر تم سے جنگ ہوئی تو ہم ضرور تمہاری مدد کریں گے؛ اور اللہ گواہی دیتا ہے کہ وہ بالکل جھوٹے ہیں۔ (الحشر 11)","تشریح: عبداللہ بن ابی اور اس کے ساتھیوں نے بنو نضیر کو مدد کا یقین دلایا مگر وقت آنے پر ساتھ نہ دیا؛ منافقت اور جھوٹے وعدے ساتھ ساتھ چلتے ہیں۔"]},{"q":[["mq12-l20-exercise-196",0]],"s":["قرآن کی عظمت: اگر ہم یہ قرآن کسی پہاڑ پر نازل کرتے تو آپ اسے اللہ کے خوف سے دبا ہوا اور پھٹا ہوا دیکھتے۔ (الحشر 21)","یعنی قرآن اتنا عظیم اور پراثر کلام ہے کہ پہاڑ بھی اس کا بوجھ نہ سہار سکتا؛ انسان کو جسے عقل اور دل دیا گیا ہے اس سے زیادہ متاثر ہونا چاہیے؛ یہ مثالیں ہم لوگوں کے لیے بیان کرتے ہیں تاکہ وہ غور و فکر کریں۔"]}],"activities":[{"q":[["mq12-l20-exercise-196",2],["mq12-l20-exercise-196",3],["mq12-l20-exercise-196",4]],"s":["مالِ فے کی تفصیل (الحشر 6–10): وہ مال جو کافروں سے جنگ کے بغیر حاصل ہو (صلح، جزیہ، خراج، جلاوطنی کے بعد چھوڑی ہوئی جائیداد)؛ اس کے مستحق: اللہ اور رسول، قرابت دار، یتیم، مسکین، مسافر، محتاج مہاجرین، انصار اور بعد میں آنے والے مسلمان؛ حکمت: «كَيْ لَا يَكُوْنَ دُوْلَةً بَيْنَ الْاَغْنِيَآءِ مِنْكُمْ» — تاکہ دولت صرف مالداروں کے درمیان گردش نہ کرے؛ حضرت عمرؓ نے اسی آیت کی بنیاد پر مفتوحہ زمینیں پوری امت کے لیے وقف رکھیں۔","ایثار پر عمل کی ممکنہ صورتیں (آیت 9): بھوکے ساتھی کو اپنا کھانا دینا؛ ضرورت مند ہم جماعت کو اپنی کتابیں یا قلم دینا؛ قطار میں بزرگ یا معذور کو آگے کرنا؛ بس میں اپنی نشست دوسروں کو دینا؛ عید پر اپنی چیزوں میں سے غریب بچوں کو حصہ دینا؛ خون کا عطیہ؛ وقت اور محنت سے دوسروں کی مدد — جیسے انصار نے مہاجرین کو اپنے گھر اور باغ میں شریک کیا۔","سورۃ الحشر کے اسمائے حسنیٰ (آیات 22–24) ترجمے کے ساتھ: اللہ، عالم الغیب والشہادۃ (غائب و حاضر کا جاننے والا)، الرحمٰن (بہت مہربان)، الرحیم (نہایت رحم والا)، الملک (بادشاہ)، القدوس (نہایت پاک)، السلام (سلامتی دینے والا)، المؤمن (امن دینے والا)، المہیمن (نگہبان)، العزیز (غالب)، الجبار (زبردست)، المتکبر (بڑائی والا)، الخالق (پیدا کرنے والا)، الباری (وجود بخشنے والا)، المصوّر (صورت بنانے والا)، الحکیم (حکمت والا)۔"]}]}},"21":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l21-exercise-201",2]],"o":[["mq12-l21-exercise-201",3],["mq12-l21-exercise-201",4],["mq12-l21-exercise-201",5],["mq12-l21-exercise-201",6]],"s":["اے ایمان والو! میرے اور اپنے دشمنوں کو دوست نہ بناؤ (الممتحنہ 1)۔"],"c":3},{"q":[["mq12-l21-exercise-201",7]],"o":[["mq12-l21-exercise-201",8],["mq12-l21-exercise-201",9],["mq12-l21-exercise-201",10],["mq12-l21-exercise-201",11]],"s":["«يَثْقَفُوْكُمْ» — اگر وہ تم پر قابو پا جائیں (آیت 2)۔"],"c":1},{"q":[["mq12-l21-exercise-201",12]],"o":[["mq12-l21-exercise-201",13],["mq12-l21-exercise-201",14],["mq12-l21-exercise-201",15],["mq12-l21-exercise-201",16]],"s":["قیامت کے دن تمہاری رشتہ داریاں (قرابتیں) اور اولاد تمہیں ہرگز فائدہ نہ دیں گی (آیت 3)۔"],"c":2},{"q":[["mq12-l21-exercise-201",17]],"o":[["mq12-l21-exercise-201",18],["mq12-l21-exercise-201",19],["mq12-l21-exercise-201",20],["mq12-l21-exercise-201",21]],"s":["«اِنَّا بُرَءٰٓؤُا مِنْكُمْ» — حضرت ابراہیمؑ اور ان کے ساتھیوں نے قوم اور ان کے معبودوں سے بیزاری (برأت) کا اعلان کیا (آیت 4)۔"],"c":3},{"q":[["mq12-l21-exercise-201",22]],"o":[["mq12-l21-exercise-201",23],["mq12-l21-exercise-201",24],["mq12-l21-exercise-201",25],["mq12-l21-exercise-201",26]],"s":["«فَامْتَحِنُوْهُنَّ» — ہجرت کر کے آنے والی مومن عورتوں کا امتحان (جانچ) کر لو (آیت 10)۔"],"c":2},{"q":[["mq12-l21-exercise-201",27]],"o":[["mq12-l21-exercise-201",28],["mq12-l21-exercise-201",29],["mq12-l21-exercise-201",30],["mq12-l21-exercise-201",31]],"s":["«وَلَا تُمْسِكُوْا بِعِصَمِ الْكَوَافِرِ» — کافر عورتوں کو اپنے نکاح میں نہ روکے رکھو (آیت 10)۔"],"c":3},{"q":[["mq12-l21-exercise-201",32]],"o":[["mq12-l21-exercise-201",33],["mq12-l21-exercise-201",34],["mq12-l21-exercise-201",35],["mq12-l21-exercise-201",36]],"s":["«لَا يَسْرِقْنَ» — وہ چوری نہیں کریں گی (آیت 12)۔"],"c":2}],"shortQuestions":[{"q":[["mq12-l21-exercise-202",1]],"s":["کافروں کے برے ارادے: اگر وہ تم پر قابو پا لیں تو تمہارے دشمن بن جائیں، اپنے ہاتھ اور زبانیں برائی کے ساتھ تم پر دراز کریں، اور وہ چاہتے ہیں کہ کاش تم بھی کافر ہو جاؤ (آیت 2)۔"]},{"q":[["mq12-l21-exercise-202",2]],"s":["قیامت کے دن رشتہ داریاں اور اولاد کام نہ آئیں گی؛ اللہ تمہارے درمیان فیصلہ کرے گا اور وہ تمہارے اعمال دیکھ رہا ہے (آیت 3) — یہ حضرت حاطب بن ابی بلتعہؓ کے واقعے کے پس منظر میں ہے جنہوں نے اپنے گھر والوں کی خاطر قریش کو خط لکھا تھا۔"]},{"q":[["mq12-l21-exercise-202",3]],"s":["حضرت ابراہیمؑ اور ان کے ساتھیوں میں ان لوگوں کے لیے بہترین نمونہ ہے جو اللہ اور آخرت کے دن کی امید رکھتے ہوں (آیت 6)۔"]},{"q":[["mq12-l21-exercise-202",4]],"s":["اللہ نے خبر دی کہ امید ہے وہ تمہارے اور ان (کافر رشتہ داروں) کے درمیان جن سے تمہاری دشمنی ہے محبت پیدا کر دے؛ اللہ قدرت والا، بخشنے والا، مہربان ہے (آیت 7) — یہ فتحِ مکہ پر پورا ہوا جب اہلِ مکہ مسلمان ہو گئے۔"]},{"q":[["mq12-l21-exercise-202",5]],"s":["اگر جانچ کے بعد معلوم ہو کہ وہ مومن ہیں تو انہیں کافروں کی طرف واپس نہ کرو؛ نہ وہ کافروں کے لیے حلال ہیں اور نہ کافر ان کے لیے؛ ان کے کافر شوہروں نے جو مہر خرچ کیا وہ انہیں ادا کر دو اور تم ان سے مہر دے کر نکاح کر سکتے ہو (آیت 10)۔"]},{"q":[["mq12-l21-exercise-202",6]],"s":["مہر کا حکم: (مسلمانوں کی جو بیویاں کافر ہو کر کافروں کے پاس چلی جائیں) تم ان کا دیا ہوا مہر مانگ لو، اور (کافروں کی جو بیویاں مسلمان ہو کر آئیں) کافر اپنا خرچ کیا ہوا مہر مانگ لیں؛ یہ اللہ کا حکم ہے جو تمہارے درمیان فیصلہ کرتا ہے (آیت 10)۔"]},{"q":[["mq12-l21-exercise-202",7]],"s":["اے ایمان والو! ایسی قوم (یہود و کفار) سے دوستی نہ کرو جس پر اللہ کا غضب ہے؛ وہ آخرت سے ایسے مایوس ہو چکے ہیں جیسے کافر قبر والوں (کے دوبارہ زندہ ہونے) سے مایوس ہیں (آیت 13)۔"]}],"longQuestions":[{"q":[["mq12-l21-exercise-202",9]],"s":["ترجمہ: اے ہمارے رب! ہمیں کافروں کے لیے آزمائش (فتنہ) نہ بنا اور ہمیں بخش دے؛ اے ہمارے رب! بے شک تو ہی غالب، حکمت والا ہے۔ (الممتحنہ 5)","تشریح: یہ حضرت ابراہیمؑ اور ان کے ساتھیوں کی دعا ہے — یعنی ہمیں کافروں کے ہاتھوں مغلوب نہ کر کہ وہ سمجھیں ہم حق پر ہیں، اور ہماری کمزوریوں کی وجہ سے وہ دین سے متنفر نہ ہوں۔"]},{"q":[["mq12-l21-exercise-202",10]],"s":["سورۃ الممتحنہ مدنی سورت ہے؛ اس میں 13 آیات اور 2 رکوع ہیں؛ اس کا ابتدائی حصہ فتحِ مکہ (8ھ) سے کچھ پہلے اور دوسرا حصہ صلح حدیبیہ کے بعد نازل ہوا۔","نام: آیت 10 «فَامْتَحِنُوْهُنَّ» (ان کا امتحان لو) سے نام \"الممتحنہ\" (امتحان لی جانے والی عورت) رکھا گیا۔","پس منظر: حضرت حاطب بن ابی بلتعہؓ نے فتحِ مکہ کی تیاری کی خبر خفیہ خط کے ذریعے قریش کو بھیجنا چاہی؛ وحی سے خط پکڑا گیا؛ آپ ﷺ نے ان کے بدری ہونے کی وجہ سے معاف کیا، اور اس پر کافروں سے دوستی کی ممانعت نازل ہوئی۔"]},{"q":[["mq12-l21-exercise-202",11]],"s":["ترجمہ: اللہ تمہیں ان لوگوں کے ساتھ نیکی اور انصاف کرنے سے منع نہیں کرتا جنہوں نے دین کے معاملے میں تم سے جنگ نہیں کی اور تمہیں تمہارے گھروں سے نہیں نکالا؛ بے شک اللہ انصاف کرنے والوں کو پسند کرتا ہے۔ (الممتحنہ 8)","تشریح: پرامن غیر مسلموں سے حسنِ سلوک اور انصاف جائز بلکہ پسندیدہ ہے؛ ممانعت صرف ان سے دوستی کی ہے جو اسلام سے لڑیں اور مسلمانوں کو نکالیں (آیت 9)؛ یہ اسلامی ریاست میں اقلیتوں کے حقوق کی بنیاد ہے۔"]},{"q":[["mq12-l21-exercise-202",12]],"s":["سورۃ الممتحنہ کے بنیادی مضامین: (1) اللہ اور مسلمانوں کے دشمنوں سے قلبی دوستی کی ممانعت (حاطبؓ کا واقعہ)؛ (2) کافروں کے عزائم؛ قیامت میں رشتہ داری کا بے فائدہ ہونا؛ (3) حضرت ابراہیمؑ کا اسوۂ حسنہ — شرک اور مشرکوں سے برأت اور ان کی دعائیں۔","(4) کافروں سے دوستی کی امید (فتحِ مکہ) اور پرامن غیر مسلموں سے حسنِ سلوک اور انصاف کی اجازت؛ (5) ہجرت کر کے آنے والی عورتوں کا امتحان، انہیں واپس نہ کرنا، مسلمان اور کافر کا باہمی نکاح ختم ہونا، مہر کا لین دین۔","(6) عورتوں سے بیعت کی شرائط — شرک، چوری، زنا، قتلِ اولاد، بہتان اور نافرمانی سے بچنا؛ (7) اللہ کے غضب والی قوم سے دوستی کی ممانعت — یوں یہ سورت اسلامی ریاست کے داخلی اور خارجی تعلقات کے اصول بیان کرتی ہے۔"]},{"q":[["mq12-l21-exercise-202",13]],"s":["ترجمہ: اور اگر تمہاری بیویوں میں سے کوئی (مرتد ہو کر) کافروں کے پاس چلی جائے، پھر تمہاری باری آئے (یعنی تمہیں غنیمت ملے یا کافروں سے مہر لینا ہو) تو جن کی بیویاں چلی گئی ہیں انہیں اتنا دے دو جتنا انہوں نے (مہر میں) خرچ کیا تھا؛ اور اس اللہ سے ڈرو جس پر تم ایمان رکھتے ہو۔ (الممتحنہ 11)","تشریح: اگر کافر مہر واپس نہ کریں تو اسلامی ریاست (غنیمت یا بیت المال سے) متاثرہ مسلمان کا نقصان پورا کرے — یہ عدل اور سماجی کفالت کا اصول ہے۔"]},{"q":[["mq12-l21-exercise-202",14]],"s":["آیت میں نبی ﷺ کو حکم دیا گیا کہ جب مومن عورتیں آپ سے ان باتوں پر بیعت کرنے آئیں تو ان سے بیعت لیجیے: (1) اللہ کے ساتھ کسی کو شریک نہ کریں گی؛ (2) چوری نہ کریں گی؛ (3) زنا نہ کریں گی؛ (4) اپنی اولاد کو قتل نہ کریں گی؛ (5) اپنے ہاتھوں اور پاؤں کے درمیان سے کوئی بہتان گھڑ کر نہ لائیں گی (کسی اور کا بچہ شوہر کے سر نہ ڈالیں گی)؛ (6) کسی نیک کام میں آپ کی نافرمانی نہ کریں گی۔ (الممتحنہ 12)","پھر ان کے لیے اللہ سے مغفرت کی دعا کیجیے؛ بے شک اللہ بخشنے والا، مہربان ہے — نبی ﷺ نے فتحِ مکہ کے دن عورتوں سے زبانی بیعت لی، ہاتھ نہیں ملایا۔"]}],"activities":[{"q":[["mq12-l21-exercise-202",16],["mq12-l21-exercise-202",17]],"s":["بیعت کے امور کی فہرست (الممتحنہ 12): (1) شرک نہ کرنا؛ (2) چوری نہ کرنا؛ (3) زنا نہ کرنا؛ (4) اولاد کو قتل نہ کرنا (آج کے دور میں اسقاطِ حمل اور بیٹیوں سے امتیاز بھی اس میں آتا ہے)؛ (5) بہتان نہ گھڑنا؛ (6) نیکی کے کاموں میں رسول ﷺ کی نافرمانی نہ کرنا — طلبہ ان پر آپس میں گفتگو کریں کہ یہ کس طرح ایک پاکیزہ معاشرے کی بنیاد ہیں۔","حضرت ابراہیمؑ کی دعائیں (الممتحنہ 4–5): «رَبَّنَا عَلَيْكَ تَوَكَّلْنَا وَاِلَيْكَ اَنَبْنَا وَاِلَيْكَ الْمَصِيْرُ» — اے ہمارے رب! ہم نے تجھ پر بھروسا کیا، تیری طرف رجوع کیا اور تیری ہی طرف لوٹنا ہے؛ «رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِيْنَ كَفَرُوْا وَاغْفِرْ لَنَا رَبَّنَا اِنَّكَ اَنْتَ الْعَزِيْزُ الْحَكِيْمُ» — انہیں زبانی یاد کر کے روزانہ پڑھنے کا معمول بنائیں۔"]}]}},"22":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l22-exercise-209",2]],"o":[["mq12-l22-exercise-209",3],["mq12-l22-exercise-209",4],["mq12-l22-exercise-209",5],["mq12-l22-exercise-209",6]],"s":["اللہ کے نزدیک یہ بات سخت ناپسندیدہ ہے کہ تم وہ کہو جو کرتے نہیں — یعنی قول و فعل کا تضاد (الصف 3)۔"],"c":2},{"q":[["mq12-l22-exercise-209",7]],"o":[["mq12-l22-exercise-209",8],["mq12-l22-exercise-209",9],["mq12-l22-exercise-209",10],["mq12-l22-exercise-209",11]],"s":["«بُنْيَانٌ مَّرْصُوْصٌ» — سیسہ پلائی ہوئی دیوار (آیت 4)۔"],"c":0},{"q":[["mq12-l22-exercise-209",12]],"o":[["mq12-l22-exercise-209",13],["mq12-l22-exercise-209",14],["mq12-l22-exercise-209",15],["mq12-l22-exercise-209",16]],"s":["حضرت موسیٰؑ نے قوم سے شکایت کی: اے میری قوم! تم مجھے کیوں ایذا دیتے ہو حالانکہ تم جانتے ہو کہ میں تمہاری طرف اللہ کا رسول ہوں (آیت 5)۔"],"c":2},{"q":[["mq12-l22-exercise-209",17]],"o":[["mq12-l22-exercise-209",18],["mq12-l22-exercise-209",19],["mq12-l22-exercise-209",20],["mq12-l22-exercise-209",21]],"s":["حضرت عیسیٰؑ نے فرمایا: میں اپنے سے پہلے آئی ہوئی تورات کی تصدیق کرنے والا ہوں اور ایک رسول کی خوشخبری دینے والا جو میرے بعد آئے گا جس کا نام احمد ہوگا (آیت 6)۔"],"c":0},{"q":[["mq12-l22-exercise-209",22]],"o":[["mq12-l22-exercise-209",23],["mq12-l22-exercise-209",24],["mq12-l22-exercise-209",25],["mq12-l22-exercise-209",26]],"s":["«هُوَ الَّذِيْ بَعَثَ فِي الْاُمِّيّٖنَ رَسُوْلًا» — اللہ نے اَن پڑھ (امی) لوگوں میں رسول بھیجا (الجمعہ 2)۔"],"c":2},{"q":[["mq12-l22-exercise-209",27]],"o":[["mq12-l22-exercise-209",28],["mq12-l22-exercise-209",29],["mq12-l22-exercise-209",30],["mq12-l22-exercise-209",31]],"s":["«اَسْفَارًا» — کتابیں (الجمعہ 5)۔"],"c":0},{"q":[["mq12-l22-exercise-209",32]],"o":[["mq12-l22-exercise-209",33],["mq12-l22-exercise-209",34],["mq12-l22-exercise-209",35],["mq12-l22-exercise-209",36]],"s":["«تَفِرُّوْنَ» — تم بھاگتے ہو (الجمعہ 8)۔"],"c":1},{"q":[["mq12-l22-exercise-209",37]],"o":[["mq12-l22-exercise-209",38],["mq12-l22-exercise-209",39],["mq12-l22-exercise-209",40],["mq12-l22-exercise-209",41]],"s":["جمعہ کی اذان ہو تو اللہ کے ذکر (خطبہ و نماز) کی طرف دوڑو اور خرید و فروخت چھوڑ دو (الجمعہ 9)۔"],"c":1}],"shortQuestions":[{"q":[["mq12-l22-exercise-209",43]],"s":["اے ایمان والو! تم وہ بات کیوں کہتے ہو جو کرتے نہیں؟ — یعنی قول و فعل کے تضاد سے خبردار کیا گیا؛ یہ اللہ کے نزدیک سخت ناپسندیدہ ہے (الصف 2–3)۔"]},{"q":[["mq12-l22-exercise-209",44]],"s":["اللہ ان لوگوں سے محبت کرتا ہے جو اس کی راہ میں صف باندھ کر اس طرح لڑتے ہیں گویا وہ سیسہ پلائی ہوئی دیوار ہیں — یعنی اتحاد، نظم اور ثابت قدمی (الصف 4)۔"]},{"q":[["mq12-l22-exercise-209",45]],"s":["اللہ نے اپنے رسول کو ہدایت اور دینِ حق کے ساتھ بھیجا تاکہ اسے تمام ادیان پر غالب کر دے، چاہے مشرکوں کو کتنا ہی ناگوار ہو (الصف 9)۔"]},{"q":[["mq12-l22-exercise-209",46]],"s":["اے ایمان والو! اللہ (کے دین) کے مددگار بن جاؤ، جیسے عیسیٰ ابنِ مریمؑ کے حواریوں نے کہا تھا کہ ہم اللہ کے مددگار ہیں (الصف 14)۔"]},{"q":[["mq12-l22-exercise-210",0]],"s":["اللہ کی صفات: الملک (بادشاہ)، القدوس (نہایت پاک)، العزیز (غالب) اور الحکیم (حکمت والا)؛ آسمانوں اور زمین کی ہر چیز اس کی تسبیح کرتی ہے (الجمعہ 1)۔"]},{"q":[["mq12-l22-exercise-210",1]],"s":["نبی ﷺ کے چار منصبی فرائض: (1) اللہ کی آیات پڑھ کر سنانا (تلاوت)؛ (2) لوگوں کا تزکیہ (پاک کرنا)؛ (3) کتاب (قرآن) کی تعلیم؛ (4) حکمت (سنت) کی تعلیم (الجمعہ 2)۔"]},{"q":[["mq12-l22-exercise-210",2]],"s":["یہود اپنے اعمال (گناہوں) کی وجہ سے جو وہ آگے بھیج چکے ہیں کبھی موت کی تمنا نہیں کریں گے، حالانکہ وہ اللہ کے دوست ہونے کا دعویٰ کرتے ہیں؛ اللہ ظالموں کو خوب جانتا ہے (الجمعہ 6–7)۔"]},{"q":[["mq12-l22-exercise-210",3]],"s":["جب جمعہ کی نماز ادا ہو جائے تو زمین میں پھیل جاؤ (کاروبار میں لگ جاؤ)، اللہ کا فضل (رزق) تلاش کرو اور اللہ کو کثرت سے یاد کرو تاکہ تم کامیاب ہو (الجمعہ 10)۔"]}],"longQuestions":[{"q":[["mq12-l22-exercise-210",5]],"s":["ترجمہ: اور اس سے بڑا ظالم کون ہوگا جو اللہ پر جھوٹ باندھے حالانکہ اسے اسلام کی طرف بلایا جا رہا ہو؛ اور اللہ ظالم لوگوں کو ہدایت نہیں دیتا۔ (الصف 7)","تشریح: یہ ان لوگوں کے بارے میں ہے جنہوں نے حضرت عیسیٰؑ کی بشارت (احمد) کے باوجود نبی ﷺ کو جادوگر کہا؛ اللہ پر جھوٹ اور حق کی دعوت کا انکار سب سے بڑا ظلم ہے۔"]},{"q":[["mq12-l22-exercise-210",6]],"s":["سورۃ الصف مدنی سورت ہے؛ اس میں 14 آیات اور 2 رکوع ہیں؛ یہ غزوۂ احد (3ھ) کے آس پاس نازل ہوئی۔","نام: آیت 4 «يُقَاتِلُوْنَ فِيْ سَبِيْلِهٖ صَفًّا» سے نام \"الصف\" (صف) رکھا گیا۔","موضوع: یہ مسبحات میں سے ہے؛ اس میں مسلمانوں کو قول و فعل میں یکسانیت، اتحاد کے ساتھ جہاد اور دینِ حق کی نصرت کی دعوت دی گئی ہے۔"]},{"q":[["mq12-l22-exercise-210",7]],"s":["ترجمہ: حواریوں نے کہا: ہم اللہ (کے دین) کے مددگار ہیں؛ پھر بنی اسرائیل کا ایک گروہ ایمان لایا اور ایک گروہ نے انکار کیا؛ پس ہم نے ایمان والوں کی ان کے دشمنوں کے مقابلے میں مدد کی تو وہ غالب ہو گئے۔ (الصف 14)","تشریح: حواریوں کی طرح اللہ کے دین کی مدد کرنے والوں کو اللہ غلبہ عطا کرتا ہے؛ یہ مسلمانوں کے لیے ترغیب ہے۔"]},{"q":[["mq12-l22-exercise-210",8]],"s":["سورۃ الصف کے بنیادی مضامین: (1) کائنات کی تسبیح؛ (2) قول و فعل کے تضاد کی مذمت؛ (3) صف بستہ ہو کر جہاد کرنے والوں سے اللہ کی محبت؛ (4) حضرت موسیٰؑ کی قوم کی ایذا رسانی اور ان کے دلوں کا ٹیڑھا ہونا۔","(5) حضرت عیسیٰؑ کی تورات کی تصدیق اور \"احمد\" (نبی ﷺ) کی بشارت؛ (6) اللہ کے نور کو پھونکوں سے بجھانے کی ناکام کوشش؛ دینِ حق کے غلبے کا اعلان؛ (7) ایک نفع بخش تجارت — اللہ اور رسول پر ایمان اور مال و جان سے جہاد جس کا بدلہ مغفرت، جنت اور قریبی فتح ہے؛ (8) انصار اللہ بننے کی دعوت اور حواریوں کی مثال۔"]},{"q":[["mq12-l22-exercise-210",9]],"s":["ترجمہ: جن لوگوں کو تورات کا حامل بنایا گیا پھر انہوں نے اسے نہ اٹھایا (اس پر عمل نہ کیا) ان کی مثال گدھے کی سی ہے جس پر کتابیں لدی ہوں؛ ان لوگوں کی مثال بہت بری ہے جنہوں نے اللہ کی آیتوں کو جھٹلایا؛ اور اللہ ظالم لوگوں کو ہدایت نہیں دیتا۔ (الجمعہ 5)","تشریح: علم پر عمل نہ ہو تو وہ گدھے پر لدی کتابوں کی طرح بے فائدہ بوجھ ہے؛ یہ مسلمانوں کے لیے بھی تنبیہ ہے کہ قرآن پڑھیں اور اس پر عمل کریں۔"]},{"q":[["mq12-l22-exercise-210",10]],"s":["سورۃ الجمعہ مدنی سورت ہے؛ اس میں 11 آیات اور 2 رکوع ہیں؛ پہلا رکوع 7ھ (فتحِ خیبر) کے قریب اور دوسرا رکوع ہجرت کے ابتدائی دور میں نازل ہوا۔","نام: آیت 9 «اِذَا نُوْدِيَ لِلصَّلٰوةِ مِنْ يَّوْمِ الْجُمُعَةِ» سے نام \"الجمعہ\" رکھا گیا۔","موضوع: یہ بھی مسبحات میں سے ہے؛ اس میں نبی ﷺ کے منصبی فرائض، یہود کی علمی بے عملی کی مذمت اور جمعہ کے احکام بیان ہوئے؛ نبی ﷺ جمعہ کی نماز میں اکثر یہ سورت اور سورۃ المنافقون پڑھتے تھے۔"]},{"q":[["mq12-l22-exercise-210",11]],"s":["ترجمہ: کہہ دیجیے: جس موت سے تم بھاگتے ہو وہ تمہیں ضرور آ کر ملے گی، پھر تم غائب اور حاضر کے جاننے والے (اللہ) کی طرف لوٹائے جاؤ گے، پھر وہ تمہیں بتا دے گا جو کچھ تم کرتے تھے۔ (الجمعہ 8)","تشریح: موت سے فرار ممکن نہیں؛ عقل مندی یہ ہے کہ انسان موت کے بعد کی زندگی کی تیاری کرے۔"]},{"q":[["mq12-l22-exercise-210",12]],"s":["سورۃ الجمعہ کے بنیادی مضامین: (1) اللہ کی تسبیح اور صفات (الملک، القدوس، العزیز، الحکیم)؛ (2) امی قوم میں رسول کی بعثت اور آپ کے چار فرائض — تلاوت، تزکیہ، تعلیمِ کتاب و حکمت؛ بعد میں آنے والوں کے لیے بھی آپ کی رسالت؛ (3) یہ اللہ کا فضل ہے جسے چاہے دے۔","(4) تورات پر عمل نہ کرنے والے یہود کی گدھے سے مثال؛ اللہ کے دوست ہونے کا دعویٰ اور موت کی تمنا کا چیلنج؛ (5) موت سے فرار ناممکن؛ (6) جمعہ کے احکام — اذان پر ذکر کی طرف دوڑنا، خرید و فروخت چھوڑنا، نماز کے بعد رزق کی تلاش اور کثرتِ ذکر؛ (7) تجارت یا کھیل تماشا دیکھ کر خطبہ چھوڑ کر چلے جانے والوں کو تنبیہ: اللہ کے پاس جو ہے وہ کھیل اور تجارت سے بہتر ہے اور اللہ بہترین رزق دینے والا ہے۔"]}],"activities":[{"q":[["mq12-l22-exercise-210",14],["mq12-l22-exercise-210",15]],"s":["نبی ﷺ کی بعثت کا ذکر قرآن میں دوسری جگہ: «لَقَدْ مَنَّ اللّٰهُ عَلَى الْمُؤْمِنِيْنَ اِذْ بَعَثَ فِيْهِمْ رَسُوْلًا مِّنْ اَنْفُسِهِمْ يَتْلُوْا عَلَيْهِمْ اٰيٰتِهٖ وَيُزَكِّيْهِمْ وَيُعَلِّمُهُمُ الْكِتٰبَ وَالْحِكْمَةَ» (آل عمران 164)؛ نیز حضرت ابراہیمؑ کی دعا: «رَبَّنَا وَابْعَثْ فِيْهِمْ رَسُوْلًا مِّنْهُمْ» (البقرہ 129)؛ اور «وَمَآ اَرْسَلْنٰكَ اِلَّا رَحْمَةً لِّلْعٰلَمِيْنَ» (الانبیاء 107)۔","جمعہ کے سنن، فضائل اور آداب: فضیلت — جمعہ سب سے افضل دن ہے، اسی دن آدمؑ پیدا ہوئے، اس میں ایک گھڑی ہے جس میں دعا قبول ہوتی ہے؛ سنتیں — غسل کرنا، صاف کپڑے پہننا، خوشبو لگانا، مسواک، جلدی مسجد جانا، پیدل جانا، امام کے قریب بیٹھنا، خطبہ خاموشی سے سننا، سورۃ الکہف پڑھنا، کثرت سے درود شریف؛ آداب — لوگوں کی گردنیں نہ پھلانگنا، خطبے کے دوران بات نہ کرنا، اذان کے بعد کاروبار بند کرنا — انہیں اپنے معمولات میں شامل کریں۔"]}]}},"23":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l23-exercise-217",5]],"o":[["mq12-l23-exercise-217",6],["mq12-l23-exercise-217",7],["mq12-l23-exercise-217",8],["mq12-l23-exercise-217",9]],"s":["«وَاللّٰهُ يَشْهَدُ اِنَّ الْمُنٰفِقِيْنَ لَكٰذِبُوْنَ» — اللہ گواہی دیتا ہے کہ منافق جھوٹے ہیں (المنافقون 1)۔"],"c":0},{"q":[["mq12-l23-exercise-218",0]],"o":[["mq12-l23-exercise-218",1],["mq12-l23-exercise-218",2],["mq12-l23-exercise-218",3],["mq12-l23-exercise-218",4]],"s":["«اِتَّخَذُوْٓا اَيْمَانَهُمْ جُنَّةً» — منافقوں نے اپنی قسموں کو ڈھال بنا رکھا ہے (آیت 2)۔"],"c":3},{"q":[["mq12-l23-exercise-218",5]],"o":[["mq12-l23-exercise-218",6],["mq12-l23-exercise-218",7],["mq12-l23-exercise-218",8],["mq12-l23-exercise-218",9]],"s":["«فَطُبِعَ عَلٰى قُلُوْبِهِمْ» — ان کے دلوں پر مہر لگا دی گئی (آیت 3)۔"],"c":2},{"q":[["mq12-l23-exercise-218",10]],"o":[["mq12-l23-exercise-218",11],["mq12-l23-exercise-218",12],["mq12-l23-exercise-218",13],["mq12-l23-exercise-218",14]],"s":["«كَاَنَّهُمْ خُشُبٌ مُّسَنَّدَةٌ» — گویا وہ (دیوار سے) ٹیک لگائی ہوئی سوکھی لکڑیاں ہیں — ظاہر خوبصورت مگر اندر سے کھوکھلے اور بے جان (آیت 4)۔"],"c":0},{"q":[["mq12-l23-exercise-218",15]],"o":[["mq12-l23-exercise-218",16],["mq12-l23-exercise-218",17],["mq12-l23-exercise-218",18],["mq12-l23-exercise-218",19]],"s":["«تُعْلِنُوْنَ» — تم ظاہر کرتے ہو (التغابن 4)۔"],"c":1},{"q":[["mq12-l23-exercise-218",20]],"o":[["mq12-l23-exercise-218",21],["mq12-l23-exercise-218",22],["mq12-l23-exercise-218",23],["mq12-l23-exercise-218",24]],"s":["«يَوْمُ التَّغَابُنِ» — ہار جیت (نفع و نقصان) کا دن، یعنی قیامت (التغابن 9)۔"],"c":2},{"q":[["mq12-l23-exercise-218",25]],"o":[["mq12-l23-exercise-218",26],["mq12-l23-exercise-218",27],["mq12-l23-exercise-218",28],["mq12-l23-exercise-218",29]],"s":["ہمارے رسول کی ذمہ داری صرف واضح طور پر پیغام پہنچا دینا ہے (التغابن 12)۔"],"c":2},{"q":[["mq12-l23-exercise-218",30]],"o":[["mq12-l23-exercise-218",31],["mq12-l23-exercise-218",32],["mq12-l23-exercise-218",33],["mq12-l23-exercise-218",34]],"s":["«اِنَّمَآ اَمْوَالُكُمْ وَاَوْلَادُكُمْ فِتْنَةٌ» — تمہارے مال اور تمہاری اولاد آزمائش ہیں (التغابن 15)۔"],"c":0}],"shortQuestions":[{"q":[["mq12-l23-exercise-218",36]],"s":["منافقوں نے آپ ﷺ کے پاس آ کر کہا: ہم گواہی دیتے ہیں کہ آپ اللہ کے رسول ہیں؛ اللہ جانتا ہے کہ آپ اس کے رسول ہیں مگر اللہ گواہی دیتا ہے کہ منافق (اپنے دعوے میں) جھوٹے ہیں کیونکہ ان کے دل اس کی تصدیق نہیں کرتے (آیت 1)۔"]},{"q":[["mq12-l23-exercise-218",37]],"s":["تنبیہ: یہی (منافق) اصل دشمن ہیں، ان سے بچ کر رہیے؛ اللہ انہیں ہلاک کرے، کہاں الٹے پھرے جا رہے ہیں (آیت 4)۔"]},{"q":[["mq12-l23-exercise-218",38]],"s":["منافقوں کی محرومی: آپ ان کے لیے مغفرت کی دعا کریں یا نہ کریں، ان کے لیے برابر ہے، اللہ انہیں ہرگز نہیں بخشے گا؛ اللہ نافرمان لوگوں کو ہدایت نہیں دیتا (آیت 6)۔"]},{"q":[["mq12-l23-exercise-218",39]],"s":["اے ایمان والو! تمہارے مال اور تمہاری اولاد تمہیں اللہ کے ذکر سے غافل نہ کریں؛ جو ایسا کرے وہی نقصان اٹھانے والے ہیں (آیت 9)۔"]},{"q":[["mq12-l23-exercise-218",40]],"s":["اللہ کا علم: وہ جانتا ہے جو کچھ آسمانوں اور زمین میں ہے، اور جانتا ہے جو تم چھپاتے ہو اور جو ظاہر کرتے ہو؛ اور اللہ دلوں کے بھید بھی جانتا ہے (التغابن 4)۔"]},{"q":[["mq12-l23-exercise-218",41]],"s":["کہہ دیجیے: کیوں نہیں، میرے رب کی قسم! تم ضرور اٹھائے جاؤ گے، پھر تمہیں بتایا جائے گا جو تم نے کیا؛ اور یہ اللہ پر آسان ہے (التغابن 7)۔"]},{"q":[["mq12-l23-exercise-218",42]],"s":["ہدایت: جہاں تک ہو سکے اللہ سے ڈرو، (احکام) سنو اور اطاعت کرو، اور (اللہ کی راہ میں) خرچ کرو، یہ تمہارے اپنے لیے بہتر ہے؛ اور جو اپنے نفس کے بخل سے بچا لیا گیا وہی کامیاب ہیں (التغابن 16)۔"]},{"q":[["mq12-l23-exercise-218",43]],"s":["قرضِ حسنہ کے انعامات: اللہ اسے تمہارے لیے کئی گنا بڑھا دے گا اور تمہیں بخش دے گا؛ اللہ قدر دان اور بردبار ہے (التغابن 17)۔"]}],"longQuestions":[{"q":[["mq12-l23-exercise-219",1]],"s":["ترجمہ: وہ (منافق) کہتے ہیں: اگر ہم مدینہ لوٹ کر گئے تو عزت والا ذلیل کو وہاں سے نکال دے گا؛ حالانکہ عزت تو اللہ، اس کے رسول اور مومنوں ہی کے لیے ہے، مگر منافق نہیں جانتے۔ (المنافقون 8)","تشریح: غزوۂ بنی المصطلق سے واپسی پر رئیس المنافقین عبداللہ بن ابی نے یہ گستاخانہ بات کہی تھی؛ اللہ نے جواب دیا کہ حقیقی عزت اللہ، رسول اور مومنوں کی ہے۔"]},{"q":[["mq12-l23-exercise-219",2]],"s":["سورۃ المنافقون مدنی سورت ہے؛ اس میں 11 آیات اور 2 رکوع ہیں؛ یہ 6ھ میں غزوۂ بنی المصطلق (مریسیع) سے واپسی پر نازل ہوئی۔","نام: پہلی آیت «اِذَا جَآءَكَ الْمُنٰفِقُوْنَ» سے نام \"المنافقون\" رکھا گیا۔","پس منظر: غزوے کے دوران ایک مہاجر اور انصاری میں جھگڑا ہوا تو عبداللہ بن ابی نے انصار کو بھڑکایا اور کہا کہ مدینہ پہنچ کر عزت والا ذلیل کو نکال دے گا؛ حضرت زید بن ارقمؓ نے یہ بات نبی ﷺ تک پہنچائی؛ ابن ابی نے قسمیں کھا کر انکار کیا تو یہ سورت نازل ہو کر زیدؓ کی تصدیق کی گئی۔"]},{"q":[["mq12-l23-exercise-219",3]],"s":["ترجمہ: اور جب کسی جان کا مقررہ وقت آ جاتا ہے تو اللہ اسے ہرگز مہلت نہیں دیتا؛ اور اللہ تمہارے کاموں سے باخبر ہے۔ (المنافقون 11)","تشریح: موت کا وقت مقرر ہے؛ اس لیے موت سے پہلے اللہ کی راہ میں خرچ کر لو، ورنہ انسان کہے گا: اے میرے رب! تو نے مجھے تھوڑی سی مہلت کیوں نہ دی کہ میں صدقہ کرتا (آیت 10)۔"]},{"q":[["mq12-l23-exercise-219",4]],"s":["سورۃ المنافقون کے بنیادی مضامین: (1) منافقین کی جھوٹی گواہی اور جھوٹی قسموں کی ڈھال؛ (2) ایمان کے بعد کفر کی وجہ سے دلوں پر مہر؛ (3) ظاہری خوبصورتی اور چرب زبانی مگر اندر سے کھوکھلی لکڑیوں کی طرح؛ ہر آواز کو اپنے خلاف سمجھنے والے بزدل؛ (4) یہی اصل دشمن ہیں — ان سے ہوشیار رہنا۔","(5) استغفار سے منہ پھیرنا؛ ان کے لیے مغفرت کی دعا بے فائدہ؛ (6) مہاجرین پر خرچ بند کرنے کی سازش — حالانکہ آسمانوں اور زمین کے خزانے اللہ کے ہیں؛ (7) عزت والا ذلیل کو نکالے گا کا جواب — عزت اللہ، رسول اور مومنوں کی ہے؛ (8) مال اور اولاد اللہ کے ذکر سے غافل نہ کریں؛ موت سے پہلے انفاق کی تلقین۔"]},{"q":[["mq12-l23-exercise-219",5]],"s":["ترجمہ: جس دن وہ تمہیں جمع ہونے کے دن (قیامت) کے لیے جمع کرے گا، وہی ہار جیت کا دن ہے؛ اور جو اللہ پر ایمان لائے اور نیک عمل کرے اللہ اس کی برائیاں دور کر دے گا اور اسے ایسے باغوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہیں، وہ ان میں ہمیشہ ہمیشہ رہیں گے؛ یہی بڑی کامیابی ہے۔ (التغابن 9)","تشریح: قیامت کے دن حقیقی نفع و نقصان ظاہر ہوگا — جنتی کامیاب اور دوزخی خسارے میں ہوں گے۔"]},{"q":[["mq12-l23-exercise-219",6]],"s":["سورۃ التغابن مدنی سورت ہے (بعض کے نزدیک مکی)؛ اس میں 18 آیات اور 2 رکوع ہیں؛ یہ ہجرت کے ابتدائی دور میں نازل ہوئی۔","نام: آیت 9 «ذٰلِكَ يَوْمُ التَّغَابُنِ» سے نام \"التغابن\" (ہار جیت) رکھا گیا۔","موضوع: یہ مسبحات میں سے آخری سورت ہے؛ اس میں ایمان، اطاعت اور اخلاق کی دعوت، قیامت کی حقیقت اور مال و اولاد کی آزمائش بیان کی گئی ہے۔"]},{"q":[["mq12-l23-exercise-219",7]],"s":["ترجمہ: اے ایمان والو! تمہاری بیویوں اور اولاد میں سے بعض تمہارے دشمن ہیں، پس ان سے ہوشیار رہو؛ اور اگر تم معاف کر دو، درگزر کرو اور بخش دو تو بے شک اللہ بخشنے والا، مہربان ہے۔ (التغابن 14)","تشریح: جب گھر والے اللہ کی اطاعت (ہجرت، جہاد، انفاق) سے روکیں تو وہ حقیقت میں دشمن کا کام کرتے ہیں؛ ان کی بات نہ مانو مگر ان سے سختی کے بجائے عفو و درگزر کا رویہ اپناؤ۔"]},{"q":[["mq12-l23-exercise-219",8]],"s":["سورۃ التغابن کے بنیادی مضامین: (1) کائنات کی تسبیح اور اللہ کی بادشاہی؛ انسان کی تخلیق اور بہترین صورت؛ (2) اللہ کا علم — ظاہر، باطن اور دلوں کے بھید؛ (3) پچھلی قوموں کا انجام اور رسولوں کا انکار۔","(4) مرنے کے بعد اٹھائے جانے کی حقیقت اور یوم التغابن؛ (5) ہر مصیبت اللہ کے حکم سے؛ اللہ پر ایمان سے دل کی ہدایت؛ اللہ اور رسول کی اطاعت اور توکل۔","(6) بیوی بچوں میں سے بعض کا دشمن ہونا اور عفو و درگزر؛ مال و اولاد کا آزمائش ہونا؛ (7) استطاعت کے مطابق تقویٰ، سننا، اطاعت اور انفاق؛ نفس کے بخل سے بچاؤ؛ قرضِ حسنہ کا اجر؛ اللہ کی صفات — عالم الغیب والشہادۃ، العزیز، الحکیم۔"]}],"activities":[{"q":[["mq12-l23-exercise-219",10],["mq12-l23-exercise-219",11],["mq12-l23-exercise-219",12]],"s":["نفاق کی علامات: حدیث — منافق کی تین نشانیاں ہیں: جب بات کرے جھوٹ بولے، وعدہ کرے تو خلاف کرے اور امانت رکھی جائے تو خیانت کرے (بخاری)؛ قرآن میں: جھوٹی قسمیں، نماز میں سستی اور ریا، ذکر کم کرنا، جہاد سے فرار، مسلمانوں کی مصیبت پر خوشی، کافروں سے دوستی؛ مدینہ کے منافقین کا کردار — عبداللہ بن ابی کی قیادت، غزوۂ احد میں تین سو آدمیوں کی واپسی، واقعۂ افک، مسجدِ ضرار، یہود سے ساز باز؛ انجام — دنیا میں رسوائی اور آخرت میں جہنم کا سب سے نچلا درجہ۔","التغابن 14–18 میں مومنوں کے لیے مفید امور: (1) گھر والوں سے ہوشیار رہنا مگر عفو و درگزر؛ (2) مال اور اولاد کو آزمائش سمجھنا اور اللہ کے پاس اجرِ عظیم کی امید؛ (3) استطاعت کے مطابق تقویٰ؛ (4) سننا اور اطاعت؛ (5) اپنے بھلے کے لیے خرچ کرنا؛ (6) نفس کے بخل سے بچنا؛ (7) اللہ کو قرضِ حسنہ دینا — جس کے بدلے کئی گنا اجر اور مغفرت۔","سورۃ التغابن میں اللہ کی صفات: الملک (بادشاہی اسی کی)، الحمد (تعریف اسی کی)، القدیر (ہر چیز پر قادر)، الخالق، البصیر (دیکھنے والا)، العلیم بذات الصدور (دلوں کا حال جاننے والا)، الغنی (بے نیاز)، الحمید (تعریف کے لائق)، الخبیر، الشکور (قدر دان)، الحلیم (بردبار)، عالم الغیب والشہادۃ، العزیز، الحکیم — طلبہ ان کے معانی پر غور کریں۔"]}]}},"24":{"lang":"ur","items":{"mcqs":[{"q":[["mq12-l24-exercise-228",2]],"o":[["mq12-l24-exercise-228",3],["mq12-l24-exercise-228",4],["mq12-l24-exercise-228",5],["mq12-l24-exercise-228",6]],"s":["«وَاَقِيْمُوا الشَّهَادَةَ لِلّٰهِ» — اللہ کے لیے (ٹھیک ٹھیک) گواہی قائم کرو (الطلاق 2)۔"],"c":1},{"q":[["mq12-l24-exercise-228",7]],"o":[["mq12-l24-exercise-228",8],["mq12-l24-exercise-228",9],["mq12-l24-exercise-228",10],["mq12-l24-exercise-228",11]],"s":["«وَاُولَاتُ الْاَحْمَالِ اَجَلُهُنَّ اَنْ يَّضَعْنَ حَمْلَهُنَّ» — حاملہ عورتوں کی عدت وضعِ حمل (بچے کی پیدائش) تک ہے (آیت 4)۔"],"c":0},{"q":[["mq12-l24-exercise-228",12]],"o":[["mq12-l24-exercise-228",13],["mq12-l24-exercise-228",14],["mq12-l24-exercise-228",15],["mq12-l24-exercise-228",16]],"s":["«اَسْكِنُوْهُنَّ مِنْ حَيْثُ سَكَنْتُمْ» — عدت میں انہیں وہیں رہائش دو جہاں تم خود رہتے ہو، اپنی حیثیت کے مطابق (آیت 6)۔"],"c":2},{"q":[["mq12-l24-exercise-228",17]],"o":[["mq12-l24-exercise-228",18],["mq12-l24-exercise-228",19],["mq12-l24-exercise-228",20],["mq12-l24-exercise-228",21]],"s":["«وَاْتَمِرُوْا بَيْنَكُمْ بِمَعْرُوْفٍ» — آپس میں بھلے طریقے سے مشورہ کر لیا کرو (آیت 6)۔"],"c":0},{"q":[["mq12-l24-exercise-228",22]],"o":[["mq12-l24-exercise-228",23],["mq12-l24-exercise-228",24],["mq12-l24-exercise-228",25],["mq12-l24-exercise-228",26]],"s":["«نَبَّاَتْ» — اس نے خبر دی (التحریم 3)۔"],"c":1},{"q":[["mq12-l24-exercise-228",27]],"o":[["mq12-l24-exercise-228",28],["mq12-l24-exercise-228",29],["mq12-l24-exercise-228",30],["mq12-l24-exercise-228",31]],"s":["«سٰٓئِحٰتٍ» — روزہ رکھنے والیاں (بعض مفسرین کے نزدیک ہجرت کرنے والیاں) (التحریم 5)۔"],"c":3},{"q":[["mq12-l24-exercise-228",32]],"o":[["mq12-l24-exercise-228",33],["mq12-l24-exercise-228",34],["mq12-l24-exercise-228",35],["mq12-l24-exercise-228",36]],"s":["«وَاغْلُظْ عَلَيْهِمْ» — کافروں اور منافقوں پر سختی کیجیے (التحریم 9)۔"],"c":0},{"q":[["mq12-l24-exercise-228",37]],"o":[["mq12-l24-exercise-228",38],["mq12-l24-exercise-228",39],["mq12-l24-exercise-228",40],["mq12-l24-exercise-228",41]],"s":["«وَكَانَتْ مِنَ الْقٰنِتِيْنَ» — حضرت مریمؑ فرمانبرداروں میں سے تھیں (التحریم 12)۔"],"c":1}],"shortQuestions":[{"q":[["mq12-l24-exercise-228",43]],"s":["اے نبی! جب تم (لوگ) عورتوں کو طلاق دو تو ان کی عدت کے (آغاز کے) لیے طلاق دو (یعنی پاکی کے ایسے زمانے میں جس میں صحبت نہ ہوئی ہو)، اور عدت کا شمار رکھو؛ اللہ سے ڈرو؛ نہ انہیں ان کے گھروں سے نکالو نہ وہ خود نکلیں (الطلاق 1)۔"]},{"q":[["mq12-l24-exercise-228",44],["mq12-l24-exercise-228",45]],"n":"کتاب میں سوال (2) اور (3) ایک ہی سطر میں چھپے ہیں، اس لیے دونوں کا جواب یہاں اکٹھا دیا گیا ہے۔","s":["عدت پوری ہونے کے قریب پہنچیں تو یا تو انہیں بھلے طریقے سے (رجوع کر کے) روک لو یا بھلے طریقے سے جدا کر دو، اور اپنے میں سے دو عادل گواہ بنا لو اور اللہ کے لیے گواہی ٹھیک ٹھیک دو (الطلاق 2)۔","تقویٰ کے فوائد (آیات 2–3): جو اللہ سے ڈرے اللہ اس کے لیے (مشکلات سے) نکلنے کا راستہ بنا دیتا ہے اور اسے وہاں سے رزق دیتا ہے جہاں سے اسے گمان بھی نہ ہو؛ اور جو اللہ پر بھروسا کرے وہ اسے کافی ہے۔"]},{"q":[["mq12-l24-exercise-228",46]],"s":["مطلقہ عورتوں کو تنگ کرنے کے لیے تکلیف نہ پہنچاؤ (رہائش اور خرچ میں تنگی نہ کرو)؛ اگر حاملہ ہوں تو وضعِ حمل تک ان پر خرچ کرو (الطلاق 6)۔"]},{"q":[["mq12-l24-exercise-228",47]],"s":["اگر وہ (مطلقہ ماں) تمہارے (بچے) کو دودھ پلائیں تو انہیں ان کی اجرت دو، اور آپس میں بھلے طریقے سے مشورہ کر لو؛ اور اگر تم آپس میں تنگی کرو تو (بچے کو) کوئی دوسری عورت دودھ پلا دے گی (الطلاق 6)۔"]},{"q":[["mq12-l24-exercise-229",0]],"s":["اے ایمان والو! اللہ کے حضور سچی (خالص) توبہ کرو — یعنی گناہ پر ندامت، اسے فوراً چھوڑ دینا اور آئندہ نہ کرنے کا پختہ ارادہ (التحریم 8)۔"]},{"q":[["mq12-l24-exercise-229",1]],"s":["سچی توبہ کرنے والوں کے انعامات: امید ہے کہ تمہارا رب تمہاری برائیاں دور کر دے اور تمہیں ایسے باغوں میں داخل کرے جن کے نیچے نہریں بہتی ہیں؛ اس دن اللہ نبی اور ایمان والوں کو رسوا نہیں کرے گا اور ان کا نور ان کے آگے اور دائیں دوڑ رہا ہوگا (التحریم 8)۔"]},{"q":[["mq12-l24-exercise-229",2]],"s":["حضرت مریمؑ کی صفات: عمران کی بیٹی، جنہوں نے اپنی عصمت کی حفاظت کی (پاک دامن)، تو ہم نے اس میں اپنی روح پھونکی؛ انہوں نے اپنے رب کے کلمات اور اس کی کتابوں کی تصدیق کی؛ اور وہ فرمانبرداروں میں سے تھیں (التحریم 12)۔"]}],"longQuestions":[{"q":[["mq12-l24-exercise-229",4]],"s":["ترجمہ: اور جو اللہ پر بھروسا کرے تو وہ اسے کافی ہے؛ بے شک اللہ اپنا کام پورا کر کے رہتا ہے؛ اللہ نے ہر چیز کے لیے ایک اندازہ مقرر کر رکھا ہے۔ (الطلاق 3)","تشریح: طلاق جیسے مشکل مرحلے میں بھی تقویٰ اور توکل سے کام لینا چاہیے؛ اللہ کی تقدیر میں ہر چیز کا وقت اور اندازہ مقرر ہے، وہ ضرور کفایت کرتا ہے۔"]},{"q":[["mq12-l24-exercise-229",5]],"s":["سورۃ الطلاق مدنی سورت ہے؛ اس میں 12 آیات اور 2 رکوع ہیں؛ یہ سورۃ البقرہ کے طلاق کے احکام کے بعد نازل ہوئی اور انہیں مکمل کرتی ہے؛ اسے \"سورۃ النساء الصغریٰ\" بھی کہا جاتا ہے۔","نام: پہلی آیت «اِذَا طَلَّقْتُمُ النِّسَآءَ» سے نام \"الطلاق\" رکھا گیا۔","موضوع: طلاق کا صحیح طریقہ، عدت کی مدت، مطلقہ کی رہائش و نفقہ اور دودھ پلانے کے احکام، اور ان سب میں تقویٰ کی تاکید۔"]},{"q":[["mq12-l24-exercise-229",6]],"s":["ترجمہ: اللہ نے ان (نافرمان بستیوں) کے لیے سخت عذاب تیار کر رکھا ہے؛ پس اے عقل والو جو ایمان لائے ہو! اللہ سے ڈرو؛ بے شک اللہ نے تمہاری طرف ایک نصیحت (ذکر) نازل کی ہے۔ (الطلاق 10)","تشریح: نافرمان قوموں کا انجام بیان کر کے اہلِ ایمان کو تقویٰ کی تلقین کی گئی؛ ذکر سے مراد قرآن یا رسول ﷺ ہیں جو اندھیروں سے روشنی کی طرف نکالتے ہیں (آیت 11)۔"]},{"q":[["mq12-l24-exercise-229",7]],"s":["سورۃ الطلاق کے بنیادی مضامین: (1) طلاق کا طریقہ — عدت کے لیے (پاکی کے زمانے میں) طلاق اور عدت کا شمار؛ (2) عدت میں عورت کو گھر سے نہ نکالنا سوائے کھلی بے حیائی کے؛ (3) عدت کے بعد بھلے طریقے سے روکنا یا رخصت کرنا اور دو عادل گواہ۔","(4) عدت کی مدتیں — جن کو حیض نہ آتا ہو (بڑی عمر یا نابالغ) ان کی تین ماہ، اور حاملہ کی وضعِ حمل تک؛ (5) مطلقہ کی رہائش، نفقہ اور دودھ پلانے کی اجرت؛ استطاعت کے مطابق خرچ — اللہ کسی پر اس کی طاقت سے زیادہ بوجھ نہیں ڈالتا۔","(6) تقویٰ اور توکل کے فوائد — نکلنے کا راستہ، بے گمان رزق اور کاموں میں آسانی؛ (7) نافرمان بستیوں کا انجام؛ (8) اللہ نے سات آسمان اور ان جیسی زمینیں بنائیں تاکہ تم جان لو کہ اللہ ہر چیز پر قادر ہے اور اس کا علم ہر چیز کو گھیرے ہوئے ہے۔"]},{"q":[["mq12-l24-exercise-229",8]],"s":["ترجمہ: اگر نبی تمہیں طلاق دے دیں تو بعید نہیں کہ ان کا رب انہیں تم سے بہتر بیویاں بدلے میں دے دے — مسلمان، ایمان والیاں، فرمانبردار، توبہ کرنے والیاں، عبادت گزار، روزہ دار، شوہر دیدہ اور کنواریاں۔ (التحریم 5)","تشریح: یہ ازواجِ مطہراتؓ کو تنبیہ تھی جب انہوں نے نبی ﷺ کے خلاف آپس میں تعاون کیا؛ اس میں ایک مثالی بیوی کی صفات بیان ہوئی ہیں۔"]},{"q":[["mq12-l24-exercise-229",9]],"s":["سورۃ التحریم مدنی سورت ہے؛ اس میں 12 آیات اور 2 رکوع ہیں؛ یہ 7ھ یا 8ھ کے قریب نازل ہوئی۔","نام: پہلی آیت «لِمَ تُحَرِّمُ مَآ اَحَلَّ اللّٰهُ لَكَ» سے نام \"التحریم\" رکھا گیا۔","شانِ نزول: نبی ﷺ نے اپنی بعض ازواج کی خوشنودی کے لیے شہد (یا حضرت ماریہؓ) کو اپنے اوپر حرام کر لیا تھا اور ایک راز کی بات ایک زوجہ کو بتائی جو انہوں نے دوسری کو بتا دی؛ اس پر یہ سورت نازل ہوئی کہ اللہ کی حلال کی ہوئی چیز کو حرام نہ کریں اور قسم کا کفارہ ادا کریں۔"]},{"q":[["mq12-l24-exercise-229",10]],"s":["ترجمہ: اے ایمان والو! اپنے آپ کو اور اپنے گھر والوں کو اس آگ سے بچاؤ جس کا ایندھن انسان اور پتھر ہیں، جس پر سخت مزاج، زور آور فرشتے مقرر ہیں جو اللہ کے کسی حکم کی نافرمانی نہیں کرتے اور وہی کرتے ہیں جو انہیں حکم دیا جاتا ہے۔ (التحریم 6)","تشریح: ہر مسلمان اپنی اور اپنے اہل و عیال کی دینی تربیت کا ذمہ دار ہے؛ حدیث: تم میں سے ہر ایک نگہبان ہے اور اپنی رعیت کے بارے میں جواب دہ ہے۔"]},{"q":[["mq12-l24-exercise-229",11]],"s":["سورۃ التحریم کے بنیادی مضامین: (1) اللہ کی حلال کردہ چیز کو اپنے اوپر حرام کرنے کی ممانعت اور قسم کا کفارہ؛ (2) ازواجِ مطہراتؓ کے راز فاش کرنے کا واقعہ اور انہیں توبہ اور تنبیہ؛ اللہ، جبرائیل، نیک مومن اور فرشتے نبی ﷺ کے مددگار۔","(3) اپنے آپ اور اہل و عیال کو جہنم سے بچانے کا حکم؛ (4) کافروں کو قیامت میں عذر پیش کرنے کی ممانعت؛ (5) توبۂ نصوح اور اس کا انعام؛ مومنوں کی دعا «رَبَّنَآ اَتْمِمْ لَنَا نُوْرَنَا»؛ (6) کافروں اور منافقوں سے جہاد اور سختی۔","(7) مثالیں — نوحؑ اور لوطؑ کی کافر بیویاں جنہیں نبیوں کی زوجیت نے فائدہ نہ دیا؛ فرعون کی مومن بیوی (حضرت آسیہؓ) جس نے جنت میں گھر کی دعا کی؛ اور حضرت مریمؑ کی پاک دامنی، تصدیق اور فرمانبرداری — یعنی نجات کا دار و مدار اپنے ایمان اور عمل پر ہے۔"]}],"activities":[{"q":[["mq12-l24-exercise-229",13],["mq12-l24-exercise-229",14],["mq12-l24-exercise-229",15],["mq12-l24-exercise-229",16]],"s":["طلاق کے بنیادی احکام: طلاق ناپسندیدہ ترین حلال ہے؛ مصالحت کی کوشش (ثالث) کے بعد طلاق دی جائے؛ پاکی کی حالت میں جس میں صحبت نہ ہوئی ہو ایک طلاق دینا مسنون ہے؛ رجعی طلاق (ایک یا دو) کے بعد عدت میں رجوع ہو سکتا ہے؛ تین طلاقوں کے بعد حلالۂ شرعیہ کے بغیر دوبارہ نکاح جائز نہیں؛ عدت — تین حیض، جن کو حیض نہ آتا ہو تین ماہ، حاملہ کی وضعِ حمل اور بیوہ کی چار ماہ دس دن؛ عدت میں عورت کو گھر سے نہ نکالا جائے اور اس کا نفقہ شوہر کے ذمے ہے؛ رخصتی سے پہلے طلاق ہو تو عدت نہیں۔","دعا (التحریم 8) ترجمے کے ساتھ: «رَبَّنَآ اَتْمِمْ لَنَا نُوْرَنَا وَاغْفِرْ لَنَا اِنَّكَ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌ» — اے ہمارے رب! ہمارے لیے ہمارا نور پورا کر دے اور ہمیں بخش دے، بے شک تو ہر چیز پر قادر ہے۔","خود کو اور گھر والوں کو جہنم سے بچانے کے کم از کم تین طریقے (التحریم 6): (1) خود فرائض (نماز، روزہ، حلال روزی) کی پابندی اور گناہوں سے بچ کر اچھا نمونہ بننا؛ (2) گھر والوں کو دین کی تعلیم دینا — نماز کی تلقین (بچوں کو سات سال پر نماز کا حکم)، قرآن کی تعلیم اور اچھے اخلاق کی تربیت؛ (3) گھر کا ماحول برائیوں (فحش میڈیا، جھوٹ، غیبت) سے پاک رکھنا اور نیکی کا حکم اور برائی سے روکنا محبت اور حکمت سے کرنا؛ نیز ان کے لیے دعا کرنا۔"]}]}}});
